  // ===== 2026-11-08 E2E-encrypted Bible data sync (owner TG 36957/36977/36978/36980/36987; István T4 signed TG 36993) =====
  "Biblia-adatok szinkronizálása": "Bibeldaten synchronisieren",
  "Titkosítva, csak te tudod megnyitni.": "Verschlüsselt, nur du kannst es öffnen.",
  "Ha bekapcsolod, a jegyzeteid, könyvjelzőid, kiemeléseid, a megtanult versek, az igekártyák, az olvasási tervek és az elolvasottnak jelölt fejezetek, a játékok, a keresési előzmények, a Biblia beállításai, az imacélok és a vezetett ima állása a fiókodon keresztül minden készülékeden és mindkét alkalmazásban (PrepperPapa, Wordlight) megjelennek. Titkosítva tároljuk, és csak te tudod megnyitni a jelmondatoddal; mi nem tudjuk elolvasni. Ha elfelejted a jelmondatot, a szerveren lévő adat nem nyitható meg. Ha nem kapcsolod be, ezek az adatok csak ezen a készüléken vannak meg, és egy másik telefonon akkor sem jelennek meg, ha ugyanazzal a fiókkal lépsz be.": "Wenn du dies einschaltest, erscheinen deine Notizen, Lesezeichen, Markierungen, gelernten Verse, Verskarten, Lesepläne und die als gelesen markierten Kapitel, Spiele, dein Suchverlauf, deine Bibel-Einstellungen, Gebetsziele und der Stand des geführten Gebets über dein Konto auf allen deinen Geräten und in beiden Apps (PrepperPapa, Wordlight). Wir speichern sie verschlüsselt, und nur du kannst sie mit deiner Passphrase öffnen; wir können sie nicht lesen. Wenn du deine Passphrase vergisst, lassen sich die Daten auf dem Server nicht öffnen. Wenn du dies nicht einschaltest, gibt es diese Daten nur auf diesem Gerät, und sie erscheinen auf einem anderen Telefon auch dann nicht, wenn du dich mit demselben Konto anmeldest.",
  "Saját imalista szinkronizálása": "Eigene Gebetsliste synchronisieren",
  "A saját imalistádat, a mások kéréseiből felvetteket is, ugyanígy, titkosítva viszi át a többi készülékedre; csak te tudod megnyitni. Ha nem kapcsolod be, az imalistád csak ezen a készüléken marad.": "Deine eigene Gebetsliste, einschließlich der aufgenommenen Anliegen anderer, wird ebenso verschlüsselt auf deine anderen Geräte übertragen; nur du kannst sie öffnen. Wenn du dies nicht einschaltest, bleibt deine Gebetsliste nur auf diesem Gerät.",
  "Jelmondat": "Passphrase",
  "Adj meg egy jelmondatot a szinkronhoz: egy általad kitalált szót vagy rövid mondatot (legalább 8 karakter és 2 szó, vagy legalább 12 karakter). Ne a neved legyen, és ne a fiókod jelszava. A kis- és nagybetű nem számít.": "Wähle eine Passphrase für die Synchronisierung: ein selbst ausgedachtes Wort oder einen kurzen Satz (mindestens 8 Zeichen und 2 Wörter oder mindestens 12 Zeichen). Nicht dein Name und nicht das Passwort deines Kontos. Groß- und Kleinschreibung spielt keine Rolle.",
  "Tovább": "Weiter",
  "A jelmondat legyen legalább 8 karakter és 2 szó, vagy legalább 12 karakter.": "Die Passphrase muss mindestens 8 Zeichen und 2 Wörter oder mindestens 12 Zeichen lang sein.",
  "A jelmondat ne a neved legyen.": "Die Passphrase darf nicht dein Name sein.",
  "Ezzel a jelmondattal nyithatod meg az adataidat a többi készülékeden. Írd le papírra, és tartsd biztonságos helyen. A telefon nem őrzi meg, és mi sem tudjuk visszaállítani.": "Mit dieser Passphrase öffnest du deine Daten auf deinen anderen Geräten. Schreib sie auf Papier und bewahre sie an einem sicheren Ort auf. Das Telefon speichert sie nicht, und auch wir können sie nicht wiederherstellen.",
  "A jelmondat utolsó négy karaktere (ellenőrzéshez)": "Die letzten vier Zeichen der Passphrase (zur Kontrolle)",
  "Nem egyezik a jelmondat utolsó négy karakterével. Nézd meg újra a leírtat.": "Das stimmt nicht mit den letzten vier Zeichen der Passphrase überein. Sieh dir das Aufgeschriebene noch einmal an.",
  "Add meg a jelmondatot, amelyet a szinkron első bekapcsolásakor választottál.": "Gib die Passphrase ein, die du beim ersten Einschalten der Synchronisierung gewählt hast.",
  "Megnyitás": "Öffnen",
  "Hibás jelmondat.": "Falsche Passphrase.",
  "Elfelejtetted? Kapcsold ki a szinkront azon a készüléken, ahol működik, majd kapcsold be újra, és válassz új jelmondatot.": "Vergessen? Schalte die Synchronisierung auf dem Gerät aus, auf dem sie funktioniert, schalte sie wieder ein und wähle eine neue Passphrase.",
  "Szinkronizálva: {ido}": "Synchronisiert: {ido}",
  "Add meg a jelmondatot a folytatáshoz.": "Gib die Passphrase ein, um fortzufahren.",
  "A szinkront egy másik készülékeden kikapcsoltad. Az adataid ezen a készüléken megmaradtak.": "Du hast die Synchronisierung auf einem anderen Gerät ausgeschaltet. Deine Daten auf diesem Gerät sind erhalten geblieben.",
  "A saját imalista szinkronját egy másik készülékeden kikapcsoltad. Az imalistád ezen a készüléken megmaradt.": "Du hast die Synchronisierung deiner eigenen Gebetsliste auf einem anderen Gerät ausgeschaltet. Deine Gebetsliste auf diesem Gerät ist erhalten geblieben.",
  "Kikapcsolod a szinkront? A szerveren tárolt titkosított Biblia-adataidat töröljük. Ezen és a többi készülékeden minden megmarad, de ott is leáll a szinkron.": "Synchronisierung ausschalten? Wir löschen deine verschlüsselten Bibeldaten auf dem Server. Auf diesem und deinen anderen Geräten bleibt alles erhalten, aber auch dort endet die Synchronisierung.",
  "Kikapcsolod a saját imalista szinkronját? A szerveren tárolt titkosított imalistádat töröljük. A telefonjaidon megmarad.": "Synchronisierung deiner eigenen Gebetsliste ausschalten? Wir löschen deine verschlüsselte Gebetsliste auf dem Server. Auf deinen Telefonen bleibt sie erhalten.",
  "A kikapcsolás most nem sikerült, mert a szervert nem értük el. Próbáld újra később.": "Das Ausschalten hat gerade nicht geklappt, weil der Server nicht erreichbar war. Versuche es später noch einmal.",
  "A szinkron kikapcsolva, a szerveren tárolt adatok törölve.": "Synchronisierung ausgeschaltet, die auf dem Server gespeicherten Daten gelöscht.",
  "Egy pillanat…": "Einen Moment…",
