  "Az alkalmazást egyetlen fájlba mentheted, és internet nélkül telepítheted egy másik Android telefonra. A saját adataid nincsenek benne: azokat a Teljes mentés viszi át, titkosítva.": "Du kannst die App in eine einzige Datei speichern und ohne Internet auf einem anderen Android-Telefon installieren. Deine eigenen Daten sind nicht darin: Die übernimmt die Vollständige Sicherung, verschlüsselt.",
  "Letöltött tartalom": "Heruntergeladene Inhalte",
  "A letöltött tartalmat külön fájlba mentheted, így a másik telefonnak nem kell újra letöltenie.": "Du kannst die heruntergeladenen Inhalte in eine eigene Datei speichern, damit das andere Telefon sie nicht erneut herunterladen muss.",
  "Tartalom mentése fájlba": "Inhalte in eine Datei speichern",
  "Ezen a telefonon még nincs letöltött tartalom.": "Auf diesem Telefon gibt es noch keine heruntergeladenen Inhalte.",
  "Tartalom betöltése fájlból": "Inhalte aus einer Datei laden",
  "Hogyan telepítsem a másik telefonra?": "Wie installiere ich sie auf dem anderen Telefon?",
