  "A másik telefonon nyisd meg az .apk fájlt a Fájlok alkalmazásban, és koppints a Telepítés gombra. Ha a telefon kéri, egyszer engedélyezd az „Ismeretlen alkalmazások telepítése” beállítást annak az alkalmazásnak, amellyel a fájlt megnyitottad.": "Öffne auf dem anderen Telefon die .apk-Datei in der App „Dateien“ und tippe auf Installieren. Wenn das Telefon fragt, erlaube einmal „Unbekannte Apps installieren“ für die App, mit der du die Datei geöffnet hast.",
  "Indítsd el az alkalmazást, nyisd meg a Beállítások, Adatok és mentés részt, koppints a „Tartalom betöltése fájlból” gombra, és válaszd ki a .pptartalom fájlt.": "Starte die App, öffne Einstellungen, Daten und Sicherung, tippe auf „Inhalte aus einer Datei laden“ und wähle die .pptartalom-Datei.",
  "Végül a saját adataidat a Teljes mentés fájljából töltsd vissza a Visszatöltés gombbal, a mentési kulcsoddal.": "Stelle zuletzt deine eigenen Daten aus der Datei der Vollständigen Sicherung mit der Schaltfläche Wiederherstellen und deinem Sicherungsschlüssel wieder her.",
