  // ===== 2026-11-02 Gerah escrow + weekly goal (owner TG 33434/33435, decision A TG 1322, card 8ed3c59e; the daily item is the signed wording) =====
  "Napi Bibliaolvasás, heti céllal. Minden nap, amikor eléred a napra beállított olvasási célodat, Gerah kerül letétbe a cél hossza szerint: legalább 10 perces cél után 1, legalább 20 perces után 2, legalább 30 perces után 3; az 5 perces cél után nem jár. Naponta legfeljebb 3 gerah. A letét akkor kerül a tárcádba, ha 7 egymást követő napon eléred a napi célodat. Ha egy nap kimarad, a letét elvész, és a hét nap elölről indul. A Gerah-t a PrepperPapa alkalmazás tárcája tárolja: a Wordlightban végzett olvasásért akkor jár, ha nálad telepítve van a PrepperPapa alkalmazás. A reggeli ébresztős felolvasás is beleszámít.": "Tägliches Bibellesen mit Wochenziel. An jedem Tag, an dem du das für diesen Tag eingestellte Leseziel erreichst, wird Gerah nach der Länge des Ziels hinterlegt: 1 für ein Ziel von mindestens 10 Minuten, 2 für mindestens 20 Minuten, 3 für mindestens 30 Minuten; ein 5-Minuten-Ziel bringt keine. Höchstens 3 gerah pro Tag. Die hinterlegte Gerah kommt in deine Brieftasche, wenn du dein Tagesziel an 7 aufeinanderfolgenden Tagen erreichst. Fällt ein Tag aus, verfällt die Hinterlegung, und die 7 Tage beginnen von vorn. Die Gerah wird in der Brieftasche der PrepperPapa-App aufbewahrt: Für das Lesen in Wordlight bekommst du sie nur, wenn die PrepperPapa-App auf deinem Gerät installiert ist. Die Lesung des Morgenweckers zählt mit.",
  "Napi Bibliaolvasás, heti céllal: minden nap, amikor eléred a napra beállított olvasási célodat (legalább {p} perc), 1 gerah kerül letétbe. A letét akkor kerül a tárcádba, ha {h} egymást követő napon eléred a napi célodat; ha egy nap kimarad, a letét elvész, és a {h} nap elölről indul. A reggeli ébresztős felolvasás is beleszámít.": "Tägliches Bibellesen mit Wochenziel: An jedem Tag, an dem du das für diesen Tag eingestellte Leseziel erreichst (mindestens {p} Minuten), wird 1 gerah hinterlegt. Die Hinterlegung kommt in deine Brieftasche, wenn du dein Tagesziel an {h} aufeinanderfolgenden Tagen erreichst; fällt ein Tag aus, verfällt die Hinterlegung, und die {h} Tage beginnen von vorn. Die Lesung des Morgenweckers zählt mit.",
  "Ma {n} gerah-t letétbe helyeztünk. Heti cél: {k} / {h} nap.": "Heute wurde {n} gerah hinterlegt. Wochenziel: {k} / {h} Tage.",
  "Heti cél teljesítve: {n} gerah a tárcádba került!": "Wochenziel erreicht: {n} gerah sind in deine Brieftasche gekommen!",
  "heti bibliaolvasási cél": "Wochenziel Bibellesen",
