  "Kimaradt egy nap: ez a letét elvész. A következő olvasott nappal a {h} nap elölről indul.": "Ein Tag ist ausgefallen: diese Hinterlegung verfällt. Mit deinem nächsten Lesetag beginnen die {h} Tage von vorn.",
