  "Még nem tudom, hol vagy. Nyomd meg a „Mérés a helyzetemre” gombot, vagy add meg kézzel.": "Ich weiß noch nicht, wo du bist. Tippe auf „Für meinen Standort berechnen“ oder gib ihn manuell ein.",
