  "megálló": "Halt",
  "mérés az elmúlt 48 órából. A telefon légnyomás-szenzora automatikusan méri; kézzel is bevihetsz értéket.": "Messungen der letzten 48 Stunden. Der Drucksensor des Telefons misst automatisch; du kannst Werte auch von Hand eingeben.",
  "nincs ismert": "nicht bekannt",
  "nincs megadva": "nicht angegeben",
  "válassz könyvet": "wähle ein Buch",
  "összesen": "insgesamt",
  "A többiek a „Szobák a hálón\" listában magától látják a szobát. Ha valakinél mégsem jelenik meg, ezt a címet írja be a „Csatlakozás más szobájához\" gombbal.": "Die anderen sehen den Raum automatisch in der Liste „Räume im Netz“. Wenn er bei jemandem nicht erscheint, gibt er diese Adresse über „Einem anderen Raum beitreten“ ein.",
  "Másik cím": "Andere Adresse",
  "A szoba címe": "Adresse des Raums",
  "Vissza a saját szobámba": "Zurück in meinen Raum",
  "Fénykép": "Foto",
  "Jóváírva.": "Gutgeschrieben.",
  "küldött neked": "hat dir gesendet",
  "Gerah küldése neki": "Gerah senden",
  // ===== 2026-10-11 22:3x: gira-kozosseg a gazda dontese =====
  "A szoba gazdája Gerah-közösségnek jelölte: a telefonod magától részt vesz.": "Der Raumverwalter hat ihn als Gerah-Gemeinschaft markiert: dein Telefon nimmt automatisch teil.",
  "Ezt a szoba gazdája kapcsolja be; még nem jelölte Gerah-közösségnek.": "Das schaltet der Raumverwalter ein; noch nicht als Gerah-Gemeinschaft markiert.",
  "Bekapcsolva a szoba minden tagjának. Átküldöm a Gerah-könyvet…": "Für alle Mitglieder des Raums eingeschaltet. Das Gerah-Buch wird gesendet…",
  "Kikapcsolva a szoba minden tagjának.": "Für alle Mitglieder des Raums ausgeschaltet.",
  "A szoba gazdája kapcsolja be; ilyenkor minden tag telefonja magától átküldi ide a Gerah-könyvét, és innen fogadja a többiekét. A szoba minden tagja látja a Gerah-mozgásokat.": "Der Raumverwalter schaltet es ein; dann sendet jedes Mitgliedstelefon sein Gerah-Buch automatisch hierher und empfängt die der anderen. Alle Mitglieder sehen die Gerah-Bewegungen.",
  // ===== 2026-10-11 22:2x: LoRa a radio-kalkulatorban =====
  "LoRa (868 MHz) — engedély nélküli adatrádió": "LoRa (868 MHz) — genehmigungsfreier Datenfunk",
  "Engedély nélkül használható: alapból 25 mW, a 869,4-869,65 MHz-es alsávon 500 mW, korlátozott adásidővel. Nem beszéd, hanem rövid szöveges üzenet; cserébe kis teljesítménnyel is kilométereket visz, mert a zaj alatt is vesz. A telefon nem tud LoRát: egy LoRa-egység kell, amihez a telefon Bluetooth-on csatlakozik.": "Genehmigungsfrei: standardmäßig 25 mW, im Teilband 869,4-869,65 MHz 500 mW, mit begrenzter Sendezeit. Keine Sprache, sondern kurze Textnachrichten; dafür reicht es mit wenig Leistung kilometerweit, weil es unter dem Rauschen empfängt. Telefone können kein LoRa: Man braucht eine LoRa-Einheit, mit der sich das Telefon per Bluetooth verbindet.",
  // ===== 2026-10-11 21:4x: gira minusz-hatar =====
  "ennyit fizethetsz most": "jetzt zahlbar",
  "Ez túllépné a mínusz-határodat.": "Das würde dein Minuslimit überschreiten.",
  "Most legfeljebb ennyit fizethetsz:": "Höchstens jetzt zahlbar:",
  "határ": "Limit",
  "Mínuszba mehetsz": "Du kannst ins Minus bis",
  "gerah-ig": "Gerah",
  "most ennyit fizethetsz": "jetzt zahlbar",
  // ===== 2026-10-11 21:3x: gira-egyenleg az urlapon =====
  "Egyenleged": "Dein Guthaben",
  "a Gerah nem mehet mínuszba, ezért fizetni akkor tudsz, ha előbb kapsz valakitől.": "Gerah kann nicht ins Minus gehen, du kannst also erst zahlen, wenn du vorher etwas bekommen hast.",
  "Ennyi Gerah-d nincs. Egyenleged:": "So viel Gerah hast du nicht. Dein Guthaben:",
  "A Gerah nem mehet mínuszba: előbb kapnod kell valakitől.": "Gerah kann nicht ins Minus gehen: du musst erst etwas bekommen.",
  // ===== 2026-10-11 21:3x: legnyomas-kartya, mozgas-szures =====
  "Járműben vagy (a GPS szerint 15 km/h felett): a riasztás szünetel, mert ilyenkor a nyomás az emelkedőtől és a szellőzéstől is változik.": "Du bist im Fahrzeug (laut GPS über 15 km/h): der Alarm pausiert, weil sich der Druck dann auch durch Steigungen und Lüftung ändert.",
  "Magasság-korrekcióval: közben": "Höhenkorrigiert: inzwischen",
