  "Fordulj a kívánt irányba, és nyomd meg: Irány felvétele.": "Richte dich in die gewünschte Richtung und drücke: Richtung erfassen.",
  "Állítsd fel a telefont: álló módban a hátsó kamera irányát mérjük, fektetve ez nem pontos.": "Halte das Telefon aufrecht: im Hochkant-Modus messen wir die Richtung der Rückkamera, flach liegend ist das ungenau.",
  "Álló mód: a hátsó kamera iránya számít. A keret zöld, ha a felvett irányba nézel, és piros, ha nem.": "Hochkant-Modus: es zählt die Richtung der Rückkamera. Der Rahmen ist grün, wenn du in die erfasste Richtung schaust, sonst rot.",
