    "Bei ihm/ihr wird es automatisch gutgeschrieben, und die Quittung kommt auch automatisch zurück.",
  "A szobába most nem ment el (nincs kapcsolat vagy kulcs). Itt a QR, ezzel is átadhatod.":
    "Konnte gerade nicht in den Raum gesendet werden (keine Verbindung oder kein Schlüssel). Hier ist der QR-Code, damit kannst du es auch übergeben.",
