    "Kapazität (mAh)",
  "Hány elem/akku (párhuzamosan összeadódó kapacitás)":
    "Wie viele Zellen (parallel addiert sich die Kapazität)",
  "A gyártói adat a fényerő NÉVLEGES üzemideje — a valóságban a hideg, az elem életkora és a fokozatos elhalványulás ennél mindig kevesebbet ad. A saját megadásos számításnál a névleges kapacitásból 15 százalékot levonunk erre.":
    "Die Herstellerangabe ist die NENN-Laufzeit für diese Helligkeit; in der Praxis geben Kälte, Batteriealter und allmähliches Nachlassen immer weniger her. In der manuellen Rechnung ziehen wir dafür 15 Prozent von der Nennkapazität ab.",
  "Ezt látják a többiek":
    "Das sehen die anderen",
  "minden szobában":
    "in jedem Raum",
  ". Egy nevet használ a rendszer; a szobába lépéskor ezt kérdezi meg, ha még nincs megadva.":
    ". Das System verwendet einen Namen; es fragt danach beim Betreten eines Raums, wenn er noch nicht gesetzt ist.",
