  "Amit vészhelyzetben tudni kell róla (nem kötelező)": "Was man im Notfall über diese Person wissen muss (optional)",
  "Ez a közös titok. Aki ismeri, az olvassa a kódjaidat, aki nem, annak értelmetlen betűsor. Add meg ugyanazt a jelszót azon a készüléken is, amelyik olvasni fogja.": "Das ist das gemeinsame Geheimnis. Wer es kennt, liest deine Codes; für alle anderen ist es eine sinnlose Zeichenfolge. Gib dasselbe Passwort auch auf dem Gerät ein, das sie lesen wird.",
  "PIN beállítása": "PIN festlegen",
