  "Morze és fax": "Morse und Fax",
  "Feloldva ezen a készüléken:": "Auf diesem Gerät freigeschaltet:",
  "Ezen a készüléken még nincs feloldott modul.": "Auf diesem Gerät ist noch kein Modul freigeschaltet.",
  "Ezt látják a többiek. Ugyanaz, mint a helyi szobában.": "Das sehen die anderen. Dasselbe wie im lokalen Raum.",
  "Előbb vedd fel a Háztartásnál, kik vagytok — a lista onnan jön.": "Trag zuerst unter „Haushalt\" ein, wer ihr seid — die Liste kommt von dort.",
  "Előbb vedd fel a Háztartásnál, kik vagytok. A lista abból dolgozik.": "Trag zuerst unter „Haushalt\" ein, wer ihr seid. Die Liste arbeitet mit diesen Daten.",
  "Előbb vegyél fel helyszínt a Háztartásnál. Alapesetben az otthon az első.": "Trag zuerst einen Ort unter „Haushalt\" ein. Standardmäßig steht das Zuhause an erster Stelle.",
  "A törlés itt van, nem a listában — hogy ne lehessen véletlenül megnyomni.": "Das Löschen ist hier, nicht in der Liste — damit man es nicht versehentlich drückt.",
  "A mentős beolvashatja. Az adat a QR-ben van, nem megy szerverre.": "Der Rettungsdienst kann es scannen. Die Daten stecken im QR-Code und gehen nicht an einen Server.",
  "Egészségügyi vészhelyzeti adatok. A mentős beolvashatja (nyílt QR). Helyben tárolva.": "Medizinische Notfalldaten. Der Rettungsdienst kann sie scannen (offener QR). Lokal gespeichert.",
  "Egészségügyi adatok (nem kötelező, de ebből tudjuk, mi kell a csomagba)": "Gesundheitsdaten (optional, aber daraus wissen wir, was ins Paket gehört)",
  "Allergia (koppints, amennyi kell — a mezőbe írja be, ott át is írhatod)": "Allergie (so oft tippen wie nötig — wird ins Feld geschrieben, dort auch änderbar)",
