  "Tárolási hely (több is lehet)": "Lagerort (mehrere möglich)",
  "A koordináta többféle alakban mehet:": "Die Koordinaten können in verschiedenen Formaten eingegeben werden:",
  "Három rövid jel, szünet, ismétlés — ez a nemzetközi vészjelzés. Hangosabban és tovább hallatszik, mint a kiabálás.": "Drei kurze Signale, Pause, Wiederholung — das ist das internationale Notsignal. Es ist lauter und weiter hörbar als Rufen.",
  "A kód alatti betűsor UGYANEZ az adat. Faxon a képet küldd, morzével a betűsort.": "Die Zeichenfolge unter dem Code enthält DIESELBEN Daten. Per Fax sende das Bild, per Morse die Zeichenfolge.",
  "A lejátszás ugyanazzal a gombbal indul és áll. Nincs külön Állj gomb — ha újra rákoppintasz, leáll.": "Die Wiedergabe startet und stoppt mit derselben Taste. Es gibt keine eigene Stopp-Taste — tippe erneut, und sie hält an.",
  "A wattóra és a watt nem ugyanaz, és ezt szokás összekeverni.": "Wattstunde und Watt sind nicht dasselbe, und das wird oft verwechselt.",
  "A wattóra (Wh) azt mondja meg, MEDDIG megy; a watt (W) azt, hogy MIT tudsz egyáltalán ráakasztani. Egy 2000 wattórás gép sem indít el egy 2000 wattos vízforralót, ha csak 600 wattot tud leadni — akkor sem, ha tele van.": "Die Wattstunde (Wh) sagt, WIE LANGE es läuft; das Watt (W), WAS du überhaupt anschließen kannst. Auch ein Gerät mit 2000 Wattstunden startet keinen Wasserkocher mit 2000 Watt, wenn es nur 600 Watt abgeben kann — selbst voll geladen nicht.",
  "Helyszínenként: kik érkeznek oda, hány napra, és elég-e az ott lévő víz és élelem.": "Pro Ort: wer dort ankommt, für wie viele Tage, und ob das dort vorhandene Wasser und Essen reicht.",
  "Telepítés a kezdőképernyőre": "Zum Startbildschirm hinzufügen",
  "Nemzetközi vészjelzés Morzéval: SOS (··· ─── ···), folyamatosan ismételve. Fénnyel, hang nélkül — a hangjelzés lent külön van, mert az mást tud.": "Internationales Notsignal in Morsecode: SOS (··· ─── ···), fortlaufend wiederholt. Mit Licht, ohne Ton — das Tonsignal steht unten separat, denn es kann etwas anderes.",
  "TEKERD FEL A HANGERŐT. Az app a telefon hangerejét nem tudja felülírni, tehát ha az le van halkítva, a síp is halk lesz.": "DREH DIE LAUTSTÄRKE AUF. Die App kann die Lautstärke des Telefons nicht überschreiben; ist sie leise gestellt, bleibt auch die Pfeife leise.",
  "Hz. A 3-4 kHz a legjobban hallható tartomány, ezért sípol ott a mentőmellény sípja is.": "Hz. 3-4 kHz ist der am besten hörbare Bereich, deshalb pfeift auch die Pfeife der Rettungsweste dort.",
  "Percenként 110 koppanás. Nyomd a mellkas közepét a koppanás ütemére, körülbelül 5-6 centit, és hagyd teljesen visszaemelkedni.": "110 Schläge pro Minute. Drücke die Mitte des Brustkorbs im Takt, etwa 5-6 Zentimeter tief, und lass ihn vollständig zurückkommen.",
  "Ez ütemadó, nem oktatás. Mentő: 112. Ha van a közelben defibrillátor, valaki hozza, de te ne hagyd abba.": "Das ist ein Taktgeber, keine Ausbildung. Rettungsdienst: 112. Wenn ein Defibrillator in der Nähe ist, soll ihn jemand holen, aber hör du nicht auf.",
  "— egységes európai segélyhívó (mentő, tűzoltó, rendőrség). Térerő nélkül is hívható, ha van bármilyen hálózat a közelben.": "— einheitliche europäische Notrufnummer (Rettung, Feuerwehr, Polizei). Auch ohne eigenen Netzempfang wählbar, wenn irgendein Netz in der Nähe ist.",
  "A vészkártyád (vércsoport, allergia, gyógyszerek, kontakt) itt jelenik meg gyorsan. Töltsd ki a": "Deine Notfallkarte (Blutgruppe, Allergie, Medikamente, Kontakt) erscheint hier schnell. Fülle sie im Abschnitt",
  "szekcióban.": "aus.",
  "Írj be szöveget, játszd le hangként vagy fénnyel, vagy vegyél kamerával/mikrofonnal.": "Gib Text ein, spiel ihn als Ton oder Licht ab, oder empfange ihn mit Kamera/Mikrofon.",
  "Próbaidő: még 14 nap. A lejárat után sem áll le semmi.": "Testzeitraum: noch 14 Tage. Auch nach Ablauf wird nichts abgeschaltet.",
  "Szöveg": "Text",
  "Sebesség:": "Geschwindigkeit:",
  "Ismétlés (folyamatos)": "Wiederholung (fortlaufend)",
  "Lejátszás": "Wiedergabe",
  "Villogtatás (Lejátszás és SOS is):": "Blinken (Wiedergabe und SOS):",
  "Képernyő": "Bildschirm",
  "Vaku": "Blitz",
  "Mindkettő": "Beides",
  "Vétel: KAMERA (fény → szöveg)": "Empfang: KAMERA (Licht → Text)",
  "Kamera vétel indítása": "Kameraempfang starten",
  "Nagyítás (távoli fényhez):": "Zoom (für entferntes Licht):",
  "Indítsd, és irányítsd a kamerát egy Morzét villogó fényre (pl. egy másik telefon vakuja). A háttér legyen sötét, a fény a kép KÖZEPÉN. A fény-küszöb magától hangolódik; a \"Fényerő\" sáv és a lámpa mutatja, mit lát. A \"Vétel sebesség\" csúszkát állítsd a vett Morze tempójához, amíg tisztán jönnek a betűk.": "Starte und richte die Kamera auf ein Licht, das Morsecode blinkt (z. B. den Blitz eines anderen Telefons). Der Hintergrund sollte dunkel sein, das Licht in der MITTE des Bildes. Die Lichtschwelle stellt sich selbst ein; der Balken \"Helligkeit\" und die Lampe zeigen, was erkannt wird. Stelle den Regler \"Empfangsgeschwindigkeit\" auf das Tempo des empfangenen Morsecodes, bis die Buchstaben sauber ankommen.",
  "Vétel: MIKROFON (hang → szöveg)": "Empfang: MIKROFON (Ton → Text)",
  "Mikrofon vétel indítása": "Mikrofonempfang starten",
  "FONTOS: külön eszközről vedd (az egyik telefon lejátssza, a másikon fut a vétel) -- ugyanazon a telefonon a mikrofon foglalása miatt a lejátszás halkul. Tartsd a Morze-hangot a mikrofon közelébe. Csendes környezet a legjobb; a hangerő-sáv és a lámpa mutatja, mit hall. Kalibrálás: a \"Vétel sebesség\" csúszkát told lassan, amíg a szövegben tisztán, hibátlanul jönnek a betűk.": "WICHTIG: Empfange von einem separaten Gerät (ein Telefon spielt ab, auf dem anderen läuft der Empfang) -- auf demselben Telefon wird die Wiedergabe leiser, weil das Mikrofon belegt ist. Halte den Morseton nah ans Mikrofon. Eine ruhige Umgebung ist am besten; der Lautstärkebalken und die Lampe zeigen, was gehört wird. Kalibrierung: Schiebe den Regler \"Empfangsgeschwindigkeit\" langsam, bis die Buchstaben im Text sauber und fehlerfrei ankommen.",
  "Tanuló: Morze → szöveg (kézi: illeszd be . és -, szóköz a betűk közt, / a szavak közt)": "Lernmodus: Morse → Text (manuell: . und - einfügen, Leerzeichen zwischen Buchstaben, / zwischen Wörtern)",
  "Kép küldése hangként (Martin M1). Játszd egy másik telefon SSTV-vevőjébe vagy egy rádió mikrofonjába.": "Bild als Ton senden (Martin M1). Spiel es in den SSTV-Empfänger eines anderen Telefons oder in das Mikrofon eines Funkgeräts.",
  "Mód": "Modus",
  "Martin M1 (320×256, működik)": "Martin M1 (320×256, funktioniert)",
  "Robot36 (hamarosan)": "Robot36 (bald)",
  "Scottie S1 (hamarosan)": "Scottie S1 (bald)",
  "PD120 (hamarosan)": "PD120 (bald)",
  "Kép": "Bild",
  "Kódolás és lejátszás": "Kodieren und abspielen",
  "Küldéshez: a másik eszközön indíts SSTV-vevőt (pl. Robot36 vagy MMSSTV) Martin M1 módban, és tartsd a hangszórót a mikrofonjához. A VIS-fejléc automatikus, a vevő magától felismeri a módot. Egy kép ~114 másodperc.": "Zum Senden: Starte auf dem anderen Gerät einen SSTV-Empfänger (z. B. Robot36 oder MMSSTV) im Modus Martin M1 und halte den Lautsprecher an dessen Mikrofon. Der VIS-Header wird automatisch gesendet, der Empfänger erkennt den Modus selbst. Ein Bild dauert etwa 114 Sekunden.",
  "Vétel (hang → kép)": "Empfang (Ton → Bild)",
  "Vétel indítása": "Empfang starten",
  "Martin M1-et fogad. Tartsd a telefont a hangszóró vagy a rádió közelébe, és a kép soronként épül fel. Csendes környezet kell hozzá: a mikrofon minden mást is hall. Hangfájlból is megy, ha valaki felvételt küld.": "Empfängt Martin M1. Halte das Telefon nah an den Lautsprecher oder das Funkgerät, und das Bild baut sich Zeile für Zeile auf. Dafür ist eine ruhige Umgebung nötig: Das Mikrofon hört auch alles andere. Funktioniert auch aus einer Audiodatei, wenn jemand eine Aufnahme schickt.",
  "Készletezés": "Vorratshaltung",
