  "· vagy egy bemásolt Google Térkép-link. Ha nem tudom értelmezni, szólok — üresen nem mentem el.": "· oder ein eingefügter Google-Maps-Link. Wenn ich ihn nicht deuten kann, sage ich Bescheid — leer speichere ich ihn nicht.",
