  "Egy powerbank a telefonhoz kevés, ha a router és a lámpa is menne. Nézd meg, mekkora kapacitás kell három napra.": "Eine Powerbank für das Telefon reicht nicht, wenn auch Router und Lampe laufen sollen. Sieh nach, welche Kapazität für drei Tage nötig ist.",
  "A nyílt lángú fűtés zárt térben szén-monoxidot termel. Ha bent fűtesz, CO-érzékelő nem opció, hanem alapfelszerelés.": "Heizen mit offener Flamme erzeugt in geschlossenen Räumen Kohlenmonoxid. Wenn du drinnen heizt, ist ein CO-Melder keine Option, sondern Grundausstattung.",
  "Napi három liter fejenként, csak ivásra. Mellé egy szűrő vagy klórtabletta, ha a csapvíz eredete kétségessé válik.": "Drei Liter pro Person und Tag, nur zum Trinken. Dazu ein Filter oder Chlortabletten, falls die Herkunft des Leitungswassers zweifelhaft wird.",
  "Fejlámpa, hogy szabad maradjon a két kezed, és tartalék elem hozzá. A gyertya tűzveszély, nem megoldás.": "Eine Stirnlampe, damit beide Hände frei bleiben, und Ersatzbatterien dazu. Die Kerze ist eine Brandgefahr, keine Lösung.",
  "— ennyi jut ténylegesen a fűtésbe,": "— so viel kommt tatsächlich beim Heizen an,",
  "A fűtés a tüzelőanyag mennyiségéből számol, darabonként grammban vagy milliliterben (egy 11 kg-os gázpalack = 11000). Most {g} {egyseg}/db van megadva, így ez a tétel a fűtésbe alig vagy egyáltalán nem számít bele.": "Die Heizung wird aus der Brennstoffmenge berechnet, pro Stück in Gramm oder Milliliter (eine 11-kg-Gasflasche = 11000). Jetzt sind {g} {egyseg}/Stk. eingetragen, daher zählt dieser Posten kaum oder gar nicht zur Heizung.",
  "OK = mégis így mentem.": "OK = trotzdem speichern.",
  "Mentve. Figyelem: {g} {egyseg}/db tüzelőanyag a fűtésbe alig számít. A mennyiséget darabonként grammban vagy milliliterben kérjük (egy 11 kg-os gázpalack = 11000).": "Gespeichert. Achtung: {g} {egyseg}/Stk. Brennstoff zählt kaum zur Heizung. Bitte die Menge pro Stück in Gramm oder Milliliter angeben (eine 11-kg-Gasflasche = 11000).",
