  "A készülék készít egy kulcspárt. A titkos kulcs csak a titkosított mentésbe kerül bele. Ezzel írod alá a fizetéseidet, és ezért nem tud más a nevedben fizetni.": "Das Gerät erzeugt ein Schlüsselpaar. Der geheime Schlüssel kommt nur in die verschlüsselte Sicherung. Damit signierst du deine Zahlungen, deshalb kann niemand anders in deinem Namen zahlen.",
