  ": nincs megadva a testtömeg, 15 kg-mal számoltam. Az adatlapján javítható.": ": Das Körpergewicht ist nicht angegeben, ich habe mit 15 kg gerechnet. Korrigieren kannst du es im Datenblatt.",
