  "liter megy veletek. A többit útközben kell megszerezni és tisztítani.": "Liter gehen mit euch. Den Rest müsst ihr unterwegs beschaffen und aufbereiten.",
  "Csak azzal számol, amit elbírsz: 1,5 liter fejenként. Ez túrához való, és a listán kiírom, mennyit kell útközben szerezni.": "Rechnet nur mit dem, was du tragen kannst: 1,5 Liter pro Person. Das ist für eine Tour gedacht, und in der Liste schreibe ich aus, wie viel unterwegs beschafft werden muss.",
  "Jelöld ki, ki megy. Enélkül nem tudom kiszámolni, mennyi kell.": "Markiere, wer mitgeht. Ohne das kann ich nicht berechnen, wie viel nötig ist.",
  "kategóriájú ruházatot kíván. A készletedben": "— Kleidung dieser Kategorie wird gebraucht. In deinem Vorrat gibt es",
  "ilyen tétel van.": "solche Einträge.",
  "nincs ilyen tétel — a készletnél ez egy kategória.": "keine solchen Einträge — im Vorrat ist das eine Kategorie.",
  "liter víz és": "Liter Wasser und",
