Object.assign(window.PP_FORD_SZOTAR.de, {
 "Mai tesztfeladat": "Heutige Testaufgabe",
 "Hogyan működik": "So funktioniert es",
 "Mit próbálj ki": "Was du ausprobieren sollst",
 "Ezt a feladatot a készüléked és a felület alapján kaptad, név nélkül.": "Diese Aufgabe hast du anhand deines Geräts und der Oberfläche (App oder Browser) bekommen, ohne deinen Namen.",
 "Működik": "Funktioniert",
 "Hibás": "Fehlerhaft",
 "Később": "Später",
 "Köszönjük, megkaptuk a visszajelzést.": "Danke, wir haben deine Rückmeldung erhalten.",
 "Most nincs kapcsolat. Elmentettem, és magától elküldöm, amint lesz.": "Gerade keine Verbindung. Gespeichert; sie wird automatisch gesendet, sobald wieder eine besteht.",
 "Ezt a szerver most nem fogadta el. Próbáld újra később.": "Der Server hat das gerade nicht angenommen. Bitte versuche es später erneut.",
 "Most nem érem el a szervert. Próbáld újra később.": "Der Server ist gerade nicht erreichbar. Bitte versuche es später erneut.",
 "Mára nincs több tesztfeladat. Köszönjük a segítséget!": "Für heute gibt es keine weitere Testaufgabe. Danke für deine Hilfe!",
 "Tesztfeladat": "Testaufgabe",
 "Mi nem működött?": "Was hat nicht funktioniert?",
 "Biblia: az olvasási terv ébresztője": "Bibel: der Wecker des Leseplans",
 "Az olvasási terv ébresztője a beállított időben felébreszti a telefont, a lezárt képernyő fölött megnyitja az aznapi olvasmányt, és felolvassa. Halkan indul, és bő fél perc alatt erősödik fel; előtte egy rövid köszöntés elmondja, mi a mai olvasmány. Amíg olvas, a képernyő alján egy nagy Leállítom gomb van.": "Der Wecker des Leseplans weckt das Telefon zur eingestellten Zeit, öffnet die heutige Lesung über dem Sperrbildschirm und liest sie vor. Er beginnt leise und wird in gut einer halben Minute lauter; davor sagt eine kurze Begrüßung, was die heutige Lesung ist. Während er liest, gibt es unten auf dem Bildschirm eine große Taste Beenden.",
 "Biblia > Olvasási terv: nyiss meg egy futó tervet, kapcsold be az ébresztőt, és állítsd az időpontot 2 perccel későbbre.": "Bibel > Leseplan: öffne einen laufenden Plan, schalte den Wecker ein und stelle die Zeit 2 Minuten später.",
 "Zárd le a telefont, és tedd le. Figyeld: felébred-e a telefon, halkan indul-e a hang, és elhangzik-e a köszöntés.": "Sperre das Telefon und lege es hin. Achte darauf: wacht das Telefon auf, beginnt der Ton leise, und hörst du die Begrüßung?",
 "Koppints a nagy Leállítom gombra: a felolvasásnak azonnal meg kell állnia.": "Tippe auf die große Taste Beenden: das Vorlesen muss sofort aufhören.",
 "Biblia: a könyvcsoportok színei": "Bibel: die Farben der Buchgruppen",
 "A Biblia könyvlistáján a könyvek csoportonként színes csempéken állnak. A csoportok ugyanazt az öt zöld árnyalatot kapják, de világos és sötét váltakozva, hogy két szomszédos csoport jól elváljon egymástól. Éjszakai módban ugyanez vörös árnyalatokkal.": "In der Bücherliste der Bibel stehen die Bücher gruppenweise auf farbigen Kacheln. Die Gruppen haben dieselben fünf Grüntöne, aber hell und dunkel wechseln sich ab, damit zwei benachbarte Gruppen gut zu unterscheiden sind. Im Nachtmodus dasselbe in Rottönen.",
 "Nyisd meg a Bibliát, és koppints a Biblia csempére, hogy megjelenjen a könyvek listája.": "Öffne die Bibel und tippe auf die Kachel Bibel, damit die Liste der Bücher erscheint.",
 "Nézd végig a csempéket: jól elválnak-e a szomszédos csoportok, és minden könyvnév olvasható-e a háttéren?": "Sieh dir die Kacheln an: sind benachbarte Gruppen gut zu unterscheiden, und ist jeder Buchname auf seinem Hintergrund lesbar?",
 "Lenyíló lista: a vissza csak a listát zárja": "Auswahlliste: Zurück schließt nur die Liste",
 "Ha egy lenyíló lista (például a Rádió-hatótáv sávválasztója) nyitva van, a vissza gomb először csak a listát zárja be, és ugyanazon a képernyőn maradsz. Ha közben másik képernyőre lépsz, a nyitott lista nem maradhat ott a következő képernyő fölött.": "Wenn eine Auswahlliste (zum Beispiel die Bandauswahl der Funkreichweite) offen ist, schließt die Zurück-Taste zuerst nur die Liste, und du bleibst auf demselben Bildschirm. Wechselst du dabei zu einem anderen Bildschirm, darf die offene Liste nicht über dem nächsten Bildschirm stehen bleiben.",
 "Kalkulátor > Rádió-hatótáv: koppints a sáv választójára, hogy lenyíljon a lista.": "Rechner > Funkreichweite: tippe auf die Bandauswahl, damit die Liste aufgeht.",
 "Nyomd meg a vissza gombot: a lista bezárul, és a Rádió-hatótáv képernyő marad.": "Drücke die Zurück-Taste: die Liste schließt sich, und der Bildschirm Funkreichweite bleibt.",
 "Nyisd ki újra a listát, és lépj át egy másik képernyőre: a lista nem maradhat ott lebegve.": "Öffne die Liste erneut und wechsle zu einem anderen Bildschirm: die Liste darf dort nicht schwebend bleiben.",
 "Szobák: privát üzenet (Csak neki)": "Räume: private Nachricht (Nur an)",
 "Egy internetes szobában egy tagnak úgy is írhatsz, hogy csak ő lássa. Ilyenkor a beíró mező fölött „Csak neki” sáv áll a nevével; amíg ez látszik, az üzenet biztosan privátként megy el, és a sáv nem takarja el a legutolsó üzenetet. Ha mégsem megy el, az app megmondja, miért, és a beírt szöveg megmarad.": "In einem Internet-Raum kannst du einem Mitglied so schreiben, dass nur es die Nachricht sieht. Dann steht über dem Eingabefeld eine Leiste „Nur an“ mit seinem Namen; solange sie zu sehen ist, geht die Nachricht sicher privat hinaus, und die Leiste verdeckt die letzte Nachricht nicht. Geht sie trotzdem nicht hinaus, sagt die App, warum, und dein Text bleibt erhalten.",
 "Nyiss meg egy szobát, ahol van legalább egy másik tag, és koppints egy tőle jött üzenet mellett a képére.": "Öffne einen Raum mit mindestens einem anderen Mitglied und tippe auf das Bild neben einer Nachricht von ihm.",
 "Írj egy rövid üzenetet, és küldd el. A legutolsó üzenetnek a „Csak neki” sáv fölött kell látszania.": "Schreibe eine kurze Nachricht und sende sie. Die letzte Nachricht muss über der Leiste „Nur an“ zu sehen sein.",
 "Ha meg tudod kérdezni: a címzett megkapta, a többiek nem látják.": "Wenn du fragen kannst: der Empfänger hat sie bekommen, die anderen sehen sie nicht."
});
