 "Noah, az offline MI segéd a telefonra telepített Android appban fut: a nyelvi modellt a telefon egyszer letölti, utána internet nélkül, helyben válaszol. A böngészős változatban és iPhone-on nem érhető el, mert ide a modell nem tölthető le.": "Noah, der Offline-KI-Assistent, läuft in der auf dem Telefon installierten Android-App: Das Telefon lädt das Sprachmodell einmal herunter und antwortet danach lokal, ohne Internet. In der Browser-Version und auf dem iPhone ist er nicht verfügbar, weil das Modell dort nicht heruntergeladen werden kann.",
 "Ehhez Android 11 vagy újabb, legalább 6 GB memóriás telefon kell, és 6-8 GB szabad hely.": "Dafür braucht es ein Telefon mit Android 11 oder neuer, mindestens 6 GB Arbeitsspeicher und 6-8 GB freiem Speicherplatz.",
 "A nyelvi modell válasz közben kb. 3 GB memóriát használ. 6 GB-nál kevesebb memóriájú telefonon a rendszer ilyenkor leállítaná az appot, ezért itt Noah nem használható.": "Beim Antworten nutzt das Sprachmodell etwa 3 GB Arbeitsspeicher. Auf einem Telefon mit weniger als 6 GB würde das System die App dabei beenden, deshalb ist Noah hier nicht nutzbar.",
