Object.assign(window.PP_FORD_SZOTAR.de, {
  "A Gerah a közösségen belüli elszámolás egysége, nem pénz és nem fizetőeszköz. A PrepperPapa nem váltja át pénzre, nem garantálja az értékét, és nem részese a tagok közötti ügyleteknek. A tagok közötti vitákat és elszámolást a felhasználók egymás közt rendezik. Az offline fizetésnél előfordulhat, hogy ugyanazt a Gerah-t kétszer költik el; ennek kockázata a felhasználókat terheli.": "Die Gerah ist eine Verrechnungseinheit innerhalb der Gemeinschaft, kein Geld und kein Zahlungsmittel. PrepperPapa tauscht sie nicht in Geld um, garantiert ihren Wert nicht und ist an den Geschäften zwischen den Mitgliedern nicht beteiligt. Streitigkeiten und Abrechnungen zwischen den Mitgliedern regeln die Nutzer untereinander. Bei Offline-Zahlungen kann es vorkommen, dass dieselbe Gerah zweimal ausgegeben wird; dieses Risiko tragen die Nutzer."
});
