 "Téves vagy félrevezető": "Falsch oder irreführend",
 "Megjegyzés (nem kötelező)": "Anmerkung (optional)",
 "A jelentett válasz": "Die gemeldete Antwort",
 "A szerver most nem fogadta el a jelentést. Próbáld újra később.": "Der Server hat die Meldung gerade nicht angenommen. Versuche es später erneut.",
 "Jelentve": "Gemeldet",
 "Köszönjük, a jelentést megkaptuk.": "Danke, wir haben die Meldung erhalten.",
 "Noah névjegye": "Über Noah",
 "Noah a Gemma 4 nyílt nyelvi modellel működik (Gemma 4, Google, Apache 2.0 licenc).": "Noah arbeitet mit dem offenen Sprachmodell Gemma 4 (Gemma 4, Google, Apache-2.0-Lizenz).",
 "A Gemma 4 modellt a Google fejlesztette és adja ki az Apache License 2.0 licenc szerint. A licenc szövege:": "Das Modell Gemma 4 wurde von Google entwickelt und wird unter der Apache License 2.0 veröffentlicht. Der Lizenztext:",
 "A PrepperPapa nem a Google terméke, és a Google nem támogatja vagy hagyja jóvá.": "PrepperPapa ist kein Google-Produkt und wird von Google weder unterstützt noch empfohlen.",
 "Noah válaszait gépi modell írja, és tévedhet. Ha egy válasz sértő, veszélyes vagy téves, a válasz alatti „Válasz jelentése” gombbal jelezd nekünk.": "Noahs Antworten schreibt ein Maschinenmodell, und sie können falsch sein. Ist eine Antwort beleidigend, gefährlich oder falsch, melde sie uns mit der Schaltfläche „Antwort melden“ darunter.",
 "Noah, az offline MI segéd: Gemma 4, Google, Apache 2.0 licenc.": "Noah, der Offline-KI-Assistent: Gemma 4, Google, Apache-2.0-Lizenz.",
 "A modell a Google Gemma 4 (Apache 2.0 licenc), a Google hivatalos LiteRT-tárából (Hugging Face) töltődik le. Wi-Fi ajánlott.": "Das Modell ist Google Gemma 4 (Apache-2.0-Lizenz) und wird aus dem offiziellen LiteRT-Repository von Google (Hugging Face) geladen. WLAN empfohlen.",
 "Reggeli összefoglaló": "Morgenübersicht",
 "Minden reggel értesítés: a készlet hiányai, a készenléti szint, egy ige és egy felkészülési tanács. Ha megnyitod Noah-t, kártyaként is látod.": "Jeden Morgen eine Benachrichtigung: die Lücken im Vorrat, die Bereitschaftsstufe, ein Bibelvers und ein Vorsorgetipp. Wenn du Noah öffnest, siehst du sie auch als Karte.",
 "Reggeli összefoglaló bekapcsolva": "Morgenübersicht eingeschaltet",
 "Mutasd most": "Jetzt zeigen",
 "Értesítés engedélyezése": "Benachrichtigungen erlauben",
 "Noah · Reggeli összefoglaló": "Noah · Morgenübersicht",
 "Készenlét: {hely}, {szint} szint, {pct}%.": "Bereitschaft: {hely}, Stufe {szint}, {pct} %.",
 "Hiányzik a következő szinthez: {lista}.": "Fehlt bis zur nächsten Stufe: {lista}.",
 "Készenlét: még nem mérhető. Add meg a Háztartásban a helyszínt, kik érkeznek oda, és rendelj hozzá készletet.": "Bereitschaft: noch nicht messbar. Lege im Haushalt den Ort an, wer dort ankommt, und ordne ihm Vorräte zu.",
 "Hiányzik: {lista}.": "Fehlt: {lista}.",
 "Ige ({hely}): {szoveg}": "Bibelvers ({hely}): {szoveg}",
 "Tipp: {szoveg}": "Tipp: {szoveg}",
 "A reggeli összefoglaló a telefonra telepített Android appban működik.": "Die Morgenübersicht funktioniert in der auf dem Telefon installierten Android-App.",
 "Kikapcsolva.": "Ausgeschaltet.",
 "Az értesítéshez engedély kell: koppints az „Értesítés engedélyezése” gombra.": "Für die Benachrichtigung ist eine Erlaubnis nötig: tippe auf „Benachrichtigungen erlauben“.",
 "Beütemezve: a következő {n} reggel, {ido}-kor.": "Geplant: die nächsten {n} Morgen um {ido}.",
 "Minden reggel {ido}-kor.": "Jeden Morgen um {ido}.",
 "A tipp a tudástárban": "Der Tipp im Wissensspeicher",
 "A nap pályájához tudni kell, hol vagy: nyomd meg lent a „Mérés a helyzetemre” gombot.": "Für die Sonnenbahn muss die App wissen, wo du bist: drücke unten „Messung an meinem Standort“.",
 "A nap most a horizont alatt van: a pályáját nappal rajzolom a képre.": "Die Sonne steht jetzt unter dem Horizont: ihre Bahn wird tagsüber ins Bild gezeichnet.",
 "A nap pályájához iránytű- és dőlésadat kell.": "Die Sonnenbahn braucht Kompass- und Neigungsdaten.",
 "Napkelte": "Sonnenaufgang",
 "delel": "Mittag",
 "A pálya most nincs a képen: fordulj {fok}° felé.": "Die Bahn ist gerade nicht im Bild: dreh dich Richtung {fok}°.",
 "A segéd beállításai": "Einstellungen des Assistenten",
 "A segédhez először le kell tölteni a nyelvi modellt a telefonra (egyszer, Wi-Fi ajánlott).": "Für den Assistenten musst du zuerst das Sprachmodell aufs Telefon laden (einmal, WLAN empfohlen).",
 "A választ a telefonon futó gépi modell írja. Életveszélyben a forráscikket olvasd el, és hívd a 112-t. Az igét a Károli-fordításból az app illeszti be, nem a modell.": "Die Antwort schreibt ein auf dem Telefon laufendes Maschinenmodell. Bei Lebensgefahr lies den Quellartikel und ruf den Notruf. Bibelverse fügt die App aus ihrer Bibelübersetzung ein, nicht das Modell.",
 "Amit még tudjon rólad. Kérdezzben is mondhatod: „jegyezd meg, hogy …”": "Was er noch über dich wissen soll. Du kannst es auch beim Fragen sagen: „merk dir, dass …“",
 "Az első használatkor a telefon még egyszer ennyi helyet foglal a gyorsabb futáshoz, tehát a letöltés méretének kétszerese kell szabadon.": "Bei der ersten Nutzung belegt das Telefon für schnelleren Betrieb noch einmal so viel Platz, also muss das Doppelte der Downloadgröße frei sein.",
 "Csak ezen a telefonon marad, sehova nem küldjük el. Gépelés közben magától mentődik.": "Es bleibt nur auf diesem Telefon und wird nirgendwohin gesendet. Es speichert sich beim Tippen selbst.",
 "Hogyan tisztítsak vizet, ha nincs forraló?": "Wie reinige ich Wasser, wenn ich es nicht abkochen kann?",
 "Hogyan tisztítsak vizet?": "Wie reinige ich Wasser?",
 "Hol van megírva, hogy ne aggódjunk a holnapért?": "Wo steht geschrieben, dass wir uns nicht um morgen sorgen sollen?",
 "Hol van megírva, hogy ne aggódjunk?": "Wo steht, dass wir uns nicht sorgen sollen?",
 "Károli-fordítás": "Die Bibelübersetzung der App",
 "Kérdezz a tudástárból, a Bibliából, vagy bármiről. Internet nélkül, a telefonon fut.": "Frag zum Wissensspeicher, zur Bibel oder zu allem anderen. Läuft auf dem Telefon, ohne Internet.",
 "Lakóhely, térség (pl. Gyömrő, Pest megye)": "Wohnort, Region (z. B. Ort, Landkreis)",
 "Megszakítás": "Abbrechen",
 "Mit tudsz?": "Was kannst du?",
 "Modell letöltése": "Modell herunterladen",
