 "Rövid válaszok": "Kurze Antworten",
 "Rólam (a válaszokhoz)": "Über mich (für die Antworten)",
 "A Háztartás családtagjait is vegye figyelembe": "Auch die Haushaltsmitglieder berücksichtigen",
 "Írj egy kérdést…": "Schreib eine Frage…",
 "Új beszélgetés": "Neues Gespräch",
