 "{n} liter víz": "{n} Liter Wasser",
 "{n} kcal élelem": "{n} kcal Lebensmittel",
 "{n} kWh hasznos fűtési energia": "{n} kWh nutzbare Heizenergie",
 "{fo} fő és {allat} állat, {nap} napra": "{fo} Personen und {allat} Tiere, für {nap} Tage",
 "{fo} fő, {nap} napra": "{fo} Personen, für {nap} Tage",
 "**{hely}**: nincs megadva, ki érkezik ide, ezért a készenléti szint nem számolható (Háztartás › Helyszínek › {hely}).": "**{hely}**: Es ist nicht angegeben, wer hier ankommt, deshalb lässt sich die Bereitschaftsstufe nicht berechnen (Haushalt › Orte › {hely}).",
 "**{hely}** ({keret}): ehhez a helyszínhez még nincs készlet rendelve, ezért a szint nem mérhető. A Készletnél a tétel Tárolási helyénél válaszd ki: {hely}.": "**{hely}** ({keret}): Diesem Ort ist noch kein Vorrat zugeordnet, deshalb ist die Stufe nicht messbar. Wähle im Vorrat beim Lagerort des Artikels: {hely}.",
 "**{hely}** ({keret}): van ide rendelt készlet, de se víz, se mérhető élelem, se fűtés nincs benne, ezért a szint nem számolható.": "**{hely}** ({keret}): Hier ist Vorrat zugeordnet, aber weder Wasser noch messbare Lebensmittel noch Heizung, deshalb lässt sich die Stufe nicht berechnen.",
 "**{hely}** ({keret}): **{szint}** készenléti szint, {pct}%.": "**{hely}** ({keret}): Bereitschaftsstufe **{szint}**, {pct} %.",
 "élelem": "Lebensmittel",
 "fűtés": "Heizung",
 "jó": "gut",
 "gyenge": "schwach",
 "teljes": "voll",
 "Az élelmiszereknél nincs megadva az energia (kcal), ezért az élelem nem mérhető.": "Bei den Lebensmitteln ist keine Energie (kcal) angegeben, deshalb sind sie nicht messbar.",
 "A teljes (100%) készlethez hiányzik: {lista}.": "Für den vollen (100 %) Vorrat fehlt: {lista}.",
 "A következő, {szint} szinthez (minden legalább {min}%) hiányzik: {lista}.": "Für die nächste Stufe, {szint} (alles mindestens {min} %), fehlt: {lista}.",
 "Minden mért összetevő 100%.": "Jeder gemessene Bestandteil liegt bei 100 %.",
 "A Háztartásban még nincs helyszín, ezért a készenléti szint nem számolható. Vedd fel az otthonodat a Háztartás › Helyszínek alatt, és add meg, kik érkeznek oda és hány napra számolsz.": "Im Haushalt gibt es noch keinen Ort, deshalb lässt sich die Bereitschaftsstufe nicht berechnen. Lege dein Zuhause unter Haushalt › Orte an und gib an, wer dort ankommt und für wie viele Tage du planst.",
 "A készlet üres: még egyetlen tételt sem vettél fel.": "Der Vorrat ist leer: Du hast noch keinen einzigen Artikel angelegt.",
 "A készleted üres: még egyetlen tételt sem vettél fel.": "Dein Vorrat ist leer: Du hast noch keinen einzigen Artikel angelegt.",
 "A Mi hiányzik? listából ({db} tétel, az első 6):": "Aus der Liste „Was fehlt?“ ({db} Artikel, die ersten 6):",
 "A Mi hiányzik? listából ({db} tétel):": "Aus der Liste „Was fehlt?“ ({db} Artikel):",
 "tag": "Mitglied",
 "{n} éves": "{n} Jahre alt",
 "{db} db": "{db} Stk.",
 "lejár:": "läuft ab:",
 "A Háztartásban még nincs helyszín. A Háztartás › Helyszínek alatt veheted fel.": "Im Haushalt gibt es noch keinen Ort. Du kannst ihn unter Haushalt › Orte anlegen.",
 "Helyszíneid ({db}):": "Deine Orte ({db}):",
 "{n} fő": "{n} Personen",
 "{n} állat": "{n} Tiere",
 "{n} nap": "{n} Tage",
 "A Háztartásban nincs háziállat felvéve.": "Im Haushalt ist kein Haustier angelegt.",
 "Háziállataid ({db}):": "Deine Haustiere ({db}):",
 "állat": "Tier",
 "A Háztartásban még nincs családtag felvéve. A Háztartás › Családtagok alatt veheted fel őket.": "Im Haushalt ist noch kein Familienmitglied angelegt. Du kannst sie unter Haushalt › Familienmitglieder anlegen.",
 "A háztartásod ({db} fő):": "Dein Haushalt ({db} Personen):",
 "A Háztartásban nincs családtag felvéve.": "Im Haushalt ist kein Familienmitglied angelegt.",
 "Háziállat:": "Haustier:",
 "Nincs mentett pontod a térképen.": "Du hast keinen gespeicherten Punkt auf der Karte.",
 "Mentett pontjaid ({db}):": "Deine gespeicherten Punkte ({db}):",
 "A készletben ({db} tétel):": "Im Vorrat ({db} Artikel):",
 "… és még {n}": "… und {n} weitere",
 "Ilyen tétel nincs a készletedben. (A készletben {db} tétel van.)": "Einen solchen Artikel gibt es in deinem Vorrat nicht. (Der Vorrat hat {db} Artikel.)",
 "A készletedben {db} tétel van, összesen {ossz} darab. Kategóriánként:": "Dein Vorrat hat {db} Artikel, insgesamt {ossz} Stück. Nach Kategorie:",
 "{t} tétel, {db} db": "{t} Artikel, {db} Stk.",
 "{nap} napos túra hátizsákkal": "eine {nap}-tägige Tour mit Rucksack",
 "{nap} napos út autóval": "eine {nap}-tägige Fahrt mit dem Auto",
 "{nap} napos út": "eine {nap}-tägige Reise",
 "A Háztartásban még nincs családtag, ezért nem tudom kijelölni, kik mennek. A Mit vigyek? ablakot megnyitom, a napokat beállítottam ({nap}); a résztvevőket a Háztartás › Családtagok alatt vedd fel, utána a lista kiszámolja, mi kell.": "Im Haushalt gibt es noch kein Familienmitglied, deshalb kann ich nicht auswählen, wer mitkommt. Ich öffne das Fenster „Was mitnehmen?“ mit eingestellten Tagen ({nap}); lege die Teilnehmer unter Haushalt › Familienmitglieder an, dann berechnet die Liste, was nötig ist.",
 "Összeállítottam: {fej}, {fo} fő és {allat} állat ({nevek}). Megnyitom a Mit vigyek? ablakban, kitöltve; a listát ott látod és pipálhatod.": "Zusammengestellt: {fej}, {fo} Personen und {allat} Tiere ({nevek}). Ich öffne es ausgefüllt im Fenster „Was mitnehmen?“; dort siehst du die Liste und kannst abhaken.",
 "Összeállítottam: {fej}, {fo} fő ({nevek}). Megnyitom a Mit vigyek? ablakban, kitöltve; a listát ott látod és pipálhatod.": "Zusammengestellt: {fej}, {fo} Personen ({nevek}). Ich öffne es ausgefüllt im Fenster „Was mitnehmen?“; dort siehst du die Liste und kannst abhaken.",
 "A Háztartásban csak {ossz} fő van, őket jelöltem ki. A hiányzó {hiany} főt vedd fel a Háztartásnál, hogy a lista velük is számoljon.": "Im Haushalt gibt es nur {ossz} Personen, die habe ich ausgewählt. Lege die fehlenden {hiany} Personen im Haushalt an, damit die Liste sie mitrechnet.",
 "A napok számát nem mondtad, {nap} nappal számoltam.": "Du hast die Anzahl der Tage nicht genannt, ich habe mit {nap} Tagen gerechnet.",
 "Hová tervezzem az útvonalat? Írd meg a cél nevét (település, turistapont, saját pont vagy helyszín), például: „Tervezd meg az útvonalat Dobogókőre.”": "Wohin soll ich die Route planen? Schreib den Namen des Ziels (Ort, Wanderpunkt, eigener Punkt oder Ort aus dem Haushalt).",
 "Nem találom ezt a helyet: „{cel}”. Sem a saját pontjaid, sem a helyszíneid, sem a letöltött turistapontok, sem a települések között nincs ilyen nevű. Útvonalat fejből nem írok le; ha máshogy hívják, írd meg pontosabban, vagy a térképen egy pont buborékán válaszd az „Útvonal ide”-t.": "Ich finde diesen Ort nicht: „{cel}“. Weder unter deinen Punkten noch deinen Orten, den heruntergeladenen Wanderpunkten oder den Siedlungen gibt es diesen Namen. Eine Route beschreibe ich nie aus dem Kopf; heißt er anders, schreib ihn genauer, oder wähle auf der Karte in der Blase eines Punktes „Route hierher“.",
 "Nem tudom, hol vagy (nincs GPS-helyzet), ezért a távolságot nem tudom megmondani.": "Ich weiß nicht, wo du bist (keine GPS-Position), deshalb kann ich die Entfernung nicht sagen.",
 "légvonalban {km} km, {egtaj} felé ({fok}°), {honnan} alapján.": "Luftlinie {km} km, Richtung {egtaj} ({fok}°), ausgehend von {honnan}.",
