 "Útvonal ide: {nev} ({al}). Megnyitom a térképen a tervezőt: a mostani helyzetedből, turistautakon számolja (legfeljebb kb. 80 km).": "Route nach: {nev} ({al}). Ich öffne den Planer auf der Karte: Er rechnet von deinem aktuellen Standort über Wanderwege (bis etwa 80 km).",
 "Több hely is illik erre: „{cel}”. Melyikre gondolsz? Koppints rá, vagy írd meg pontosabban.": "Mehrere Orte passen zu „{cel}“. Welchen meinst du? Tippe darauf oder schreib es genauer.",
