 "{nap} napon belül sem jár le semmi. A következő lejáratok:": "Auch innerhalb von {nap} Tagen läuft nichts ab. Die nächsten Ablaufdaten:",
 "{db} tételnél nincs megadva lejárati dátum, ezeket nem tudom figyelni.": "Bei {db} Artikeln ist kein Ablaufdatum angegeben, die kann ich nicht überwachen.",
 "Nem tudom, hol vagy: nincs GPS-helyzet, mentett pont vagy otthon-koordináta, ezért a napkeltét nem tudom kiszámolni.": "Ich weiß nicht, wo du bist: Es gibt keine GPS-Position, keinen gespeicherten Punkt und keine Koordinate des Zuhauses, deshalb kann ich den Sonnenaufgang nicht berechnen.",
 "{nap}: ezen a helyen ma nincs napkelte vagy napnyugta.": "{nap}: An diesem Ort gibt es heute keinen Sonnenauf- oder -untergang.",
 "{nap} ({honnan} alapján): napkelte {kelte}, napnyugta {nyugta}; világos még a polgári szürkület végéig, {szurk}. Hold: {hold}, {szaz}% megvilágítva. (Az app számolja, néhány perc pontossággal.)": "{nap} (ausgehend von {honnan}): Sonnenaufgang {kelte}, Sonnenuntergang {nyugta}; hell bis zum Ende der bürgerlichen Dämmerung, {szurk}. Mond: {hold}, {szaz} % beleuchtet. (Von der App berechnet, auf wenige Minuten genau.)",
