  "Eddig összesen {n} gerah-t kaphattál volna a PrepperPapa alkalmazásban.": "Bisher hättest du in der PrepperPapa-App insgesamt {n} gerah bekommen können.",
  "A mai napot a PrepperPapa alkalmazás veszi át, amikor legközelebb megnyitod. Ha a nap csatlakozik a heti cél egymást követő napjaihoz, {n} gerah kerül érte letétbe, és a heti cél teljesítésekor a tárcádba.": "Die PrepperPapa-App übernimmt den heutigen Tag, wenn du sie das nächste Mal öffnest. Schließt der Tag an die aufeinanderfolgenden Tage deines Wochenziels an, werden dafür {n} gerah hinterlegt und kommen mit dem erreichten Wochenziel in deine Geldbörse.",
