Object.assign(window.PP_FORD_SZOTAR.de, {
 "Gerah: a terv befejezésekor {m} gerah ráadás jár": "Gerah: Der Abschluss des Plans bringt {m} gerah Bonus",
 "Gerah: {k} megszerezve": "Gerah: {k} verdient",
 "A kézi pipa a saját nyilvántartásodnak szól, Gerah-t nem ad. A terv befejezési ráadása a ténylegesen elolvasott vagy végighallgatott napok alapján jár.": "Ein manuelles Häkchen dient nur deiner eigenen Übersicht und bringt keine Gerah. Der Abschlussbonus des Plans richtet sich nach den Tagen, die du wirklich liest oder anhörst.",
 "Megjelölve. A terv befejezési ráadásába akkor számít, ha el is olvasod vagy végighallgatod.": "Markiert. Zum Abschlussbonus des Plans zählt es, wenn du es auch liest oder anhörst.",
 "+{n} gerah az olvasási tervért.": "Gerah für den Leseplan: +{n}",
 "+{n} gerah a terv befejezéséért.": "Leseplan abgeschlossen, Gerah: +{n}",
 "Ha végigolvasod vagy végighallgatod, a nap beszámít a terv befejezési ráadásába.": "Wenn du es bis zum Ende liest oder anhörst, zählt der Tag zum Abschlussbonus des Plans.",
 "Olvasási terv: a tervnapokért nem jár Gerah; a terv végigolvasásakor ráadás jár a ténylegesen elolvasott vagy végighallgatott napok arányában (a teljes Biblia egyéves terve {n} gerah, a többi terv a terjedelme szerint).": "Leseplan: Für die Plantage gibt es keine Gerah; zum Abschluss des Plans gibt es einen Bonus im Verhältnis zu den wirklich gelesenen oder angehörten Tagen (Jahresplan für die ganze Bibel {n} gerah, andere Pläne nach ihrem Umfang)."
});

