 "Amikor nem tudsz aludni": "Wenn du nicht schlafen kannst",
 "Amikor beteg vagy, vagy fájdalmad van": "Wenn du krank bist oder Schmerzen hast",
 "Amikor bűntudat nyom": "Wenn dich Schuld bedrückt",
 "Amikor haragszol, vagy megbántottak": "Wenn du zornig bist oder verletzt wurdest",
 "Amikor bátorság kell": "Wenn du Mut brauchst",
 "Amikor menekülnöd kell, vagy úton vagy": "Wenn du fliehen musst oder unterwegs bist",
 "Amikor sötét van, és nincs áram": "Wenn es dunkel ist und kein Strom da ist",
 "Amikor éhség és szűkösség van": "Wenn Hunger und Mangel herrschen",
