 "Amikor vihar, árvíz vagy tűz fenyeget": "Wenn Sturm, Flut oder Feuer drohen",
 "Amikor a gyermekeidért aggódsz": "Wenn du dich um deine Kinder sorgst",
 "Amikor reménytelennek látszik minden": "Wenn alles hoffnungslos scheint",
