 "Amikor a halál gondolata félelemmel tölt el": "Wenn dich der Gedanke an den Tod ängstigt",
 "Amikor döntened kell, és nincs idő": "Wenn du entscheiden musst und keine Zeit ist",
 "Amikor a munka nehéz és sok": "Wenn die Arbeit schwer und viel ist",
 "Amikor hálát adnál": "Wenn du danken möchtest",
