// ===== 2026-11-01 prayer room: the 4-week cycle of 28 guided prayers + "Imádság a világért" (text: Énok; owner TG 32765-32783) =====
Object.assign(window.PP_FORD_SZOTAR.de, {
  "Imádság a világért": "Gebet für die Welt",
  "Mind a 28 vezetett ima": "Alle 28 geführten Gebete",
  "{n}. hét": "Woche {n}",
  "Ezen a héten": "Diese Woche",
  "Négy hét, minden napra egy rövid vezetett ima, a kör négyhetente ismétlődik. Mindegyik hálaadással kezdődik, és csenddel zárul.": "Vier Wochen, für jeden Tag ein kurzes geführtes Gebet; der Kreis wiederholt sich alle vier Wochen. Jedes beginnt mit Dank und endet in der Stille.",
  "Megnyitás a térképen": "Auf der Karte öffnen",
  "A térkép világhelyzet-adatából, frissítve {kor}.": "Aus den Weltlage-Daten der Karte, aktualisiert {kor}.",
  "Köszönd meg a hetet, ami mögötted van. Nevezz meg három konkrét dolgot, amiért hálás vagy.": "Danke für die Woche, die hinter dir liegt. Nenne drei konkrete Dinge, für die du dankbar bist.",
  "Uram, köszönöm a mögöttem lévő hetet, a jót is és azt is, amit még nem értek. Köszönöm, hogy nem engedted el a kezemet. Hálás vagyok azért a három dologért, amit most eléd hozok.": "Herr, ich danke dir für die Woche, die hinter mir liegt, für das Gute und auch für das, was ich noch nicht verstehe. Danke, dass du meine Hand nicht losgelassen hast. Ich bin dankbar für die drei Dinge, die ich jetzt vor dich bringe.",
  "Uram, voltak napok, amikor nélküled indultam, és nélküled döntöttem. Nem mentegetem magam, hanem eléd teszem. Köszönöm, hogy Jézusért megbocsátasz, és tisztán állhatok előtted.": "Herr, es gab Tage, an denen ich ohne dich losgegangen bin und ohne dich entschieden habe. Ich rede mich nicht heraus, sondern lege es dir hin. Danke, dass du mir um Jesu willen vergibst und ich rein vor dir stehen darf.",
  "Uram, te mondod: csendesedjetek. Elcsendesedek, és elismerem, hogy te vagy az Isten, nem én. Te vagy az, aki a zaj fölött is úr marad.": "Herr, du sagst: Seid still. Ich werde still und erkenne an, dass du Gott bist, nicht ich. Du bist es, der auch über allem Lärm Herr bleibt.",
  "Uram, eléd teszem a jövő hetet: a munkámat, a családomat és a döntéseket, amik várnak rám. Nem kérem, hogy minden könnyű legyen, azt kérem, hogy te vezess benne. Add, hogy felismerjem a hangodat, amikor szólsz.": "Herr, ich lege dir die kommende Woche hin: meine Arbeit, meine Familie und die Entscheidungen, die vor mir liegen. Ich bitte nicht darum, dass alles leicht wird, sondern dass du mich darin führst. Hilf mir, deine Stimme zu erkennen, wenn du sprichst.",
  "Uram, itt vagyok. Nem mondok többet, csak előtted maradok.": "Herr, hier bin ich. Ich sage nicht mehr, ich bleibe einfach vor dir.",
  "Uram, mielőtt bármit kérnék, köszönöm, amit már adtál. Köszönöm az otthonomat, az erőmet és azokat az embereket, akik mellettem állnak. Nem magától értetődő, ajándék.": "Herr, bevor ich um etwas bitte, danke ich dir für das, was du mir schon gegeben hast. Danke für mein Zuhause, für meine Kraft und für die Menschen, die zu mir stehen. Das ist nicht selbstverständlich, es ist ein Geschenk.",
  "Uram, voltak gondok, amiket úgy cipeltem, mintha te nem látnád. Bocsásd meg, hogy a félelmemnek jobban hittem, mint neked. Most leteszem őket a kezedbe.": "Herr, es gab Sorgen, die ich getragen habe, als würdest du sie nicht sehen. Vergib mir, dass ich meiner Angst mehr geglaubt habe als dir. Jetzt lege ich sie in deine Hände.",
  "Uram, te nem azt mondod, hogy ne legyenek gondjaim, hanem hogy hozzam őket eléd. Imádsággal, kéréssel és hálával jövök, ahogy mondtad. Te békességet ígérsz, nem magyarázatot, és ez nekem elég.": "Herr, du sagst nicht, dass ich keine Sorgen haben soll, sondern dass ich sie zu dir bringen soll. Ich komme mit Gebet, mit Bitten und mit Dank, wie du gesagt hast. Du versprichst Frieden, keine Erklärung, und das genügt mir.",
  "Uram, egyenként hozom eléd, ami ma a vállamon van. Mindegyiket rád bízom, nem azért, mert kicsik, hanem mert te nagy vagy. Őrizd meg a szívemet és a gondolataimat a Krisztus Jézusban.": "Herr, eins nach dem anderen bringe ich vor dich, was heute auf meinen Schultern liegt. Ich vertraue dir alles an, nicht weil es klein ist, sondern weil du groß bist. Bewahre mein Herz und meine Gedanken in Christus Jesus.",
  "Uram, ami még bennem maradt, azt is tudod. Átadom szavak nélkül is.": "Herr, du weißt auch, was noch in mir geblieben ist. Ich gebe es dir, auch ohne Worte.",
  "Uram, köszönöm, hogy nem azt kapom, amit megérdemlek, hanem kegyelmet. Köszönöm, hogy Jézus már megfizetett azért, amit én nem tudtam volna. Ezért jöhetek most eléd félelem nélkül.": "Herr, danke, dass ich nicht bekomme, was ich verdiene, sondern Gnade. Danke, dass Jesus schon bezahlt hat, was ich nie hätte bezahlen können. Darum darf ich jetzt ohne Angst zu dir kommen.",
  "Uram, mutasd meg, mi az, amit rendbe kell tennem. Néven nevezem előtted, nem szépítem és nem magyarázom. Te hű és igaz vagy: megbocsátasz, és megtisztítasz minden hamisságtól.": "Herr, zeig mir, was ich in Ordnung bringen muss. Ich nenne es vor dir beim Namen, ich beschönige nichts und erkläre nichts weg. Du bist treu und gerecht: Du vergibst mir und reinigst mich von aller Ungerechtigkeit.",
  "Uram, a te szavad azt mondja: ha megvallom, megbocsátod. Nem a jó érzésemre építek, hanem a te hűségedre. Elfogadom, hogy ami megvallva van, az el is van rendezve.": "Herr, dein Wort sagt: Wenn ich bekenne, vergibst du. Ich baue nicht auf mein Gefühl, sondern auf deine Treue. Ich nehme an, dass das, was bekannt ist, auch erledigt ist.",
  "Uram, adj erőt, hogy ahol embertől kell bocsánatot kérnem, megtegyem. És adj szívet, hogy annak is megbocsássak, aki engem bántott. Tedd rendbe, amit én már nem tudok.": "Herr, gib mir Kraft, mich bei einem Menschen zu entschuldigen, wo es nötig ist. Und gib mir ein Herz, auch dem zu vergeben, der mich verletzt hat. Bring in Ordnung, was ich selbst nicht mehr in Ordnung bringen kann.",
  "Uram, tiszta lappal indulok. Köszönöm.": "Herr, ich fange neu an, mit reinem Tisch. Danke.",
  "Uram, köszönöm a mai napot, a reggelt, az ételt az asztalon, a tetőt a fejem fölött. Köszönöm a kicsiket is, amiket észre sem veszek. Mindegyik tőled jött.": "Herr, danke für den heutigen Tag, für den Morgen, für das Essen auf dem Tisch, für das Dach über meinem Kopf. Danke auch für die kleinen Dinge, die ich gar nicht bemerke. Alles kam von dir.",
  "Uram, tudom, mi került az első helyre nálam az utóbbi időben, és az nem te voltál. Megvallom, hogy a figyelmemet és az időmet máshová adtam. Bocsáss meg, és segíts újra sorba rakni.": "Herr, ich weiß, was in letzter Zeit bei mir an erster Stelle stand, und das warst nicht du. Ich bekenne, dass ich meine Aufmerksamkeit und meine Zeit woanders hingegeben habe. Vergib mir und hilf mir, wieder die richtige Reihenfolge zu finden.",
  "Uram, te azt mondod: először az országodat és az igazságodat keressem. Nem arra kérsz, hogy ne dolgozzak, hanem hogy ne a gond vezessen. Segíts úgy élni, mintha hinném, hogy te viselsz rám gondot, mert hiszem.": "Herr, du sagst, ich soll zuerst dein Reich und deine Gerechtigkeit suchen. Du verlangst nicht, dass ich nicht arbeite, sondern dass nicht die Sorge mich führt. Hilf mir so zu leben, als glaubte ich, dass du für mich sorgst, denn ich glaube es.",
  "Uram, rakd rendbe a mai napom sorrendjét: te legyél az első, és minden más a helyére kerüljön. És eléd hozom a szükségleteimet is, mert te mondtad, hogy hozzam. Add meg, ami kell, és adj hálás szívet ahhoz, amit adsz.": "Herr, ordne meinen heutigen Tag: Du sollst an erster Stelle stehen, und alles andere soll seinen Platz finden. Ich bringe dir auch meine Bedürfnisse, denn du hast gesagt, ich soll sie bringen. Gib mir, was ich brauche, und gib mir ein dankbares Herz für das, was du gibst.",
  "Uram, a nap többi része a tiéd. Járj velem benne.": "Herr, der Rest des Tages gehört dir. Geh mit mir hindurch.",
  "Uram, köszönöm, hogy nem kell bejelentkeznem hozzád, és nem kell érdemet hoznom. Jézus miatt nyitva az út, és te nem fordulsz el. Köszönöm, hogy a trónod kegyelem trónja.": "Herr, danke, dass ich mich bei dir nicht anmelden muss und keine Verdienste mitbringen muss. Durch Jesus ist der Weg offen, und du wendest dich nicht ab. Danke, dass dein Thron ein Thron der Gnade ist.",
  "Uram, amiben elbuktam, azt nem rejtem el előled. A szégyen azt mondja, hogy maradjak távol, de te azt mondod, hogy jöjjek közel. Jövök, és kérem az irgalmadat.": "Herr, worin ich versagt habe, verberge ich nicht vor dir. Die Scham sagt mir, ich soll fernbleiben, aber du sagst, ich soll näherkommen. Ich komme und bitte um dein Erbarmen.",
  "Uram, te bizalommal hívsz, nem rettegéssel. Jézus tudja, milyen embernek lenni, ezért értesz engem. Alkalmas időben segítesz, és ez az idő most van.": "Herr, du rufst mich mit Zuversicht, nicht mit Furcht. Jesus weiß, wie es ist, Mensch zu sein, darum verstehst du mich. Du hilfst zur rechten Zeit, und diese Zeit ist jetzt.",
  "Uram, most nem magamért jövök, hanem másokért. Eléd hozom a családomat, név szerint, és a barátaimat. És eléd hozom azt az embert, akiről tudom, hogy most nehéz helyzetben van: légy közel hozzá, adj neki erőt és reményt, és használj engem, ha kell.": "Herr, jetzt komme ich nicht für mich, sondern für andere. Ich bringe dir meine Familie, mit Namen, und meine Freunde. Und ich bringe dir den Menschen, von dem ich weiß, dass er gerade in einer schweren Lage ist: Sei ihm nahe, gib ihm Kraft und Hoffnung, und gebrauche mich, wenn es nötig ist.",
  "Uram, itt maradok előtted. Elég, hogy te itt vagy.": "Herr, ich bleibe hier vor dir. Es genügt, dass du da bist.",
  "Uram, ma a hálával kezdem, és nem sietek vele. Végigmegyek a héten, és köszönöm a jó pillanatokat egyiket a másik után: egy beszélgetést, egy elvégzett munkát, egy nyugodt estét. Te voltál mindegyikben, akkor is, ha nem vettem észre.": "Herr, heute beginne ich mit Dank und lasse mir Zeit damit. Ich gehe die Woche durch und danke dir für die guten Momente, einen nach dem anderen: ein Gespräch, eine erledigte Arbeit, einen ruhigen Abend. Du warst in jedem von ihnen, auch wenn ich es nicht gemerkt habe.",
  "Uram, voltak percek a héten, amikor zúgolódtam, és a hiányra néztem, nem rád. Bocsásd meg, és változtasd meg a szívemet. Taníts hálásnak lenni akkor is, amikor nem könnyű.": "Herr, es gab Augenblicke in dieser Woche, in denen ich gemurrt und auf das Fehlende geschaut habe statt auf dich. Vergib mir und verändere mein Herz. Lehre mich, dankbar zu sein, auch wenn es nicht leicht ist.",
  "Uram, te azt mondod, mindenben adjak hálát, nem mindenért, hanem mindenben. A nehézben is te vagy velem, és ezért ott is van mit köszönnöm. Ez a te akaratod, és én ezt választom.": "Herr, du sagst, ich soll in allem danken: nicht für alles, sondern in allem. Auch im Schweren bist du bei mir, und darum gibt es auch dort etwas zu danken. Das ist dein Wille, und ich entscheide mich dafür.",
  "Uram, a hétvégét is veled szeretném tölteni, ne csak a hétköznapokat. Vigyázz azokra, akikkel együtt leszek, és add, hogy jó legyek hozzájuk. Legyen pihenés és öröm is benne.": "Herr, ich möchte auch das Wochenende mit dir verbringen, nicht nur die Werktage. Behüte die, mit denen ich zusammen sein werde, und hilf mir, gut zu ihnen zu sein. Lass darin auch Ruhe und Freude sein.",
  "Uram, örülök, hogy velem vagy. Csendben is ezt mondom.": "Herr, ich freue mich, dass du bei mir bist. Auch in der Stille sage ich das.",
  "Uram, köszönöm, hogy ma meg lehet állni. Köszönöm, ami ezen a héten elkészült, és köszönöm, hogy nem rajtam múlik a világ. A pihenés is tőled jön.": "Herr, danke, dass ich heute innehalten darf. Danke für das, was in dieser Woche fertig geworden ist, und danke, dass die Welt nicht an mir hängt. Auch die Ruhe kommt von dir.",
  "Uram, cipelek dolgokat, amiket nem rám bíztál. Felelősséget, amit te hordozol, aggodalmat, amit te már elrendeztél. Megvallom, hogy nehezen engedem el, és most leteszem.": "Herr, ich trage Dinge, die du mir nicht aufgetragen hast: Verantwortung, die du trägst, Sorgen, die du schon geregelt hast. Ich bekenne, dass es mir schwerfällt loszulassen, und jetzt lege ich sie ab.",
  "Uram, te a megfáradtakat hívod, és én fáradt vagyok. Nem azt kéred, hogy előbb rendbe jöjjek, hanem hogy jöjjek. Jövök hozzád, úgy, ahogy vagyok.": "Herr, du rufst die Müden, und ich bin müde. Du verlangst nicht, dass ich zuerst in Ordnung komme, sondern dass ich komme. Ich komme zu dir, so wie ich bin.",
  "Uram, adj nyugalmat a testemnek és a lelkemnek. Ami a jövő héten vár, azt is a kezedbe teszem, hogy ne most hordozzam. Újítsd meg az erőmet, ahogy csak te tudod.": "Herr, gib meinem Leib und meiner Seele Ruhe. Was in der kommenden Woche auf mich wartet, lege ich auch in deine Hände, damit ich es nicht jetzt schon trage. Erneuere meine Kraft, wie nur du es kannst.",
  "Uram, megpihenek nálad. Nem teszek semmit, csak itt vagyok.": "Herr, ich ruhe bei dir. Ich tue nichts, ich bin einfach da.",
  "Az Úr az én pásztorom": "Der Herr ist mein Hirte",
  "Köszönd meg, hogy van, aki vezet, és nem egyedül kell kitalálnod az utat.": "Danke dafür, dass jemand dich führt und du den Weg nicht allein herausfinden musst.",
  "Uram, köszönöm, hogy nem egyedül kell kitalálnom, hová megyek. Te vezetsz, te gondoskodsz, és te ismered az utat, ahol én még nem jártam. Jó a te nyájadhoz tartozni.": "Herr, danke, dass ich nicht allein herausfinden muss, wohin ich gehe. Du führst, du sorgst, und du kennst den Weg, wo ich noch nie gegangen bin. Es ist gut, zu deiner Herde zu gehören.",
  "Hol mentél a magad feje után a héten, ahelyett, hogy őt követted volna? Mondd el.": "Wo bist du diese Woche deinen eigenen Kopf gegangen, statt ihm zu folgen? Sag es ihm.",
  "Uram, voltak helyek, ahová a magam feje után mentem, és nem kérdeztelek meg. Megvallom, hogy okosabbnak hittem magam a pásztoromnál. Hozz vissza, és én jövök.": "Herr, es gab Orte, an die ich nach meinem eigenen Kopf gegangen bin, ohne dich zu fragen. Ich bekenne, dass ich mich für klüger hielt als meinen Hirten. Hol mich zurück, und ich komme.",
  "Olvasd el, és mondd ki saját szavaddal: ő az én pásztorom.": "Lies es und sprich es mit deinen eigenen Worten aus: Er ist mein Hirte.",
  "Uram, te vagy az én pásztorom, nem általánosságban, hanem az enyém. Ha te vezetsz, nem szűkölködöm, mert te tudod, mi kell nekem. Erre építem ezt a hetet.": "Herr, du bist mein Hirte, nicht allgemein, sondern meiner. Wenn du mich führst, wird mir nichts mangeln, denn du weißt, was ich brauche. Darauf baue ich diese Woche.",
  "Kérd, hogy a jövő héten a hangját kövesd, és hogy a sötét völgyben is érezd, hogy ott van.": "Bitte darum, in der kommenden Woche seiner Stimme zu folgen und auch im finsteren Tal zu spüren, dass er da ist.",
  "Uram, add, hogy a jövő héten a te hangodat kövessem, ne a zajt. Ha völgybe vezet az út, add, hogy tudjam, ott is velem vagy. Legelőt és vizet is te adsz, rád bízom.": "Herr, hilf mir, in der kommenden Woche deiner Stimme zu folgen, nicht dem Lärm. Wenn der Weg in ein Tal führt, lass mich wissen, dass du auch dort bei mir bist. Weide und Wasser gibst auch du, ich vertraue es dir an.",
  "Maradj csendben, mint aki biztonságban van.": "Bleib still wie jemand, der in Sicherheit ist.",
  "Uram, biztonságban vagyok nálad. Csendben maradok.": "Herr, bei dir bin ich in Sicherheit. Ich bleibe still.",
  "Elég a kegyelem": "Die Gnade genügt",
  "Köszönd meg azokat a helyzeteket, ahol a saját erőd nem volt elég, mégis átjutottál.": "Danke für die Situationen, in denen deine eigene Kraft nicht reichte und du trotzdem hindurchgekommen bist.",
  "Uram, köszönöm azokat a helyzeteket, ahol a saját erőm elfogyott, és mégis átjutottam. Nem én voltam erős, te voltál. Köszönöm, hogy a gyengeségem nem akadály nálad.": "Herr, danke für die Situationen, in denen meine eigene Kraft zu Ende war und ich trotzdem hindurchgekommen bin. Nicht ich war stark, du warst es. Danke, dass meine Schwäche für dich kein Hindernis ist.",
  "Hol próbáltad a saját erődből megoldani, amit rá kellett volna bíznod? Valld meg.": "Wo hast du versucht, aus eigener Kraft zu lösen, was du ihm hättest anvertrauen sollen? Bekenne es.",
  "Uram, megvallom, hogy sokszor a magam erejéből akartam megoldani, amit neked kellett volna átadnom. Büszkeségből vagy félelemből, de nélküled. Bocsáss meg, és taníts rád támaszkodni.": "Herr, ich bekenne, dass ich oft aus eigener Kraft lösen wollte, was ich dir hätte übergeben sollen. Aus Stolz oder aus Angst, aber ohne dich. Vergib mir und lehre mich, mich auf dich zu stützen.",
  "Olvasd el. Figyeld meg: Pál nem a gyengeség megszűnését kapta, hanem a kegyelmet benne.": "Lies es. Achte darauf: Paulus bekam nicht das Ende seiner Schwäche, sondern die Gnade darin.",
  "Uram, te azt mondtad Pálnak: elég neked az én kegyelmem. Nekem is ezt mondod. Nem azt ígéred, hogy elveszed a tövist, hanem hogy az erőd a gyengeségemben teljesedik ki.": "Herr, du hast zu Paulus gesagt: Lass dir an meiner Gnade genügen. Das sagst du auch zu mir. Du versprichst nicht, den Dorn wegzunehmen, sondern dass deine Kraft in meiner Schwäche vollendet wird.",
  "Nevezd meg a gyenge pontodat erre a hétre, és kérd, hogy ott Krisztus ereje lakjon.": "Nenne deinen schwachen Punkt für diese Woche und bitte darum, dass dort die Kraft Christi wohnt.",
  "Uram, tudom, hol vagyok gyenge ezen a héten, és eléd hozom. Ott lakjon a Krisztus ereje, ahol az enyém nem elég. Nem kérem, hogy erős legyek, azt kérem, hogy te legyél erős bennem.": "Herr, ich weiß, wo ich in dieser Woche schwach bin, und ich bringe es vor dich. Lass dort die Kraft Christi wohnen, wo meine nicht reicht. Ich bitte nicht darum, stark zu sein, sondern dass du in mir stark bist.",
  "Csendben hagyd, hogy a kegyelem elég legyen.": "Lass in der Stille die Gnade genügen.",
  "Uram, elég nekem a kegyelmed. Ezt most elhiszem, és csendben maradok.": "Herr, deine Gnade genügt mir. Das glaube ich jetzt, und ich bleibe still.",
  "Ne félj": "Fürchte dich nicht",
  "Köszönd meg azokat a pillanatokat, amikor féltél, és ő mégis ott volt.": "Danke für die Augenblicke, in denen du Angst hattest und er trotzdem da war.",
  "Uram, köszönöm azokat a pillanatokat, amikor féltem, és te mégis ott voltál. Köszönöm, hogy nem hagytál egyedül a félelemmel, akkor sem, amikor nem éreztelek. Visszanézve látom a kezedet.": "Herr, danke für die Augenblicke, in denen ich Angst hatte und du trotzdem da warst. Danke, dass du mich mit meiner Angst nicht allein gelassen hast, auch dann nicht, als ich dich nicht spürte. Im Rückblick sehe ich deine Hand.",
  "A félelem gyakran olyan döntésekhez vezet, amiket nem vállalnánk tisztán. Hol döntöttél félelemből? Mondd el neki.": "Angst führt oft zu Entscheidungen, die wir mit klarem Kopf nicht treffen würden. Wo hast du aus Angst entschieden? Sag es ihm.",
  "Uram, megvallom, hogy voltak döntéseim, amiket a félelem hozott, nem a hit. Elhallgattam, elkerültem, halogattam, mert féltem. Bocsásd meg, és szabadíts meg a félelem uralmától.": "Herr, ich bekenne, dass manche meiner Entscheidungen aus Angst kamen, nicht aus Glauben. Ich habe geschwiegen, ausgewichen, aufgeschoben, weil ich Angst hatte. Vergib mir und befreie mich von der Herrschaft der Angst.",
  "Olvasd el, és számold meg, hány ígéret van egy versben. Mindegyik a jelenlétéből fakad.": "Lies es und zähle, wie viele Zusagen in einem einzigen Vers stehen. Jede entspringt seiner Gegenwart.",
  "Uram, te azt mondod: ne félj, mert veled vagyok. Nem azt mondod, hogy nincs mitől, hanem hogy te ott vagy. Megerősítesz, megsegítesz, a jobboddal támogatsz, és én ebbe kapaszkodom.": "Herr, du sagst: Fürchte dich nicht, denn ich bin mit dir. Du sagst nicht, dass es nichts zu fürchten gibt, sondern dass du da bist. Du stärkst mich, du hilfst mir, du hältst mich mit deiner rechten Hand, und daran halte ich mich fest.",
  "Nevezd meg a legnagyobb félelmedet most, és tedd mellé a vers szavait.": "Nenne jetzt deine größte Angst und stelle die Worte des Verses daneben.",
  "Uram, kimondom előtted, mitől félek most a legjobban. Odateszem mellé a te szavaidat: veled vagyok, megerősítelek. Add, hogy a félelmem kisebb legyen, mint a hitem benned.": "Herr, ich spreche vor dir aus, wovor ich mich gerade am meisten fürchte. Ich stelle deine Worte daneben: Ich bin mit dir, ich stärke dich. Lass meine Angst kleiner sein als mein Glaube an dich.",
  "Maradj csendben, mint akit fog a jobb kéz.": "Bleib still wie jemand, den die rechte Hand hält.",
  "Uram, te fogsz engem, nem én téged. Ebben nyugszom meg.": "Herr, du hältst mich, nicht ich dich. Darin komme ich zur Ruhe.",
  "Bízd rá az utadat": "Befiehl ihm deinen Weg",
  "Köszönd meg azokat a döntéseket, amiket utólag nézve ő igazgatott.": "Danke für die Entscheidungen, die er, im Rückblick gesehen, gelenkt hat.",
  "Uram, köszönöm azokat a döntéseket, amikről utólag látom, hogy te igazgattad. Akkor nem értettem, most már igen. Köszönöm, hogy a kerülőutak is a te kezedben voltak.": "Herr, danke für die Entscheidungen, bei denen ich im Nachhinein sehe, dass du sie gelenkt hast. Damals habe ich es nicht verstanden, jetzt schon. Danke, dass auch die Umwege in deiner Hand waren.",
  "Hol támaszkodtál csak a saját értelmedre, és hagytad ki őt a döntésből? Valld meg.": "Wo hast du dich nur auf deinen eigenen Verstand verlassen und ihn aus der Entscheidung herausgelassen? Bekenne es.",
  "Uram, megvallom, hogy voltak döntéseim, amikbe nem vontalak be. Mindent kiszámoltam, csak téged nem kérdeztelek meg. Bocsáss meg, és segíts bizalommal élni, ne csak okosan.": "Herr, ich bekenne, dass es Entscheidungen gab, in die ich dich nicht einbezogen habe. Ich habe alles durchgerechnet, nur dich habe ich nicht gefragt. Vergib mir und hilf mir, mit Vertrauen zu leben, nicht nur klug.",
  "Olvasd el. Nem az értelmet tiltja, hanem azt, hogy csak arra építs.": "Lies es. Es verbietet nicht den Verstand, sondern nur, allein darauf zu bauen.",
  "Uram, te adtad az értelmemet, és nem kéred, hogy eldobjam. Azt kéred, hogy ne egyedül arra építsek, hanem rád. Minden utamon számolok veled, és te igazgatod az utamat.": "Herr, du hast mir meinen Verstand gegeben, und du verlangst nicht, dass ich ihn wegwerfe. Du verlangst, dass ich nicht allein darauf baue, sondern auf dich. Auf allen meinen Wegen rechne ich mit dir, und du ebnest meinen Weg.",
  "Hozd eléje azt a döntést, ami most előtted áll. Kérj bölcsességet és nyitott szívet az ő irányára.": "Bring die Entscheidung vor ihn, die jetzt vor dir liegt. Bitte um Weisheit und ein offenes Herz für seine Richtung.",
  "Uram, eléd hozom azt a döntést, ami most előttem áll. Adj bölcsességet, és adj nyitott szívet, hogy a te irányodat elfogadjam akkor is, ha más, mint amit terveztem. Igazgasd ezt az utamat.": "Herr, ich bringe dir die Entscheidung, die jetzt vor mir liegt. Gib mir Weisheit und ein offenes Herz, deine Richtung anzunehmen, auch wenn sie anders ist, als ich es geplant habe. Ebne mir diesen Weg.",
  "Csendben engedd el a kontrollt.": "Lass in der Stille die Kontrolle los.",
  "Uram, az utam a tiéd. Elengedem, és rád bízom.": "Herr, mein Weg gehört dir. Ich lasse los und vertraue ihn dir an.",
  "Egymás terhét": "Einer trage des anderen Last",
  "Köszönd meg azokat, akik a te terhedet hordozták, amikor nehéz volt.": "Danke für die Menschen, die deine Last getragen haben, als es schwer war.",
  "Uram, köszönöm azokat az embereket, akik hordozták a terhemet, amikor nehéz volt. Egy hívás, egy ima, egy segítő kéz, amikor kellett. Rajtuk keresztül te voltál ott.": "Herr, danke für die Menschen, die meine Last getragen haben, als es schwer war. Ein Anruf, ein Gebet, eine helfende Hand, als ich sie brauchte. Durch sie warst du da.",
  "Kinek a terhe elől fordultál el az utóbbi időben, mert kényelmetlen volt? Mondd el.": "Von wessen Last hast du dich in letzter Zeit abgewandt, weil es unbequem war? Sag es ihm.",
  "Uram, megvallom, hogy volt valaki, akinek a terhe elől elfordultam, mert kényelmetlen volt. Láttam, és továbbmentem. Bocsásd meg, és adj szívet, ami nem fordul el.": "Herr, ich bekenne, dass es jemanden gab, von dessen Last ich mich abgewandt habe, weil es unbequem war. Ich habe es gesehen und bin weitergegangen. Vergib mir und gib mir ein Herz, das sich nicht abwendet.",
  "Olvasd el. A Krisztus törvénye a szeretet: így teljesítjük be.": "Lies es. Das Gesetz Christi ist die Liebe: So erfüllen wir es.",
  "Uram, te azt mondod, hogy egymás terhét hordozzuk, és ezzel a Krisztus törvényét töltjük be. Nem szabály ez, hanem szeretet. Taníts úgy szeretni, ahogy te szerettél engem.": "Herr, du sagst, wir sollen einer des anderen Last tragen und so das Gesetz Christi erfüllen. Das ist keine Regel, sondern Liebe. Lehre mich so zu lieben, wie du mich geliebt hast.",
  "Nevezz meg három embert, akiknek most teher van a vállán. Imádkozz érte egyenként: egészségért, erőért, kiútért.": "Nenne drei Menschen, die gerade eine Last tragen. Bete für jeden einzeln: um Gesundheit, um Kraft, um einen Ausweg.",
  "Uram, eléd hozok három embert, akik most terhet hordoznak. Az elsőért kérem, hogy adj neki erőt, a másodikért, hogy gyógyítsd, a harmadikért, hogy mutass neki kiutat. És ha engem akarsz használni bármelyiküknél, mutasd meg, hogyan.": "Herr, ich bringe dir drei Menschen, die gerade eine Last tragen. Für den ersten bitte ich, dass du ihm Kraft gibst, für den zweiten, dass du ihn heilst, für den dritten, dass du ihm einen Ausweg zeigst. Und wenn du mich bei einem von ihnen gebrauchen willst, zeig mir, wie.",
  "Csendben kérdezd meg: kihez küld ma?": "Frage in der Stille: Zu wem schickt er dich heute?",
  "Uram, kihez küldesz ma? Csendben várom.": "Herr, zu wem schickst du mich heute? Ich warte in der Stille.",
  "Ahogy ő megbocsátott": "Wie er vergeben hat",
  "Köszönd meg, hogy neked megbocsáttatott, konkrétan, nem általánosságban.": "Danke dafür, dass dir vergeben wurde, ganz konkret, nicht allgemein.",
  "Uram, köszönöm, hogy megbocsátottál nekem. Nem általánosságban, hanem azt a konkrét dolgot is, ami most eszembe jut. Krisztusban elrendezted, és nem tartod számon.": "Herr, danke, dass du mir vergeben hast. Nicht allgemein, sondern auch das ganz Bestimmte, das mir gerade einfällt. In Christus hast du es erledigt, und du rechnest es mir nicht mehr an.",
  "Kire haragszol még? Mondd ki a nevét Isten előtt, és valld meg, ha keserűséget hordozol.": "Auf wen bist du noch zornig? Sprich den Namen vor Gott aus und bekenne es, wenn du Bitterkeit in dir trägst.",
  "Uram, van valaki, akire még haragszom, és a nevét most kimondom előtted. Megvallom, hogy keserűséget hordozok, és ez nem tőled van. Vedd ki a szívemből, mert magam nem tudom.": "Herr, es gibt jemanden, auf den ich noch zornig bin, und ich spreche den Namen jetzt vor dir aus. Ich bekenne, dass ich Bitterkeit in mir trage, und die kommt nicht von dir. Nimm sie aus meinem Herzen, denn ich selbst kann es nicht.",
  "Olvasd el. A mérce: ahogy Isten Krisztusban nekem.": "Lies es. Der Maßstab: wie Gott mir in Christus vergeben hat.",
  "Uram, te azt mondod, úgy bocsássak meg, ahogy te megbocsátottál nekem Krisztusban. Ez a mérce, és én ebből élek. Nem azért bocsátok meg, mert a másik megérdemli, hanem mert én is kegyelmet kaptam.": "Herr, du sagst, ich soll so vergeben, wie du mir in Christus vergeben hast. Das ist der Maßstab, und davon lebe ich. Ich vergebe nicht, weil der andere es verdient, sondern weil auch ich Gnade empfangen habe.",
  "Kérj erőt a megbocsátásra, és áldást arra az emberre. Ha túl nehéz, csak ezt mondd: segíts akarni.": "Bitte um Kraft zur Vergebung und um Segen für diesen Menschen. Wenn es zu schwer ist, sag nur: Hilf mir, es zu wollen.",
  "Uram, adj erőt, hogy megbocsássak annak, akit most eléd hoztam, és áldd meg őt. Ha még nem tudom teljesen, segíts akarni. Tedd meg bennem, amit én még nem tudok megtenni.": "Herr, gib mir Kraft, dem zu vergeben, den ich jetzt vor dich gebracht habe, und segne ihn. Wenn ich es noch nicht ganz kann, hilf mir, es zu wollen. Tu in mir, was ich selbst noch nicht tun kann.",
  "Csendben engedd el, ami a kezedben volt.": "Lass in der Stille los, was du in der Hand hattest.",
  "Uram, elengedem. A kezedbe teszem, nem az enyémben tartom.": "Herr, ich lasse es los. Ich lege es in deine Hand und halte es nicht mehr in meiner.",
  "Megújuló erő": "Neue Kraft",
  "Köszönd meg a hetet, és azt, hogy végigvitt rajta, akkor is, ha elfáradtál.": "Danke für die Woche und dafür, dass er dich hindurchgetragen hat, auch wenn du müde geworden bist.",
  "Uram, köszönöm, hogy végigvittél ezen a héten. Volt, hogy elfáradtam, de te nem fáradtál el mellettem. Köszönöm a mai napot, amikor meg lehet állni.": "Herr, danke, dass du mich durch diese Woche getragen hast. Manchmal wurde ich müde, aber du wurdest neben mir nicht müde. Danke für den heutigen Tag, an dem ich innehalten darf.",
  "Hol pótoltad a saját erőddel azt, amit tőle kellett volna várnod? Mondd el.": "Wo hast du mit eigener Kraft ersetzt, was du von ihm hättest erwarten sollen? Sag es ihm.",
  "Uram, megvallom, hogy sokszor a saját erőmből próbáltam pótolni azt, amit tőled kellett volna várnom. Hajtottam, mert nem bíztam. Bocsásd meg, és taníts várni rád.": "Herr, ich bekenne, dass ich oft mit eigener Kraft ersetzen wollte, was ich von dir hätte erwarten sollen. Ich habe mich angetrieben, weil ich nicht vertraut habe. Vergib mir und lehre mich, auf dich zu warten.",
  "Olvasd el lassan. Az erő azoknak újul meg, akik benne bíznak, nem akik jobban igyekeznek.": "Lies es langsam. Die Kraft erneuert sich bei denen, die ihm vertrauen, nicht bei denen, die sich mehr anstrengen.",
  "Uram, te azt mondod, hogy akik benned bíznak, azok ereje megújul. Nem akik jobban igyekeznek, hanem akik bíznak. Én is ezt választom: nem több erőlködés, hanem több bizalom.": "Herr, du sagst, dass die, die auf dich vertrauen, neue Kraft bekommen. Nicht die, die sich mehr anstrengen, sondern die, die vertrauen. Dafür entscheide ich mich auch: nicht mehr Anstrengung, sondern mehr Vertrauen.",
  "Kérj megújulást a testednek, a gondolataidnak és a hitednek a jövő hétre.": "Bitte um Erneuerung für deinen Körper, deine Gedanken und deinen Glauben für die kommende Woche.",
  "Uram, újítsd meg az erőmet a jövő hétre: a testemet, a gondolataimat és a hitemet. Add, hogy ne lankadjak meg a hosszú úton, és ne fáradjak el a mindennapiban. Te vagy a forrás, nem én.": "Herr, erneuere meine Kraft für die kommende Woche: meinen Körper, meine Gedanken und meinen Glauben. Lass mich auf dem langen Weg nicht matt werden und im Alltag nicht müde. Du bist die Quelle, nicht ich.",
  "Pihenj csendben, mint aki vár az Úrra.": "Ruhe in der Stille wie jemand, der auf den Herrn wartet.",
  "Uram, várok rád. Csendben, nem sietve.": "Herr, ich warte auf dich. In der Stille, ohne Eile.",
  "Világosságom és üdvösségem": "Mein Licht und mein Heil",
  "Köszönd meg, hogy van világosságod, amikor minden más sötét.": "Danke dafür, dass du ein Licht hast, wenn alles andere dunkel ist.",
  "Uram, köszönöm, hogy te vagy a világosságom, amikor körülöttem sötét van. Köszönöm, hogy az üdvösségem nem rajtam áll, hanem rajtad. Jó ezt egy vasárnap reggel kimondani.": "Herr, danke, dass du mein Licht bist, wenn es um mich herum dunkel ist. Danke, dass mein Heil nicht an mir hängt, sondern an dir. Es ist gut, das an einem Sonntagmorgen auszusprechen.",
  "Mitől remegtél a héten, ami nagyobbnak látszott, mint Isten? Valld meg.": "Wovor hast du diese Woche gezittert, weil es größer aussah als Gott? Bekenne es.",
  "Uram, megvallom, hogy voltak dolgok a héten, amik nagyobbnak látszottak, mint te. Remegtem tőlük, mintha te nem lennél az erősségem. Bocsáss meg, és állítsd helyre bennem az arányokat.": "Herr, ich bekenne, dass es diese Woche Dinge gab, die größer aussahen als du. Ich habe vor ihnen gezittert, als wärst du nicht meine Stärke. Vergib mir und rücke in mir die Verhältnisse wieder zurecht.",
  "Olvasd el, és válaszolj a kérdésre: kitől féljek?": "Lies es und beantworte die Frage: Vor wem sollte ich mich fürchten?",
  "Uram, te kérdezed: kitől féljek? És a válasz az, hogy senkitől, mert te vagy az életem erőssége. Nem azért, mert bátor vagyok, hanem mert a tiéd vagyok.": "Herr, du fragst: Vor wem sollte ich mich fürchten? Und die Antwort ist: vor niemandem, denn du bist meines Lebens Kraft. Nicht weil ich mutig bin, sondern weil ich dir gehöre.",
  "Kérd, hogy a jövő héten a te világosságában lásd a dolgokat, és hogy a házában lakjon a szíved.": "Bitte darum, die Dinge in der kommenden Woche in seinem Licht zu sehen, und dass dein Herz in seinem Haus wohnt.",
  "Uram, add, hogy a jövő héten a te világosságodban lássam a dolgokat, ne a félelem fényében. Legyen a szívem otthon nálad, akármerre jár a testem. Ezt kérem egyedül.": "Herr, hilf mir, die Dinge in der kommenden Woche in deinem Licht zu sehen, nicht im Licht der Angst. Lass mein Herz bei dir zu Hause sein, wohin mein Körper auch geht. Darum allein bitte ich.",
  "Maradj csendben az ő világosságában.": "Bleib still in seinem Licht.",
  "Uram, a világosságodban vagyok. Itt maradok.": "Herr, ich bin in deinem Licht. Hier bleibe ich.",
  "A Lélek gyümölcse": "Die Frucht des Geistes",
  "Köszönd meg, hogy a Szentlélek benned lakik, és nem egyedül kell jóvá lenned.": "Danke dafür, dass der Heilige Geist in dir wohnt und du nicht allein gut werden musst.",
  "Uram, köszönöm, hogy a Szentlelked bennem lakik, és nem egyedül kell jóvá lennem. Köszönöm, hogy a változás nem az én görcsös igyekezetem, hanem a te munkád bennem.": "Herr, danke, dass dein Heiliger Geist in mir wohnt und ich nicht allein gut werden muss. Danke, dass die Veränderung nicht mein verkrampftes Bemühen ist, sondern dein Werk in mir.",
  "A kilenc gyümölcsből melyik hiányzott a legjobban a hétvégén? Mondd el.": "Welche der neun Früchte hat am Wochenende am meisten gefehlt? Sag es ihm.",
  "Uram, végignézem a Lélek gyümölcseit, és tudom, melyik hiányzott a hétvégén. Kimondom előtted, mi volt az. Bocsásd meg, és ne hagyd, hogy ez legyen a végső szó rólam.": "Herr, ich gehe die Frucht des Geistes durch und weiß, was am Wochenende gefehlt hat. Ich spreche es vor dir aus. Vergib mir und lass das nicht das letzte Wort über mich sein.",
  "Olvasd el lassan a kilenc szót. Melyiket kéri tőled Isten ezen a héten?": "Lies die neun Worte langsam. Welches erbittet Gott diese Woche von dir?",
  "Uram, kilenc szót olvasok, és mindegyik a te természeted. Nem én termelem, a te Lelked termi bennem, ha vele járok. Mutasd meg, melyiket akarod ezen a héten növelni bennem.": "Herr, ich lese neun Worte, und jedes ist dein Wesen. Ich bringe sie nicht selbst hervor, dein Geist lässt sie in mir wachsen, wenn ich mit ihm gehe. Zeig mir, welches du in dieser Woche in mir wachsen lassen willst.",
  "Kérd azt az egy gyümölcsöt a hétre, és nevezd meg a helyzetet, ahol szükséged lesz rá.": "Bitte um diese eine Frucht für die Woche und nenne die Situation, in der du sie brauchen wirst.",
  "Uram, azt az egy gyümölcsöt kérem erre a hétre, amit most mutattál. Tudom, melyik helyzetben lesz rá szükségem, és eléd hozom azt is. Teremd meg bennem, amit én nem tudok előállítani.": "Herr, für diese Woche bitte ich um die eine Frucht, die du mir gerade gezeigt hast. Ich weiß, in welcher Situation ich sie brauchen werde, und auch die bringe ich vor dich. Lass in mir wachsen, was ich selbst nicht hervorbringen kann.",
  "Csendben engedd, hogy a Lélek dolgozzon.": "Lass in der Stille den Geist wirken.",
  "Uram, dolgozz bennem. Nem állok az utadba.": "Herr, wirke in mir. Ich stelle mich dir nicht in den Weg.",
  "Gyors a hallásra": "Schnell zum Hören",
  "Köszönd meg azokat, akik meghallgattak téged, és azt, hogy Isten mindig meghallgat.": "Danke für die Menschen, die dir zugehört haben, und dafür, dass Gott immer zuhört.",
  "Uram, köszönöm, hogy te mindig meghallgatsz, mielőtt szólnék. És köszönöm azokat az embereket, akik meghallgattak engem, amikor beszélnem kellett. A meghallgatás ajándék, és te adod.": "Herr, danke, dass du mir immer zuhörst, noch bevor ich spreche. Und danke für die Menschen, die mir zugehört haben, als ich reden musste. Gehört zu werden ist ein Geschenk, und du gibst es.",
  "Hol szóltál túl gyorsan, hol haragudtál túl hamar a héten? Nevezd meg az esetet, és valld meg.": "Wo hast du diese Woche zu schnell geredet, wo bist du zu schnell zornig geworden? Nenne die Situation und bekenne es.",
  "Uram, megvallom, hogy voltak percek, amikor gyorsabban szóltam, mint hallgattam, és hamarabb haragudtam, mint értettem. Egy konkrét eset most eszembe jut, és eléd teszem. Bocsásd meg, és adj szelíd nyelvet.": "Herr, ich bekenne, dass es Augenblicke gab, in denen ich schneller geredet als zugehört habe und schneller zornig wurde, als ich verstanden habe. Eine konkrete Situation fällt mir jetzt ein, und ich lege sie dir hin. Vergib mir und gib mir eine sanfte Zunge.",
  "Olvasd el a három sorrendet: gyors, késedelmes, késedelmes. Melyik a te gyenge pontod?": "Lies die drei in ihrer Reihenfolge: schnell, langsam, langsam. Welches ist dein schwacher Punkt?",
  "Uram, te azt kéred: gyors legyek a hallásra, késedelmes a szólásra és a haragra. Tudom, hol vagyok ebben gyenge. Taníts először téged hallgatni, aztán az embereket, és csak utána szólni.": "Herr, du willst, dass ich schnell zum Hören bin, langsam zum Reden und langsam zum Zorn. Ich weiß, wo ich darin schwach bin. Lehre mich, zuerst auf dich zu hören, dann auf die Menschen, und erst danach zu reden.",
  "Kérj türelmes szívet a mai beszélgetéseidhez, és egy konkrét emberhez, akivel nehezen beszélsz.": "Bitte um ein geduldiges Herz für die heutigen Gespräche und für einen bestimmten Menschen, mit dem dir das Reden schwerfällt.",
  "Uram, adj türelmes szívet a mai beszélgetésekhez. Van valaki, akivel nehezen beszélek, őt külön eléd hozom: segíts meghallgatnom, mielőtt válaszolok. Legyen a szavam békesség, ne tűz.": "Herr, gib mir ein geduldiges Herz für die heutigen Gespräche. Es gibt jemanden, mit dem mir das Reden schwerfällt, ihn bringe ich besonders vor dich: Hilf mir zuzuhören, bevor ich antworte. Lass meine Worte Frieden bringen, nicht Feuer.",
  "Csendben hallgass, ez a gyakorlat maga.": "Höre in der Stille, das ist die Übung selbst.",
  "Uram, hallgatlak. Most nem beszélek.": "Herr, ich höre auf dich. Jetzt rede ich nicht.",
  "Nézd a madarakat": "Seht die Vögel an",
  "Köszönd meg a mindennapi gondviselést: az ételt, a munkát, a hónap végéig kitartó erőt.": "Danke für die tägliche Versorgung: für das Essen, die Arbeit und die Kraft, die bis zum Monatsende gereicht hat.",
  "Uram, köszönöm a mindennapi gondviselésedet: az ételt az asztalon, a munkát, ami van, és az erőt, ami kitartott a hónap végéig. Nem magamnak köszönhetem, neked.": "Herr, danke für deine tägliche Versorgung: für das Essen auf dem Tisch, für die Arbeit, die ich habe, und für die Kraft, die bis zum Monatsende gereicht hat. Das verdanke ich nicht mir, sondern dir.",
  "Hol aggódtál a jövő miatt úgy, mintha az Atya elfelejtett volna? Mondd el.": "Wo hast du dir Sorgen um die Zukunft gemacht, als hätte der Vater dich vergessen? Sag es ihm.",
  "Uram, megvallom, hogy aggódtam a jövő miatt, mintha elfelejtettél volna. Számoltam, forgattam, nem aludtam, és közben nem néztem rád. Bocsásd meg a kishitűségemet.": "Herr, ich bekenne, dass ich mir Sorgen um die Zukunft gemacht habe, als hättest du mich vergessen. Ich habe gerechnet, gegrübelt, nicht geschlafen und dabei nicht auf dich geschaut. Vergib mir meinen Kleinglauben.",
  "Olvasd el. Figyeld meg a kérdést a végén: nem vagytok-e sokkal különbek?": "Lies es. Achte auf die Frage am Ende: Seid ihr nicht viel mehr wert?",
  "Uram, te a madarakra mutatsz, és azt kérdezed, nem vagyok-e sokkal különb azoknál. A te gyermeked vagyok, nem csak a teremtményed. Ha őket eltartod, engem sem hagysz el.": "Herr, du zeigst auf die Vögel und fragst, ob ich nicht viel mehr wert bin als sie. Ich bin dein Kind, nicht nur dein Geschöpf. Wenn du sie ernährst, wirst du mich auch nicht verlassen.",
  "Hozd eléje az anyagi és gyakorlati gondjaidat, egyenként, és kérd, hogy ő tartson el.": "Bring deine finanziellen und praktischen Sorgen vor ihn, eine nach der anderen, und bitte ihn, für dich zu sorgen.",
  "Uram, eléd hozom az anyagi és gyakorlati gondjaimat, egyenként, ahogy vannak. Nem kérek fölösleget, azt kérem, hogy te tarts el, ahogy a madarakat. Adj munkát a kezemnek, és bizalmat a szívemnek.": "Herr, ich bringe dir meine finanziellen und praktischen Sorgen, eine nach der anderen, so wie sie sind. Ich bitte nicht um Überfluss, sondern darum, dass du für mich sorgst wie für die Vögel. Gib meinen Händen Arbeit und meinem Herzen Vertrauen.",
  "Csendben nézz ki az ablakon, vagy képzeld el: ő gondot visel.": "Schau in der Stille aus dem Fenster oder stell es dir vor: Er sorgt für dich.",
  "Uram, te gondot viselsz rám. Csendben ezt hagyom bennem leülepedni.": "Herr, du sorgst für mich. In der Stille lasse ich das in mir zur Ruhe kommen.",
  "Imádság a vezetőkért": "Gebet für die Verantwortlichen",
  "Köszönd meg a békét, amiben élsz, a rendet, ami működik, és azokat, akik szolgálnak benne.": "Danke für den Frieden, in dem du lebst, für die Ordnung, die funktioniert, und für die, die darin dienen.",
  "Uram, köszönöm a békét, amiben élek, és a rendet, ami működik körülöttem, akkor is, ha nem tökéletes. Köszönöm azokat, akik ebben szolgálnak, az orvosokat, a tanárokat, a tisztviselőket. Rajtuk keresztül is gondot viselsz.": "Herr, danke für den Frieden, in dem ich lebe, und für die Ordnung, die um mich herum funktioniert, auch wenn sie nicht vollkommen ist. Danke für die, die darin dienen: die Ärzte, die Lehrer, die Beamten. Auch durch sie sorgst du für uns.",
  "Hol ítéltél vagy szidtál vezetőket imádság helyett? Valld meg.": "Wo hast du über Verantwortliche geurteilt oder geschimpft, statt für sie zu beten? Bekenne es.",
  "Uram, megvallom, hogy könnyebben szidtam a vezetőket, mint imádkoztam értük. Ítéltem ott, ahol könyörögnöm kellett volna. Bocsásd meg, és adj szívet, ami inkább kér, mint vádol.": "Herr, ich bekenne, dass es mir leichter fiel, über die Verantwortlichen zu schimpfen, als für sie zu beten. Ich habe geurteilt, wo ich hätte bitten sollen. Vergib mir und gib mir ein Herz, das lieber bittet als anklagt.",
  "Olvasd el. Mindenek előtt: ez a sorrend. És mindenkiért, nem csak azokért, akiket kedvelünk.": "Lies es. Vor allen Dingen: Das ist die Reihenfolge. Und für alle, nicht nur für die, die wir mögen.",
  "Uram, te azt kéred, hogy mindenekelőtt imádkozzak minden emberért, a vezetőkért is. Nem azért, mert egyetértek velük, hanem mert te így akarod. Ez nem politika, ez közbenjárás.": "Herr, du bittest mich, vor allen Dingen für alle Menschen zu beten, auch für die Regierenden. Nicht weil ich mit ihnen einverstanden bin, sondern weil du es so willst. Das ist keine Politik, das ist Fürbitte.",
  "Imádkozz a saját országod vezetőiért, a településedért, a gyülekezeted vezetőiért, és azokért, akik háborús országokban döntenek.": "Bete für die Verantwortlichen deines eigenen Landes, für deinen Wohnort, für die Leitung deiner Gemeinde und für die, die in Ländern im Krieg Entscheidungen treffen.",
  "Uram, eléd hozom azokat, akik az országomat vezetik, bármilyen oldalon állnak: adj nekik bölcsességet, igazságot és félelmet tőled. Imádkozom a településemért és azokért, akik ott döntenek. Imádkozom a gyülekezetem vezetőiért, hogy hűek maradjanak. És imádkozom azokért, akik háborús országokban döntenek életről és halálról: fordítsd a szívüket a béke felé.": "Herr, ich bringe dir die, die mein Land regieren, auf welcher Seite sie auch stehen: Gib ihnen Weisheit, Gerechtigkeit und Ehrfurcht vor dir. Ich bete für meinen Wohnort und für die, die dort entscheiden. Ich bete für die Leitung meiner Gemeinde, dass sie treu bleibt. Und ich bete für die, die in Ländern im Krieg über Leben und Tod entscheiden: Lenke ihre Herzen zum Frieden.",
  "Csendben kérj békét, hogy nyugodalmas életet élhessünk.": "Bitte in der Stille um Frieden, damit wir ein ruhiges und stilles Leben führen können.",
  "Uram, adj békét, hogy csendes és nyugodalmas életet élhessünk. Ámen.": "Herr, gib Frieden, damit wir ein ruhiges und stilles Leben führen können. Amen.",
  "A reménység Istene": "Der Gott der Hoffnung",
  "Péntek van, a hála napja. Köszönd meg a hét öt jó pillanatát, és köszönd meg a reménységet, ami nem tőled függ.": "Es ist Freitag, der Tag des Dankes. Danke für fünf gute Momente der Woche und danke für die Hoffnung, die nicht von dir abhängt.",
  "Uram, végigmegyek a héten, és megköszönöm az öt legjobb pillanatát, egyiket a másik után. És köszönöm, hogy a reménységem nem a körülményeimtől függ, hanem tőled. Te vagy a reménység Istene.": "Herr, ich gehe die Woche durch und danke dir für ihre fünf besten Momente, einen nach dem anderen. Und danke, dass meine Hoffnung nicht von meinen Umständen abhängt, sondern von dir. Du bist der Gott der Hoffnung.",
  "Hol engedted el a reményt a héten, és hol lett belőle keserű beszéd? Mondd el.": "Wo hast du diese Woche die Hoffnung losgelassen, und wo sind daraus bittere Worte geworden? Sag es ihm.",
  "Uram, megvallom, hogy voltak percek, amikor elengedtem a reményt, és keserű lett a beszédem. Nem hittem, hogy változhat bármi. Bocsásd meg, és töltsd meg újra a szívemet.": "Herr, ich bekenne, dass es Augenblicke gab, in denen ich die Hoffnung losgelassen habe und meine Worte bitter wurden. Ich habe nicht geglaubt, dass sich etwas ändern kann. Vergib mir und fülle mein Herz neu.",
  "Olvasd el. Az öröm és a békesség a hitből jön, a reménység a Lélek erejéből.": "Lies es. Freude und Frieden kommen aus dem Glauben, die Hoffnung aus der Kraft des Geistes.",
  "Uram, te a reménység Istene vagy, és örömmel, békességgel töltesz be a hitben. Nem én termelem a reményt, a Lelked adja. Hadd bővölködjek benne, ne csak megéljek.": "Herr, du bist der Gott der Hoffnung, und du erfüllst mich im Glauben mit Freude und Frieden. Ich bringe die Hoffnung nicht selbst hervor, dein Geist schenkt sie. Lass mich überreich daran werden, nicht nur irgendwie durchkommen.",
  "Kérj reménységet egy konkrét ügyben, ami most reménytelennek látszik.": "Bitte um Hoffnung in einer konkreten Sache, die gerade hoffnungslos aussieht.",
  "Uram, van egy ügy, ami most reménytelennek látszik, és eléd hozom. Adj reménységet benne, nem vak optimizmust, hanem a te Lelked erejét. Mutasd meg, hol vagy benne te.": "Herr, es gibt eine Sache, die gerade hoffnungslos aussieht, und ich bringe sie vor dich. Gib mir Hoffnung darin, keinen blinden Optimismus, sondern die Kraft deines Geistes. Zeig mir, wo du darin bist.",
  "Csendben hagyd, hogy a béke betöltsön.": "Lass dich in der Stille mit Frieden erfüllen.",
  "Uram, töltsd be a szívemet békével. Csendben várom.": "Herr, erfülle mein Herz mit Frieden. Ich warte in der Stille.",
  "Vizsgálj meg": "Erforsche mich",
  "Köszönd meg, hogy Isten teljesen ismer, és mégis szeret.": "Danke dafür, dass Gott dich ganz kennt und dich trotzdem liebt.",
  "Uram, köszönöm, hogy teljesen ismersz, a gondolataimat is, és mégis szeretsz. Előtted nem kell szerepet játszanom. Ez a legnagyobb nyugalom, ami egy hét végén létezik.": "Herr, danke, dass du mich ganz kennst, auch meine Gedanken, und mich trotzdem liebst. Vor dir muss ich keine Rolle spielen. Das ist die größte Ruhe, die es am Ende einer Woche gibt.",
  "Kérd, hogy ő mutassa meg, mit nem látsz magadban. Várj, és ami eszedbe jut, azt valld meg.": "Bitte ihn, dir zu zeigen, was du an dir selbst nicht siehst. Warte, und bekenne, was dir in den Sinn kommt.",
  "Uram, vizsgálj meg, és mutasd meg, mit nem látok magamban. Nem védekezem, várok. Ami most eszembe jut, azt megvallom, és kérem, hogy tisztítsd ki belőlem.": "Herr, erforsche mich und zeig mir, was ich an mir selbst nicht sehe. Ich verteidige mich nicht, ich warte. Was mir jetzt in den Sinn kommt, bekenne ich, und ich bitte dich, mich davon zu reinigen.",
  "Olvasd el lassan. Ez egy bizalmi kérés: aki szeret, azt engedjük vizsgálni.": "Lies es langsam. Das ist eine Bitte aus Vertrauen: Wer uns liebt, den lassen wir uns erforschen.",
  "Uram, Dávid azt kérte, hogy vizsgáld meg, és én is ezt kérem. Nem félek a tekintetedtől, mert tudom, hogy szeretettel nézel. Vezess az örökkévalóság útján, ne csak a mai napon át.": "Herr, David hat dich gebeten, ihn zu erforschen, und ich bitte dich um dasselbe. Ich fürchte deinen Blick nicht, denn ich weiß, dass du mich mit Liebe ansiehst. Leite mich auf ewigem Weg, nicht nur durch den heutigen Tag.",
  "Kérd, hogy a jövő héten ott vezessen, ahol a legkönnyebb letérni.": "Bitte ihn, dich in der kommenden Woche dort zu führen, wo es am leichtesten ist, vom Weg abzukommen.",
  "Uram, tudom, hol a legkönnyebb letérnem a jövő héten, és eléd hozom. Ott vezess, ott tarts meg. Add, hogy a szívem ne menjen oda, ahová a lábam már ne lépjen.": "Herr, ich weiß, wo ich in der kommenden Woche am leichtesten vom Weg abkomme, und ich bringe es vor dich. Führe mich dort, halte mich dort fest. Lass mein Herz nicht dorthin gehen, wohin mein Fuß nicht mehr treten soll.",
  "Csendben hagyd, hogy ő nézzen rád, és pihenj ebben.": "Lass ihn in der Stille auf dich schauen und ruhe darin.",
  "Uram, nézz rám. Én csendben maradok a tekinteted alatt.": "Herr, sieh mich an. Ich bleibe still unter deinem Blick.",
  "Hálaadással a kapuin": "Mit Danken zu seinen Toren",
  "Vasárnap van. Lépj be hálával: köszönd meg, aki ő, nem csak azt, amit ad.": "Es ist Sonntag. Tritt mit Dank ein: Danke ihm für das, was er ist, nicht nur für das, was er gibt.",
  "Uram, hálaadással lépek eléd ezen a reggelen. Köszönöm, aki vagy: hű, jó, irgalmas, a kezdettől a végig ugyanaz. Nem csak az ajándékaidat áldom, hanem a nevedet.": "Herr, mit Danken trete ich an diesem Morgen vor dich. Danke für das, was du bist: treu, gut, barmherzig, derselbe vom Anfang bis zum Ende. Ich preise nicht nur deine Gaben, sondern deinen Namen.",
  "Mi tart vissza attól, hogy teljes szívvel dicsérd? Mondd el neki.": "Was hält dich davon ab, ihn von ganzem Herzen zu loben? Sag es ihm.",
  "Uram, tudom, mi tart vissza attól, hogy teljes szívvel dicsérjelek. Fáradtság, sértődés, vagy egy el nem rendezett dolog. Eléd teszem, hogy ne álljon a kapuban.": "Herr, ich weiß, was mich davon abhält, dich von ganzem Herzen zu loben. Müdigkeit, Kränkung oder etwas Ungeklärtes. Ich lege es dir hin, damit es nicht im Tor steht.",
  "Olvasd el. Kapu, tornác, hála, dicséret: egyre közelebb visz hozzá.": "Lies es. Tore, Vorhöfe, Dank, Lob: Alles bringt dich ihm näher.",
  "Uram, te hívsz, hogy a kapuidon hálaadással, az udvarodba dicsérettel lépjek be. Minden lépés közelebb visz hozzád. Áldom a nevedet, mert te vagy az Isten.": "Herr, du rufst mich, zu deinen Toren mit Danken und zu deinen Vorhöfen mit Loben einzutreten. Jeder Schritt bringt mich näher zu dir. Ich lobe deinen Namen, denn du bist Gott.",
  "Kérj a gyülekezetedért, a mai istentiszteletért, és azokért, akik ma nem tudnak eljönni.": "Bete für deine Gemeinde, für den heutigen Gottesdienst und für die, die heute nicht kommen können.",
  "Uram, eléd hozom a gyülekezetemet és a mai istentiszteletet: szólj, és add, hogy halljuk. Imádkozom azokért, akik ma nem tudnak eljönni, mert betegek vagy távol vannak. Légy velük ott, ahol vannak.": "Herr, ich bringe dir meine Gemeinde und den heutigen Gottesdienst: Sprich, und hilf uns zu hören. Ich bete für die, die heute nicht kommen können, weil sie krank oder weit weg sind. Sei bei ihnen dort, wo sie sind.",
  "Maradj csendben az ő udvarában.": "Bleib still in seinen Vorhöfen.",
  "Uram, itt vagyok az udvarodban. Jó itt lenni.": "Herr, hier bin ich in deinen Vorhöfen. Es ist gut, hier zu sein.",
  "Mint az Úrnak": "Als dem Herrn",
  "Köszönd meg a munkádat, azt is, ami fárasztó. Ez a hely, ahol szolgálhatsz.": "Danke für deine Arbeit, auch für das, was ermüdend ist. Das ist der Ort, an dem du dienen kannst.",
  "Uram, köszönöm a munkámat, azt is, ami fárasztó és láthatatlan. Köszönöm, hogy van mit tennem, és van, aki számít rá. Ez a hely, ahol téged szolgálhatlak.": "Herr, danke für meine Arbeit, auch für das, was ermüdend und unsichtbar ist. Danke, dass ich etwas zu tun habe und dass jemand darauf zählt. Das ist der Ort, an dem ich dir dienen kann.",
  "Hol dolgoztál csak a látszatért, vagy csak félszívvel? Valld meg.": "Wo hast du nur für den Schein oder nur halbherzig gearbeitet? Bekenne es.",
  "Uram, megvallom, hogy voltak napok, amikor csak a látszatért dolgoztam, vagy félszívvel. Embereknek akartam megfelelni, nem neked. Bocsásd meg, és fordítsd a szívemet feléd a munkámban.": "Herr, ich bekenne, dass es Tage gab, an denen ich nur für den Schein oder halbherzig gearbeitet habe. Ich wollte Menschen gefallen, nicht dir. Vergib mir und richte mein Herz bei meiner Arbeit auf dich aus.",
  "Olvasd el. Mint az Úrnak: ez az egyetlen szó megváltoztatja a hétfőt.": "Lies es. Als dem Herrn: Diese wenigen Worte verändern deinen Montag.",
  "Uram, amit ma teszek, azt neked teszem, nem embereknek. Ez a mondat megváltoztatja a hétfőmet. A legkisebb feladat is istentisztelet, ha neked végzem.": "Herr, was ich heute tue, tue ich für dich, nicht für Menschen. Dieser Satz verändert meinen Montag. Auch die kleinste Aufgabe ist Gottesdienst, wenn ich sie für dich tue.",
  "Hozd eléje a hét munkáját, a nehéz feladatot, és azokat, akikkel dolgozol.": "Bring die Arbeit der Woche vor ihn, die schwierige Aufgabe und die Menschen, mit denen du arbeitest.",
  "Uram, eléd hozom a hét munkáját és azt a feladatot, ami a legnehezebb lesz. Adj hozzá erőt és tiszta szándékot. Áldd meg azokat, akikkel együtt dolgozom, és add, hogy jó legyen velem dolgozni.": "Herr, ich bringe dir die Arbeit dieser Woche und die Aufgabe, die am schwersten sein wird. Gib mir Kraft dafür und eine lautere Absicht. Segne die, mit denen ich zusammenarbeite, und lass es gut sein, mit mir zu arbeiten.",
  "Csendben ajánld fel a napot neki.": "Bring ihm in der Stille den Tag dar.",
  "Uram, ez a nap a tiéd. Lélekből, neked.": "Herr, dieser Tag gehört dir. Von Herzen, für dich.",
  "Békesség, amit a világ nem ad": "Frieden, den die Welt nicht gibt",
  "Köszönd meg azt a békességet, amit megéltél, amikor emberileg nem volt rá ok.": "Danke für den Frieden, den du erlebt hast, als es menschlich gesehen keinen Grund dafür gab.",
  "Uram, köszönöm azokat a pillanatokat, amikor békém volt, pedig emberileg nem volt rá ok. Az a te békességed volt, nem az enyém. Köszönöm, hogy nem a világtól függ.": "Herr, danke für die Augenblicke, in denen ich Frieden hatte, obwohl es menschlich gesehen keinen Grund dafür gab. Das war dein Frieden, nicht meiner. Danke, dass er nicht von der Welt abhängt.",
  "Mi nyugtalanítja a szívedet? Mondd el, és valld meg, ha a békességet máshol kerested: a kontrollban, a zajban, a menekülésben.": "Was beunruhigt dein Herz? Sag es ihm und bekenne es, wenn du den Frieden woanders gesucht hast: in der Kontrolle, im Lärm, in der Flucht.",
  "Uram, megvallom, mi nyugtalanítja a szívemet, és azt is, hogy a békét máshol kerestem: a kontrollban, a zajban, a menekülésben. Nem tőled vártam. Bocsásd meg, és add vissza a békédet.": "Herr, ich bekenne, was mein Herz beunruhigt, und auch, dass ich den Frieden woanders gesucht habe: in der Kontrolle, im Lärm, in der Flucht. Ich habe ihn nicht von dir erwartet. Vergib mir und gib mir deinen Frieden zurück.",
  "Olvasd el. Nem úgy, ahogy a világ adja: ez a különbség.": "Lies es. Nicht wie die Welt gibt: Das ist der Unterschied.",
  "Uram, te azt mondod, az én békességemet adom nektek, nem úgy, ahogy a világ adja. A világ békéje a baj hiánya, a tiéd a te jelenléted a bajban. Ezt kérem, nem a másikat.": "Herr, du sagst: Meinen Frieden gebe ich euch, nicht wie die Welt gibt. Der Frieden der Welt ist das Fehlen von Not, deiner ist deine Gegenwart in der Not. Darum bitte ich, nicht um den anderen.",
  "Kérd a békességét egy konkrét helyzetre, ami most feszültséget okoz.": "Bitte um seinen Frieden für eine konkrete Situation, die dir gerade Spannung bereitet.",
  "Uram, van egy helyzet, ami most feszültséget okoz, és eléd hozom. Add bele a te békességedet, amit nem lehet elvenni. Ne nyugtalankodjék a szívem, és ne féljen.": "Herr, es gibt eine Situation, die mir gerade Spannung bereitet, und ich bringe sie vor dich. Leg deinen Frieden hinein, den niemand nehmen kann. Lass mein Herz nicht erschrecken und sich nicht fürchten.",
  "Csendben fogadd el a békességét.": "Nimm in der Stille seinen Frieden an.",
  "Uram, elfogadom a békességedet. Csendben maradok benne.": "Herr, ich nehme deinen Frieden an. Ich bleibe still darin.",
  "Lámpás az úton": "Eine Leuchte auf dem Weg",
  "Köszönd meg, hogy van Igéd, és hogy olvashatod, hallgathatod, amikor akarod.": "Danke dafür, dass du Gottes Wort hast und es lesen und hören kannst, wann du willst.",
  "Uram, köszönöm, hogy van Igéd, és hogy itt van nálam, olvashatom és hallgathatom, amikor akarom. Sokaknak ez nem adatott meg. Köszönöm, hogy szólsz rajta keresztül.": "Herr, danke für dein Wort, und dass ich es hier bei mir habe und lesen und hören kann, wann ich will. Vielen ist das nicht gegeben. Danke, dass du dadurch sprichst.",
  "Mikor tetted le az Igét, és indultál el a saját fényednél? Mondd el.": "Wann hast du das Wort beiseitegelegt und bist bei deinem eigenen Licht losgegangen? Sag es ihm.",
  "Uram, megvallom, hogy sokszor letettem az Igédet, és a saját fényemnél indultam el. Aztán csodálkoztam, hogy sötét van. Bocsásd meg, és hozz vissza a lámpásodhoz.": "Herr, ich bekenne, dass ich dein Wort oft beiseitegelegt habe und bei meinem eigenen Licht losgegangen bin. Dann habe ich mich gewundert, dass es dunkel war. Vergib mir und bring mich zurück zu deiner Leuchte.",
  "Olvasd el. A lámpás a következő lépést mutatja, nem az egész utat.": "Lies es. Eine Leuchte zeigt den nächsten Schritt, nicht den ganzen Weg.",
  "Uram, a te Igéd lámpás a lábamnak. Nem az egész utat mutatja, csak a következő lépést, és ez elég. Taníts megelégedni annyi fénnyel, amennyit ma adsz.": "Herr, dein Wort ist meines Fußes Leuchte. Es zeigt nicht den ganzen Weg, nur den nächsten Schritt, und das genügt. Lehre mich, mit so viel Licht zufrieden zu sein, wie du mir heute gibst.",
  "Kérd, hogy egy konkrét kérdésben az Igéből kapj irányt, és hogy legyen időd olvasni a héten.": "Bitte darum, in einer konkreten Frage Richtung aus dem Wort zu bekommen, und dass du diese Woche Zeit zum Lesen hast.",
  "Uram, van egy kérdés, amiben irányt várok, és kérem, hogy az Igéden keresztül szólj bele. Adj időt és csendet a héten, hogy olvassalak, ne csak kapkodjak. Legyen a te szavad az első, amit meghallok.": "Herr, es gibt eine Frage, in der ich auf Richtung warte, und ich bitte dich, durch dein Wort hineinzusprechen. Gib mir diese Woche Zeit und Stille, um zu lesen, statt nur zu hetzen. Lass dein Wort das Erste sein, was ich höre.",
  "Csendben hagyd, hogy a világosság rád essen.": "Lass in der Stille das Licht auf dich fallen.",
  "Uram, világíts az ösvényemre. Csendben követlek.": "Herr, erleuchte meinen Pfad. In der Stille folge ich dir.",
  "Erősek az Úrban": "Stark im Herrn",
  "Köszönd meg, hogy a harc már eldőlt a kereszten, és te az ő erejében állsz.": "Danke dafür, dass der Kampf am Kreuz schon entschieden wurde und du in seiner Kraft stehst.",
  "Uram, köszönöm, hogy a döntő harcot te már megnyerted a kereszten. Nem én harcolok a győzelemért, hanem a győzelemből állok meg. Köszönöm a fegyverzetet, amit nem én gyártottam.": "Herr, danke, dass du den entscheidenden Kampf am Kreuz schon gewonnen hast. Ich kämpfe nicht um den Sieg, sondern ich stehe aus dem Sieg heraus fest. Danke für die Waffenrüstung, die nicht ich gemacht habe.",
  "Hol harcoltál emberek ellen, amikor nem ők voltak az igazi ellenség? Valld meg.": "Wo hast du gegen Menschen gekämpft, obwohl nicht sie der eigentliche Feind waren? Bekenne es.",
  "Uram, megvallom, hogy emberek ellen harcoltam, pedig te azt mondod, nem test és vér ellen van a harcunk. Haraggal válaszoltam ott, ahol imádkozni kellett volna. Bocsásd meg, és nyisd meg a szememet.": "Herr, ich bekenne, dass ich gegen Menschen gekämpft habe, obwohl du sagst, dass wir nicht gegen Fleisch und Blut zu kämpfen haben. Ich habe mit Zorn geantwortet, wo ich hätte beten sollen. Vergib mir und öffne mir die Augen.",
  "Olvasd el. Erősek az Úrban, nem magunkban. Megállni, nem rohamozni.": "Lies es. Stark im Herrn, nicht in uns selbst. Standhalten, nicht stürmen.",
  "Uram, te azt mondod, legyek erős az Úrban, a te hatalmas erődben, nem a magaméban. Felöltözöm, amit adsz: az igazságot, a hitet, a békesség evangéliumát. Nem rohamozok, megállok.": "Herr, du sagst, ich soll stark sein im Herrn und in der Macht deiner Stärke, nicht in meiner eigenen. Ich ziehe an, was du gibst: die Wahrheit, den Glauben, das Evangelium des Friedens. Ich stürme nicht, ich halte stand.",
  "Imádkozz közbenjárva: a családodért, hogy megálljanak, a gyülekezetedért, a kísértésben lévő testvéredért, és az üldözött keresztényekért.": "Bete fürbittend: für deine Familie, dass sie standhält, für deine Gemeinde, für einen Bruder oder eine Schwester in der Versuchung und für verfolgte Christen.",
  "Uram, imádkozom a családomért, hogy megálljanak a hitben, és te őrizd őket. Imádkozom a gyülekezetemért, hogy egy legyen és erős. Eléd hozom azt a testvéremet, akiről tudom, hogy kísértésben van: tarts meg őt. És imádkozom az üldözött keresztényekért a világban, hogy hűek maradjanak, és te légy nekik pajzs.": "Herr, ich bete für meine Familie, dass sie im Glauben standhält und du sie bewahrst. Ich bete für meine Gemeinde, dass sie eins und stark ist. Ich bringe dir den Bruder oder die Schwester, von denen ich weiß, dass sie in Versuchung stehen: Halte sie fest. Und ich bete für die verfolgten Christen in der Welt, dass sie treu bleiben und du ihr Schild bist.",
  "Csendben állj meg az ő erejében.": "Steh in der Stille fest in seiner Kraft.",
  "Uram, a te erődben állok. Megállok, és te tartasz.": "Herr, ich stehe in deiner Kraft. Ich halte stand, und du hältst mich.",
  "Minden reggel megújul": "Jeden Morgen neu",
  "A hála napja. Köszönd meg a hét minden reggelét, hogy felkelhettél, és azt, hogy ő minden reggel ugyanaz volt.": "Der Tag des Dankes. Danke für jeden Morgen der Woche, dass du aufstehen konntest, und dafür, dass er jeden Morgen derselbe war.",
  "Uram, köszönöm a hét minden reggelét, hogy felkelhettem, és hogy te minden reggel ugyanaz voltál. Köszönöm a kegyelmedet, ami nem fogyott el, pedig én sokszor elfogytam. Nagy a te hűséged.": "Herr, danke für jeden Morgen dieser Woche, dass ich aufstehen konnte und dass du jeden Morgen derselbe warst. Danke für deine Gnade, die nicht zu Ende ging, obwohl ich oft am Ende war. Groß ist deine Treue.",
  "Hol kételkedtél a hűségében a héten, mert a körülmény mást mondott? Mondd el.": "Wo hast du diese Woche an seiner Treue gezweifelt, weil die Umstände etwas anderes sagten? Sag es ihm.",
  "Uram, megvallom, hogy voltak percek a héten, amikor a körülmény mást mondott, mint te, és én a körülménynek hittem. Kételkedtem a hűségedben. Bocsásd meg, te hű maradtál akkor is.": "Herr, ich bekenne, dass es Augenblicke in dieser Woche gab, in denen die Umstände etwas anderes sagten als du, und ich habe den Umständen geglaubt. Ich habe an deiner Treue gezweifelt. Vergib mir, du bist auch da treu geblieben.",
  "Olvasd el. Ez a mondat romok közül hangzik, ezért igaz a te romjaid közt is.": "Lies es. Diese Worte wurden in Trümmern gesprochen, darum sind sie auch in deinen Trümmern wahr.",
  "Uram, ezt a mondatot valaki romok közt mondta ki, és azért igaz az én romjaim közt is. A te irgalmad nem fogyatkozik el, minden reggel megújul. Erre építem a következő reggelt is.": "Herr, diese Worte hat jemand in Trümmern ausgesprochen, und darum sind sie auch in meinen Trümmern wahr. Deine Barmherzigkeit hört nicht auf, sie ist jeden Morgen neu. Darauf baue ich auch den nächsten Morgen.",
  "Kérd, hogy az ő hűsége legyen az, amire a hétvégén építesz, és nem a saját hangulatod.": "Bitte darum, dass seine Treue das ist, worauf du am Wochenende baust, und nicht deine eigene Stimmung.",
  "Uram, add, hogy a hétvégén a te hűségedre építsek, ne a hangulatomra. Újítsd meg a kegyelmedet a holnapi reggelre is, és add, hogy észrevegyem. Te vagy az, akiben nincs változás.": "Herr, hilf mir, am Wochenende auf deine Treue zu bauen, nicht auf meine Stimmung. Erneuere deine Gnade auch für den morgigen Morgen und hilf mir, sie zu bemerken. Du bist es, bei dem es keine Veränderung gibt.",
  "Csendben nyugodj meg a hűségében.": "Komm in der Stille in seiner Treue zur Ruhe.",
  "Uram, nagy a te hűséged. Ebben nyugszom meg.": "Herr, groß ist deine Treue. Darin komme ich zur Ruhe.",
  "Aki elkezdte, elvégzi": "Der angefangen hat, wird es vollenden",
  "Nézz vissza az elmúlt négy hétre. Köszönd meg, amit Isten elkezdett benned, akkor is, ha még nincs kész.": "Schau auf die letzten vier Wochen zurück. Danke für das, was Gott in dir angefangen hat, auch wenn es noch nicht fertig ist.",
  "Uram, visszanézek az elmúlt hetekre, és köszönöm, amit elkezdtél bennem. Nincs kész, de elkezdted, és ez a tiéd. Köszönöm, hogy nem hagytad abba, amikor én abbahagytam volna.": "Herr, ich schaue auf die vergangenen Wochen zurück und danke dir für das, was du in mir angefangen hast. Es ist nicht fertig, aber du hast es angefangen, und es gehört dir. Danke, dass du nicht aufgehört hast, als ich aufgehört hätte.",
  "Hol adtad fel magad, mintha a befejezés rajtad állna? Valld meg.": "Wo hast du dich selbst aufgegeben, als hinge die Vollendung von dir ab? Bekenne es.",
  "Uram, megvallom, hogy voltak percek, amikor feladtam magamat, mintha a befejezés rajtam állna. Elfelejtettem, hogy a munka a tiéd. Bocsásd meg, és emeld fel újra a fejemet.": "Herr, ich bekenne, dass es Augenblicke gab, in denen ich mich selbst aufgegeben habe, als hinge die Vollendung von mir ab. Ich habe vergessen, dass das Werk dir gehört. Vergib mir und richte meinen Kopf wieder auf.",
  "Olvasd el lassan. Aki elkezdte, az végzi el. Nem te.": "Lies es langsam. Der es angefangen hat, wird es vollenden. Nicht du.",
  "Uram, te kezdted el bennem a jó dolgot, és te végzed el a Krisztus Jézus napjáig. Nem én tartom magam a kezedben, te tartasz engem. Ebben a bizonyosságban zárom a hetet.": "Herr, du hast das gute Werk in mir angefangen, und du wirst es vollenden bis zum Tag Christi Jesu. Nicht ich halte mich in deiner Hand, du hältst mich. In dieser Gewissheit schließe ich die Woche.",
  "Kérd, hogy a következő hetekben is folytassa benned a munkáját, és nevezd meg, hol szeretnél növekedni.": "Bitte ihn, sein Werk in dir auch in den kommenden Wochen fortzusetzen, und nenne, wo du wachsen möchtest.",
  "Uram, folytasd bennem a munkádat a következő hetekben is. Tudom, hol szeretnék növekedni, és eléd hozom, de rád bízom, hogy mit és milyen sorrendben formálsz. A te időd a jó idő.": "Herr, setze dein Werk in mir auch in den kommenden Wochen fort. Ich weiß, wo ich wachsen möchte, und ich bringe es vor dich, aber ich überlasse es dir, was du formst und in welcher Reihenfolge. Deine Zeit ist die richtige Zeit.",
  "Pihenj csendben abban, hogy Isten keze van rajtad, és ő nem engedi el.": "Ruhe in der Stille darin, dass Gottes Hand auf dir liegt und er dich nicht loslässt.",
  "Uram, a te kezed van rajtam, és te nem engedsz el. Csendben megpihenek ebben. Ámen.": "Herr, deine Hand liegt auf mir, und du lässt mich nicht los. In der Stille ruhe ich darin. Amen.",
  "Most emeld fel a tekintetedet a saját ügyeidről a világra. Ezek az események most történnek, és ott emberek vannak.": "Richte jetzt deinen Blick von deinen eigenen Anliegen auf die Welt. Diese Ereignisse geschehen gerade jetzt, und dort sind Menschen.",
  "Uram, most nem magamért kérek, hanem azokért, akiket nem ismerek, de te igen. Eléd hozom a világ bajait, amik ma történnek.": "Herr, jetzt bitte ich nicht für mich, sondern für die, die ich nicht kenne, du aber kennst. Ich bringe dir die Nöte der Welt, die heute geschehen.",
  "Uram, te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Hadd legyél az nekik is ma. Ámen.": "Herr, du bist unsere Zuflucht und Stärke, eine Hilfe in den großen Nöten, die uns getroffen haben. Sei das heute auch für sie. Amen.",
  "Most nem tudjuk, mi történik épp a világban, de valahol most is baj van. Imádkozz azokért, akikről ma nem szól a hír.": "Wir wissen gerade nicht, was in der Welt geschieht, aber irgendwo ist auch jetzt Not. Bete für die, von denen heute keine Nachrichten berichten.",
  "Uram, nem tudom, hol van ma a legnagyobb baj a világon, de te tudod. Eléd hozom azokat, akik ebben az órában földrengésben, árvízben, tűzben vagy háborúban vannak, és akikről nem szól a hír. Légy az oltalmuk, adj nekik segítséget és vigaszt, és fordítsd a világ szívét a béke felé. Te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Ámen.": "Herr, ich weiß nicht, wo heute die größte Not auf der Welt ist, aber du weißt es. Ich bringe dir die, die in dieser Stunde in einem Erdbeben, einer Flut, einem Feuer oder einem Krieg sind, und die, von denen keine Nachrichten berichten. Sei ihre Zuflucht, gib ihnen Hilfe und Trost, und lenke das Herz der Welt zum Frieden. Du bist unsere Zuflucht und Stärke, eine Hilfe in den großen Nöten, die uns getroffen haben. Amen.",
  // Imádság a világért, per event (Énok, ima-vilag-rovid.json, owner 2026-11-02 TG 33947-33954): encouragement + prayer, news labels
  "Amikor a föld megrendül, Isten nem rendül meg. Az imád most valódi kéz lehet a romok fölött.": "Wenn die Erde bebt, wankt Gott nicht. Dein Gebet kann jetzt eine echte Hand über den Trümmern sein.",
  "A víz gyorsabb az embernél, de nem gyorsabb Istennél. Egy mondat most életet menthet.": "Das Wasser ist schneller als der Mensch, aber nicht schneller als Gott. Ein Satz kann jetzt Leben retten.",
  "A tűz nem kérdez, de Isten hall. Állj oda imádságban azok mellé, akik most mindent hátrahagynak.": "Das Feuer fragt nicht, aber Gott hört. Steh im Gebet bei denen, die jetzt alles zurücklassen.",
  "Isten megígérte, hogy a víz nem lesz úr a földön. Kérd ezt most azoknak, akiknek mindent elvisz.": "Gott hat versprochen, dass das Wasser nicht über die Erde herrschen wird. Bitte jetzt darum für die, denen es alles nimmt.",
  "Jézus egy szóval elcsendesítette a vihart. Ugyanez a szó ma is érvényes, mondd ki értük.": "Jesus hat den Sturm mit einem Wort gestillt. Dieses Wort gilt auch heute, sprich es für sie aus.",
  "A hegyek Isten kezében vannak. Imádkozz, hogy az emberek időben induljanak, és legyen hová menniük.": "Die Berge sind in Gottes Hand. Bete, dass die Menschen rechtzeitig aufbrechen und einen Ort haben, wohin sie gehen können.",
  "Az aszály csendes baj, ritkán szól róla a hír. Te most mégis eléje viheted Istennek.": "Dürre ist eine stille Not, selten in den Nachrichten. Du kannst sie jetzt trotzdem vor Gott bringen.",
  "Jézus gyógyító keze ma sem rövidült meg. Állj oda a betegek és az ápolók mellé.": "Jesu heilende Hand ist auch heute nicht zu kurz. Steh den Kranken und den Pflegenden bei.",
  "Isten nem áll be egyik tömegbe sem, mindkét oldalon az övéit látja. Imádkozz oldal nélkül, békéért.": "Gott stellt sich in keine Menge, er sieht die Seinen auf beiden Seiten. Bete ohne Partei für Frieden.",
  "Boldogok a békességre igyekezők. Az imád ma ott lehet, ahová senki más nem jut el.": "Selig sind die Friedensstifter. Dein Gebet kann heute dorthin gelangen, wohin sonst niemand kommt.",
  "Uram, légy {hely} romjai alatt a várakozókkal, adj erőt a mentőknek, és vigasztald a gyászolókat.": "Herr, sei bei denen, die in {hely} unter den Trümmern warten, gib den Rettern Kraft und tröste die Trauernden.",
  "Uram, tartsd vissza a vizet, és vezesd időben magaslatra a part lakóit.": "Herr, halte das Wasser zurück und führe die Menschen an der Küste rechtzeitig auf höheres Gelände.",
  "Uram, védd meg {hely} menekülőit és tűzoltóit, és küldj esőt a lángokra.": "Herr, beschütze die Flüchtenden und die Feuerwehrleute in {hely} und sende Regen auf die Flammen.",
  "Uram, őrizd meg {hely} lakóinak életét, és adj menedéket azoknak, akiknek otthona víz alatt áll.": "Herr, bewahre das Leben der Menschen in {hely} und gib denen Zuflucht, deren Zuhause unter Wasser steht.",
  "Uram, csendesítsd le a szelet és a vizet {hely} fölött, ahogy a tanítványaid hajóján tetted.": "Herr, stille den Wind und das Wasser in der Region {hely}, wie du es auf dem Boot deiner Jünger getan hast.",
  "Uram, vezesd biztonságba {hely} lakóit, és adj bölcsességet azoknak, akik a kitelepítésről döntenek.": "Herr, führe die Menschen in {hely} in Sicherheit und gib denen Weisheit, die über die Evakuierung entscheiden.",
  "Uram, adj esőt {hely} földjére és kenyeret az asztalukra, és nyisd meg a bővölködők kezét.": "Herr, gib dem Land in der Region {hely} Regen und den Menschen Brot auf den Tisch, und öffne die Hände derer, die Überfluss haben.",
  "Uram, gyógyítsd {hely} betegeit, és adj erőt és védelmet az orvosoknak és ápolóknak.": "Herr, heile die Kranken in {hely} und gib den Ärzten und Pflegekräften Kraft und Schutz.",
  "Uram, őrizd meg {hely} életeit mindkét oldalon, és fordítsd a szíveket a béke felé.": "Herr, bewahre die Leben in {hely} auf allen Seiten und wende die Herzen zum Frieden.",
  "Uram, védd meg {hely} civiljeit és gyermekeit, gyógyítsd a sebesülteket, és adj békét, bármelyik oldalon állnak.": "Herr, beschütze die Zivilisten und Kinder in {hely}, heile die Verwundeten und schenke Frieden, auf welcher Seite sie auch stehen.",
  "Érintett terület": "Betroffene Fläche",
  "Legnagyobb szélsebesség": "Höchste Windgeschwindigkeit",
  "Események": "Ereignisse",
  "Halálos áldozatok": "Todesopfer",
  "Időszak": "Zeitraum",
  "Egy földrengés után órák döntenek életekről. Imádkozz a romok alatt lévőkért és a mentőkért.": "Nach einem Erdbeben entscheiden Stunden über Leben. Bete für die Menschen unter den Trümmern und für die Retter.",
  "Uram, eléd hozom {hely} területét, ahol megrendült a föld. Légy azokkal, akik a romok alatt várnak, és adj erőt és gyorsaságot azoknak, akik keresik őket. Vigasztald, aki ma elveszített valakit, és adj fedelet annak, akinek nem maradt.": "Herr, ich bringe dir die Region {hely}, wo die Erde gebebt hat. Sei bei denen, die unter den Trümmern warten, und gib denen Kraft und Schnelligkeit, die nach ihnen suchen. Tröste die, die heute jemanden verloren haben, und gib denen ein Dach, denen keines geblieben ist.",
  "A tűz otthonokat, erdőket és életeket visz el. Imádkozz a menekülőkért és a tűzoltókért.": "Feuer nimmt Häuser, Wälder und Leben. Bete für die Flüchtenden und für die Feuerwehrleute.",
  "Uram, eléd hozom {hely} területét, ahol tűz pusztít. Védd meg azokat, akik menekülnek, és add, hogy mindenkit elérjen a figyelmeztetés időben. Adj erőt és védelmet a tűzoltóknak, és küldj esőt és szelet úgy, ahogy csak te tudod.": "Herr, ich bringe dir die Region {hely}, wo Feuer wütet. Beschütze die, die fliehen, und lass die Warnung alle rechtzeitig erreichen. Gib den Feuerwehrleuten Kraft und Schutz, und schick Regen und Wind, wie nur du es kannst.",
  "Az árvíz lassan jön, és mindent elvisz. Imádkozz azokért, akik az otthonukat látják eltűnni.": "Das Hochwasser kommt langsam und nimmt alles mit. Bete für die, die zusehen, wie ihr Zuhause verschwindet.",
  "Uram, eléd hozom {hely} lakóit, akiket elért a víz. Őrizd meg az életüket, és adj menedéket azoknak, akiknek az otthona víz alatt áll. Légy a gyerekekkel és az idősekkel, akik nem tudnak maguktól menekülni, és adj türelmet és erőt a visszatéréshez.": "Herr, ich bringe dir die Menschen in {hely}, die das Wasser erreicht hat. Bewahre ihr Leben, und gib denen Zuflucht, deren Zuhause unter Wasser steht. Sei bei den Kindern und den Alten, die nicht allein fliehen können, und gib Geduld und Kraft für die Rückkehr.",
  "A vihar előtt a várakozás, utána a kár. Imádkozz az útjában lévőkért.": "Vor dem Sturm das Warten, danach der Schaden. Bete für die, die auf seinem Weg liegen.",
  "Uram, eléd hozom {hely} területét, amerre a vihar tart vagy ahol már lecsapott. Csendesítsd a szelet és a vizet, ahogy a tanítványaid hajóján tetted. Védd meg azokat, akik az útjában állnak, és adj gyors segítséget, ahol a tetők és a falak már leomlottak.": "Herr, ich bringe dir die Region {hely}, wohin der Sturm zieht oder wo er schon eingeschlagen hat. Stille den Wind und das Wasser, wie du es im Boot deiner Jünger getan hast. Beschütze die, die auf seinem Weg sind, und schick schnelle Hilfe, wo Dächer und Mauern schon eingestürzt sind.",
  "A hamu és a láva elől menekülni kell. Imádkozz a környék falvaiért és a kitelepítettekért.": "Vor Asche und Lava muss man fliehen. Bete für die Dörfer der Umgebung und für die Evakuierten.",
  "Uram, eléd hozom {hely} környékét, ahol a hegy kitört. Védd meg a falvakat és a városokat a láva és a hamu útjából, és adj bölcsességet azoknak, akik a kitelepítésről döntenek. Légy azokkal, akik mindent otthagytak, és adj nekik helyet, ahol megpihenhetnek.": "Herr, ich bringe dir die Gegend um {hely}, wo der Berg ausgebrochen ist. Bewahre die Dörfer und Städte vor dem Weg der Lava und der Asche, und gib denen Weisheit, die über die Evakuierung entscheiden. Sei bei denen, die alles zurückgelassen haben, und gib ihnen einen Ort, an dem sie ausruhen können.",
  "Az aszály csendes katasztrófa, nincs hírverése. Imádkozz az éhezőkért és a földművesekért.": "Die Dürre ist eine stille Katastrophe, ohne Schlagzeilen. Bete für die Hungernden und für die Bauern.",
  "Uram, eléd hozom {hely} lakóit, ahol kiszáradt a föld, és nincs mit enni. Adj esőt a földre és kenyeret az asztalra, és nyisd meg azok kezét, akiknek bőven van. Tartsd meg a gyerekeket, és adj reményt a földműveseknek, akik újra vetnek.": "Herr, ich bringe dir die Menschen in {hely}, wo die Erde ausgetrocknet ist und es nichts zu essen gibt. Gib Regen für das Land und Brot für den Tisch, und öffne die Hände derer, die reichlich haben. Erhalte die Kinder, und gib den Bauern Hoffnung, die wieder säen.",
  "A háborúban mindkét oldalon emberek halnak meg. Imádkozz a civilekért, a sebesültekért és a békéért, oldal nélkül.": "Im Krieg sterben auf beiden Seiten Menschen. Bete für die Zivilisten, die Verwundeten und für den Frieden, ohne Partei zu ergreifen.",
  "Uram, eléd hozom {hely} területét, ahol fegyverek szólnak. Védd meg a civileket, a gyerekeket, az öregeket és azokat, akiknek nincs hová menniük. Gyógyítsd a sebesülteket, vigasztald a gyászolókat, és fordítsd a döntéshozók szívét a béke felé, bármelyik oldalon állnak. Te vagy a békesség Istene, hadd legyen béke ott is.": "Herr, ich bringe dir die Region {hely}, wo Waffen sprechen. Beschütze die Zivilisten, die Kinder, die Alten und die, die nirgendwo hingehen können. Heile die Verwundeten, tröste die Trauernden, und lenke die Herzen der Entscheidungsträger zum Frieden, auf welcher Seite sie auch stehen. Du bist der Gott des Friedens, lass auch dort Frieden sein.",
  "Ahol tömegek feszülnek egymásnak, ott félelem és harag van mindkét oldalon. Imádkozz békéért és józanságért, oldal nélkül.": "Wo Menschenmengen gegeneinanderstehen, gibt es Angst und Zorn auf beiden Seiten. Bete um Frieden und Besonnenheit, ohne Partei zu ergreifen.",
  "Uram, eléd hozom {hely} területét, ahol feszültség és zavargás van az utcákon. Csendesítsd a haragot, és őrizd meg az életeket, azokét is, akik tüntetnek, és azokét is, akik rendet tartanak. Adj józanságot azoknak, akik döntenek, és add, hogy a sérelmek ne vérrel, hanem szóval oldódjanak meg.": "Herr, ich bringe dir die Region {hely}, wo es Spannungen und Unruhen auf den Straßen gibt. Besänftige den Zorn und bewahre das Leben, das derer, die protestieren, und das derer, die für Ordnung sorgen. Gib Besonnenheit denen, die entscheiden, und lass die Kränkungen nicht mit Blut, sondern mit Worten gelöst werden.",
  "A járványban a betegek és az ápolók egyformán kimerülnek. Imádkozz gyógyulásért és kitartásért.": "In einer Epidemie sind die Kranken und die Pflegenden gleichermaßen erschöpft. Bete um Heilung und Ausdauer.",
  "Uram, eléd hozom {hely} lakóit, ahol betegség terjed. Gyógyítsd a betegeket, és állítsd meg a terjedést, ahogy csak te tudod. Adj erőt és védelmet az orvosoknak és az ápolóknak, akik nem mennek haza, és vigasztald azokat, akik már elveszítettek valakit.": "Herr, ich bringe dir die Menschen in {hely}, wo sich eine Krankheit ausbreitet. Heile die Kranken und halte die Ausbreitung auf, wie nur du es kannst. Gib den Ärzten und Pflegekräften Kraft und Schutz, die nicht nach Hause gehen, und tröste die, die schon jemanden verloren haben.",
  "Nem tudjuk pontosan, mi történik ott, de Isten tudja. Imádkozz azokért, akik benne vannak.": "Wir wissen nicht genau, was dort geschieht, aber Gott weiß es. Bete für die, die mitten darin sind.",
  "Uram, eléd hozom {hely} területét, ahol most baj van, és nem is tudom pontosan, milyen. Te tudod, és te látod minden embert ott. Légy velük, védd meg az életüket, és küldj segítséget időben.": "Herr, ich bringe dir die Region {hely}, wo gerade Not herrscht, und ich weiß nicht einmal genau, welche. Du weißt es, und du siehst jeden Menschen dort. Sei bei ihnen, bewahre ihr Leben und schick rechtzeitig Hilfe.",
});

