  "Helyes! A könyv és a fejezet is talált.": "Richtig! Buch und Kapitel stimmen.",
  "Közel! A {n}. fejezet volt.": "Knapp! Es war Kapitel {n}.",
  "A könyv jó, de a {n}. fejezet volt.": "Das Buch stimmt, aber es war Kapitel {n}.",
  // ===== 2026-11-02 Bible game 3, Igehely-párosító (owner TG 33698, card ec633681) =====
  "Igehely-párosító": "Stellen zuordnen",
  "Négy-öt ige és az igehelyeik összekeverve: párosítsd őket.": "Vier bis fünf Verse und ihre Stellen gemischt: ordne sie zu.",
  "Válassz egy igehelyet, majd az igét, amelyikhez tartozik.": "Wähle eine Stelle, dann den Vers, der dazugehört.",
  "Kész! Hibátlan.": "Fertig! Fehlerfrei.",
  "Kész! {n} tévesztéssel.": "Fertig, mit {n} Fehlgriff(en).",
  "Nem ez az. Próbáld újra.": "Das ist es nicht. Versuch es noch einmal.",
  // ===== 2026-11-02 Bible game 4, Könyvsorrend (owner TG 33698, card ec633681) =====
  "Könyvsorrend": "Bücherreihenfolge",
  "Egymás után következő könyvek összekeverve: rakd őket sorba. Felnőtt módban egy egész szövetség is kérhető.": "Aufeinanderfolgende Bücher gemischt: bringe sie in die richtige Reihenfolge. Im Erwachsenenmodus auch ein ganzes Testament.",
  "Mennyi könyv?": "Wie viele Bücher?",
  "Hat könyv": "Sechs Bücher",
  "Egész szövetség": "Ganzes Testament",
  "Rakd sorba az Ószövetség könyveit.": "Ordne die Bücher des Alten Testaments.",
  "Rakd sorba az Újszövetség könyveit.": "Ordne die Bücher des Neuen Testaments.",
  "Rakd sorba ezeket az egymás után következő könyveket.": "Ordne diese aufeinanderfolgenden Bücher.",
  "Nyomd hosszan a könyvet, és húzd a helyére.": "Halte ein Buch gedrückt und ziehe es an seinen Platz.",
  "Helyes! Mind a helyén.": "Richtig! Alles an seinem Platz.",
  "{n} könyv van a helyén a {m}-ből. A helyes sorrend:": "{n} von {m} Büchern stehen richtig. Die richtige Reihenfolge:",
  // ===== 2026-11-02 children's Bible games + game tiles (owner TG 7440, 7442, 7443) =====
  "Kicsiknek": "Für die Kleinen",
