  "Hol van a kis Mózes a kosárban?": "Wo ist der kleine Mose im Korb?",
  "Hol van Jézus a gyerekekkel?": "Wo ist Jesus mit den Kindern?",
  "Hol van a jó pásztor?": "Wo ist der gute Hirte?",
  "Hol van Dániel az oroszlánokkal?": "Wo ist Daniel bei den Löwen?",
  "Hol van a betlehemi csillag?": "Wo ist der Stern von Betlehem?",
  "Noé megépítette a bárkát, és Isten megmentette őt és az állatokat.": "Noah baute die Arche, und Gott rettete ihn und die Tiere.",
  "A kis Dávid Istenben bízott, és legyőzte az óriás Góliátot.": "Der kleine David vertraute Gott und besiegte den Riesen Goliat.",
  "Jónást elnyelte a nagy hal, de Isten megmentette.": "Ein großer Fisch verschluckte Jona, aber Gott rettete ihn.",
  "A kis Mózes egy kosárban úszott a folyón, és a királylány megtalálta.": "Der kleine Mose schwamm in einem Korb auf dem Fluss, und die Prinzessin fand ihn.",
  "Jézus szereti a gyerekeket, és megáldotta őket.": "Jesus liebt die Kinder, und er segnete sie.",
  "Jézus a jó pásztor: megkeresi és hazaviszi az elveszett bárányt.": "Jesus ist der gute Hirte: Er sucht das verlorene Schaf und trägt es heim.",
  "Dániel imádkozott, és Isten bezárta az oroszlánok száját.": "Daniel betete, und Gott verschloss den Löwen das Maul.",
  "A csillag megmutatta az utat a kis Jézushoz Betlehemben.": "Der Stern zeigte den Weg zum Jesuskind in Betlehem.",
  "Oroszlán": "Löwe",
