  "Vezetett ima: a felolvasott szöveg látható marad, és minden lépés megvárja, amíg a felolvasás véget ér.": "Geführtes Gebet: Der vorgelesene Text bleibt sichtbar, und jeder Schritt wartet, bis das Vorlesen beendet ist.",
  "Igetanuló: a nyomtatott vágási útmutató szerint minden csíkot a két vágójel között félúton kell elvágni.": "Verse lernen: Die gedruckte Schneideanleitung sagt jetzt, dass jeder Streifen in der Mitte zwischen seinen zwei Schnittmarken geschnitten wird.",
  "Gerah: tárca nélkül az app nem ígér letétet; a panel megmondja, hogy nincs tárca, és egy koppintással a tárcához visz. Az olvasási napok állapota a tárcával együtt átkerül a másik appba.": "Gerah: Ohne Wallet verspricht die App keine Hinterlegung mehr; das Feld sagt, dass keine Wallet da ist, und ein Tippen führt zur Wallet. Der Stand deiner Lesetage wird zusammen mit der Wallet in die andere App übertragen.",
  "Tablet: álló és fekvő elrendezés, a tablet elforgatható; a Biblia szövege kitölti a képernyőt, fekvő helyzetben a hivatkozások és jegyzetek oldalt nyílnak, és a kezdőlapon a világhelyzet csempéje jelenik meg.": "Tablet: Hoch- und Querformat, das Tablet darf gedreht werden; der Bibeltext füllt den Bildschirm, im Querformat öffnen sich Querverweise und Notizen seitlich, und die Startseite zeigt eine Kachel zur Weltlage.",
  "Világhelyzet térkép: új Támadás réteg, a terrortámadások és tömeges gyilkosságok is megjelennek a térképen és a vezetett ima világhelyzet-lépésében.": "Weltlage-Karte: neue Ebene Anschlag; Terroranschläge und Massenmorde erscheinen jetzt auf der Karte und im Weltlage-Schritt des geführten Gebets.",
  "Megvallások: a Szellemi fegyverek felvétele megvallás mindenkinek beépítve, a fegyverzet minden darabjához saját képpel.": "Bekenntnisse: das Bekenntnis „Die geistliche Waffenrüstung anlegen“ ist für alle eingebaut, mit einem eigenen Bild für jedes Stück der Rüstung.",
