// ===== 2026-11-08 Támogatás screen (card a0a2d3d6): store purchase only, never a web hint =====
Object.assign(window.PP_FORD_SZOTAR.de, {
  "Támogatás": "Unterstützung",
  "Választható összegek": "Betrag wählen",
  "Ha tetszik az alkalmazás, egy kisebb összeggel támogathatod a fejlesztését. A támogatás önkéntes, és semmit nem old fel: az alkalmazás nálad ugyanúgy működik, akár támogatsz, akár nem.": "Wenn dir die App gefällt, kannst du ihre Entwicklung mit einem kleinen Betrag unterstützen. Die Unterstützung ist freiwillig und schaltet nichts frei: Die App funktioniert bei dir genau gleich, ob du sie unterstützt oder nicht.",
  "A támogatás hamarosan elérhető.": "Die Unterstützung ist bald verfügbar.",
  "Köszönjük, hogy használod az alkalmazást, és hogy gondolsz ránk.": "Danke, dass du die App nutzt und an uns denkst.",
  "Köszönjük a támogatást!": "Danke für deine Unterstützung!",
  "A fizetés függőben van. Amint jóváhagyják, megérkezik a támogatásod.": "Die Zahlung ist ausstehend. Deine Unterstützung kommt an, sobald sie bestätigt ist."
});

// THE BUILT-IN CONFESSION "Szellemi fegyverek felvétele" IN THIS LANGUAGE (Marveen 30529, Thomas 30526: the confession
// list was empty outside Hungarian). Same 27 paragraphs as the Hungarian Part 2, the same 9 pictures in the same
// paragraphs (kepek: the sentence the picture stands before / after, and the piece name set in bold). The scripture after
// "it is written" is verbatim from the Bible the app ships for this language (Lutherbibel 1912), with its reference.
window.PP_MEGV_BEEPITETT_FORD = window.PP_MEGV_BEEPITETT_FORD || {};
window.PP_MEGV_BEEPITETT_FORD.de = {"cim": "Die geistliche Waffenrüstung anlegen", "szoveg": "Lieber himmlischer Vater, ich danke Dir für Deine Liebe. Ich danke Dir für Deine Treue, ich danke Dir für das Leben. Ich danke Dir für Dein Reden, das Du auch heute kundgetan hast, und ich danke Dir für Dein Wort. Ich danke Dir, Herr, für die geistlichen Waffen, die mächtigsten geistlichen Waffen. Ich danke Dir für Deinen Sohn, ich danke Dir für den Namen des Herrn Jesus Christus. Ich danke Dir, Jesus, für Dein Blut. Ich danke Dir, Herr, für die Erlösung, ich danke Dir, Herr, für das Heil, für die Vergebung der Sünden, für das Geschenk der Umkehr. Ich danke Dir, Herr, dass Du mich wiedergeboren hast; ich preise Dich, mein ewiger König. Ich danke Dir, Herr, für die Kirche, den Leib Christi, und für meine christliche Gemeinschaft, einen Teil der weltweiten Kirche. Ich danke Dir, Herr, für meine Brüder und Schwestern, für die, die ich kenne, und für die, die ich nicht kenne. Ich danke Dir für die, deren Namen ich weiß, und auch für die, deren Namen ich nicht weiß. Ich danke Dir, himmlischer Vater, für die Starken im Glauben und für die Schwachen im Glauben. Ich danke Dir, himmlischer Vater, für die, die frei sind, und auch für die, die gebunden sind.\n\nVater, jetzt trete ich vor Dich und lege die geistlichen Waffen fest an, und auch alles Übrige. Ich setze den Helm des Heils und der Hoffnung auf und nehme jeden Gedanken gefangen, damit jeder meiner Gedanken dem Herrn Jesus Christus gehorcht. Ich denke durch, welche Gedanken meinen Verstand von Gott abziehen, und spreche sie auch aus, um sie Wort für Wort im mächtigen und herrlichen Namen Jesu zu binden. Ich nehme Vollmacht über jede Sorge, über jeden unreinen, unzüchtigen Gedanken: Ich verbiete dir, in meinem Kopf umherzustreifen, ich gebiete dir, meinen Kopf, meinen Verstand zu verlassen. Im Namen Jesu fährst du aus mir aus und weichst von mir! Im Namen Jesu nehme ich Vollmacht über allen religiösen Nebel, alle Abstumpfung und Benommenheit und binde sie. Ich gebiete dir, von mir zu weichen, von mir herunter, aus mir heraus, aus meiner Familie, aus meinem Zuhause, im Namen des Herrn Jesus.\n\nIm Namen Jesu nehme ich Vollmacht über jeden Argwohn, jedes Misstrauen, jeden Zweifel und jede Skepsis gegenüber der Wahrheit und den Dienern Gottes. Ich binde dich und gebiete dir, von mir herunter zu weichen, aus mir heraus, aus meiner Familie, aus meinem Zuhause, aus meinen menschlichen Beziehungen, im Namen Jesu! Im Namen des Herrn Jesus nehme ich Vollmacht über jedes Erschrecken, jede Einschüchterung und jedes Grauen. Im Namen des Herrn Jesus gebiete ich dir, aus mir zu weichen, aus meiner Familie, aus meinem Zuhause, im Namen Jesu. Ich reiße nieder, sage mich los und werfe aus meinem Verstand jeden Gedanken, jede Höhe und jede Festung hinaus, die sich gegen die Erkenntnis Gottes erhoben hat und dem Erkennen Gottes im Weg steht. Im Namen des Herrn Jesus nehme ich Vollmacht, ich gebiete: Weiche aus meinem Kopf! Jede Lüge, ich binde dich im Namen Jesu! Ihr bösen Geister der Falschheit, der Heuchelei, der Unreinheit, der Unzucht, der Untreue, des Ehebruchs, der Pornografie, der Wollust, der Ausschweifung, des Nudismus, der Homosexualität, der Blutschande, der Schamlosigkeit, des Sadismus und der Perversion, verlasst meinen Kopf, meinen Verstand, meine Gedanken! Ihr fahrt aus mir aus, weicht von mir, aus meiner Familie, aus meinem Zuhause, aus meinen Kindern, aus meinen Eltern, aus meinem Mann / meiner Frau, aus meinen menschlichen Beziehungen, aus meinen Geschwistern, aus meiner Gemeinde und aus meiner Stadt, im mächtigen, herrlichen und heiligen Namen Jesu, durch die Kraft des Heiligen Geistes!\n\nIm Namen Jesu nehme ich Vollmacht über alle bösen Geister des Streits, der Rivalität, des Neides, der Bitterkeit, des Selbstmitleids, der Empfindlichkeit, der Überempfindlichkeit, der Gekränktheit, der Kränkbarkeit, des Grolls, des Zorns, des Giftes, der Böswilligkeit, des Hasses, der Missgunst, der Rachsucht, der Unversöhnlichkeit, der mörderischen Wut und der mörderischen Gedanken, die gegen mich und gegen meine Gemeinde kommen, und binde sie! Ich binde euch und gebiete euch, aus mir zu weichen, von mir herunter; weicht von uns, verlasst uns, im mächtigen und herrlichen Namen Jesu, durch die Kraft des Heiligen Geistes!\n\nIm Namen des Herrn Jesus nehme ich Vollmacht über jeden bösen Geist des Hochmuts, der Eitelkeit, der Einbildung, des Stolzes, der Selbstgefälligkeit, des Egoismus und der Ichbezogenheit, der gegen mich und gegen meine Gemeinde kommt; über jeden bösen Geist der Hoffnungslosigkeit, der Entmutigung, der Lethargie, der Depression, der Melancholie, des Kummers, der Traurigkeit, der Lustlosigkeit, der Düsterkeit, der Verdrossenheit, des Pessimismus und der Aussichtslosigkeit! Ich binde dich und gebiete dir, von mir herunter zu weichen, aus mir heraus! Böser Geist der Niederlage und des Versagens, du fährst aus von diesem Ort, du weichst von meinem Kopf, von meinem Verstand!\n\nIch segne dich, mein Verstand, dass du nach dem trachtest, was droben ist, nach dem, was wahrhaftig, keusch, herrlich und ehrbar ist. Ist etwa eine Tugend, ist etwa ein Lob, dem denke nach, mein Verstand.\n\nIch danke Dir, Herr, dass Du mich wiedergeboren hast, dass ich eine lebendige Hoffnung im Herrn habe. Du errettest mich, Herr Jesus Christus, denn auf Dich hoffe ich, Du bist der sichere und feste Anker meiner Seele. Die Hoffnung bewahrt mich, und die Hoffnung lässt mich auch heute nicht zuschanden werden. Eine gute Zukunft erwartet mich, Herr, denn Du, Jesus Christus, bist der Hohepriester meiner kommenden Tage, mein Fürsprecher, mein Anwalt. Du bist es, Herr, der zur Rechten des Vaters für mich bittet und eintritt. Amen. Das ist der Helm meines Heils und meiner Hoffnung.\n\nIm Namen des Herrn Jesus nehme ich Vollmacht und lege den Panzer der Gerechtigkeit und der Rechtfertigung an. Ich ziehe Kraft und Vollmacht an, Entschlossenheit, Mut, Tatkraft, Initiative, Männlichkeit. (Frauen sprechen das letzte Wort nicht.) Ich liebe die Gerechtigkeit und hasse die Gottlosigkeit, darum hast Du, Vater, mich gesalbt mit dem Öl der Freude mehr als meine Gefährten. Es steht geschrieben: Der Geist des HERRN ist bei mir, darum, daß er mich gesalbt hat; er hat mich gesandt, zu verkündigen das Evangelium den Armen, zu heilen die zerstoßenen Herzen, zu predigen den Gefangenen, daß sie los sein sollten, und den Blinden das Gesicht und den Zerschlagenen, daß sie frei und ledig sein sollen, und zu verkündigen das angenehme Jahr des HERRN. (Lk 4,18-19) Christus ist der Gesalbte, und Christus ist in mir, darum bekenne ich es.\n\nIm Namen des Herrn Jesus nehme ich Vollmacht über den bösen Geist der Anklage, der Verdammung, der Schuld, des Schuldgefühls, der falschen Gewissensbisse, der Schmähung, der Lästerung, der Verachtung, der Herabsetzung und der Verunglimpfung, der gegen mich und gegen meine Gemeinde kommt. Ich binde dich und gebiete dir im herrlichen Namen Jesu, von mir zu weichen, aus mir heraus, von mir herunter, von uns! Du verlässt mich, ihr verlasst meine Familie, mein Zuhause, meinen Arbeitsplatz, meine menschlichen Beziehungen, meine Gemeinde, ihr verlasst den Gottesdienst, im mächtigen Namen Jesu Christi, durch die Kraft des Heiligen Geistes.\n\nEs steht geschrieben: So ist nun nichts Verdammliches an denen, die in Christo Jesu sind, die nicht nach dem Fleisch wandeln, sondern nach dem Geist. (Röm 8,1) Ich bin in Christus Jesus, ich lebe nach dem Geist und wandle nicht nach dem Fleisch. Es steht geschrieben: Wer will die Auserwählten Gottes beschuldigen? Gott ist hier, der da gerecht macht. Wer will verdammen? (Röm 8,33-34) Gott hat mich gerecht gemacht. Es steht geschrieben: Und sie haben ihn überwunden durch des Lammes Blut und durch das Wort ihres Zeugnisses (Offb 12,11). Auch heute überwinde ich den Verkläger durch das Blut des Lammes, durch die Kraft des Wortes meines Zeugnisses, durch mein hingegebenes Leben. Ich bin die Gerechtigkeit Gottes, das Licht der Welt, das Salz der Erde, und ich bin ein Wohlgeruch Christi.\n\nIm mächtigen Namen des Herrn Jesus nehme ich Kraft und Vollmacht über den bösen Geist der Untauglichkeit, der Unwürdigkeit, der Minderwertigkeitsgefühle, der Verworfenheit, des Übergangenwerdens, des Ausgestoßenseins, des Ausgeschlossenseins, des Gemiedenwerdens, der Einsamkeit, der Benachteiligung, des Überflüssigseins, der Vereinsamung, der Frustration und der Lieblosigkeit, der gegen uns und gegen unsere Gemeinde kommt. Ich binde dich und gebiete dir: Weiche von mir, von uns! Verlasst meine Geschwister, die Versammlung, die Gemeinde, im Namen Jesu Christi, durch die Kraft des Heiligen Geistes! Im Namen des Herrn Jesus steht geschrieben, dass ich ein geliebtes Kind Gottes bin. Darum bin ich nicht frustriert, denn ich bin ein seliger Mensch im Herrn. Ich vertraue, denn mich hungert und dürstet nach der Gerechtigkeit. Der Herr macht mich satt. Ich bin ein seliger Mensch, denn der Herr hat mich erwählt. Ich bin ein seliger Mensch, denn Er hat meinen Namen in das Buch des Lebens geschrieben. Ich bin ein seliger Mensch, denn mein Herz ist rein, und ich werde Gott schauen, denn der Herr hat mein Herz gereinigt.\n\nIm Namen Jesu Christi nehme ich Vollmacht und Kraft über die Furcht, die Angst und das Grauen, die gegen uns und gegen unsere Gemeinde kommen: über die Furcht vor Zurückweisung, vor Versagen und vor Beschämung; über die Furcht vor Ausstoßung, vor Ausgrenzung und vor Ächtung; über die Furcht vor Einsamkeit, vor Benachteiligung, vor dem Überflüssigsein und vor Vereinsamung; über die Furcht vor dem Fallen, vor dem Tod, vor der Hölle und vor dem Scheitern; über die Furcht vor Dämonen, vor Krankheit, vor Fluch, vor Zauberei und vor seelischen Gebeten. Ich nehme Vollmacht über dich und binde dich. Ich gebiete dir: Weiche von mir herunter, weiche von mir, weiche aus mir heraus! Ihr verlasst mich, meine Geschwister, meine Familie, mein Zuhause und auch den Gottesdienst, im mächtigen Namen des Herrn Jesus Christus, durch die Kraft des Heiligen Geistes! Denn es steht geschrieben: die Liebe Gottes ist ausgegossen in unser Herz durch den heiligen Geist, welcher uns gegeben ist (Röm 5,5), und: die völlige Liebe treibt die Furcht aus (1Joh 4,18). Diese Liebe treibt jede Furcht aus mir aus, verdrängt sie aus mir! (Bekenntnis: Psalmen 27, 91, 18)\n\nIch umgürte meine Lenden mit Aufrichtigkeit: mit Geradheit, Reinheit, Hass gegen die Sünde, Hass gegen das Böse, Liebe zum Guten, Langmut. Ich ziehe Barmherzigkeit an, Erbarmen, Güte, Treue, Sanftmut, Selbstbeherrschung, Demut, brüderliche Liebe, Freundlichkeit und Liebenswürdigkeit; ich ziehe Christus an. Ich ziehe den Charakter Christi an, Sein Wesen, die Gabe und die Frucht des Heiligen Geistes.\n\nIm mächtigen Namen Jesu Christi lege ich den alten Menschen ab, mit seiner Verdorbenheit, seiner Arglist, seinen Begierden, seinen Leidenschaften, seinen Flüchen, seiner Verfluchtheit, seinen Krankheiten, seinen Schwachheiten, seiner Müdigkeit, seinen Depressionen und seiner Hoffnungslosigkeit. Ich ziehe die neue Natur Christi an, die auch heute erneuert wird, Herr Jesus Christus, zu Deinem Ebenbild und zu Deiner Herrlichkeit, durch das Wort Gottes und die Kraft des Heiligen Geistes. Ich vergebe jedem, der an mir sündigt. Im Namen Jesu Christi vergebe ich den folgenden Menschen: ………… (man muss sie bekennen und ihre Namen aussprechen) ……. Und zuletzt vergebe ich auch mir selbst.\n\nIm Namen des Herrn Jesus Christus nehme ich Kraft und Vollmacht über die satanischen bösen Geister der Kraftlosigkeit, der Schwäche, der Unsicherheit, der Mutlosigkeit, der Befangenheit, der Schlappheit, der Feigheit, der Unentschlossenheit, des Unglücks, der Unfälle und der Unfallverursachung, die gegen mich und gegen meine Gemeinde kommen. Ich binde euch im Namen des Herrn Jesus und gebiete euch, von uns zu weichen, von mir, von meiner Familie, von meinem Zuhause, von meinem Arbeitsplatz, von meinen Kollegen! Ich gebiete euch zu weichen: alle Ungeduld, Unbarmherzigkeit, Mitleidlosigkeit, Gesetzlichkeit, Härte, Kritiksucht, Hartherzigkeit! Ich binde dich, Unversöhnlichkeit, Groll, Bitterkeit, Selbstmitleid! Ich gebiete dir, von mir zu weichen! Ihr verlasst mein Leben, mein Zuhause, meine Familie, meine Beziehungen, die Häuser, das Volk Gottes, den Gottesdienst, die Gemeinde, im Namen Jesu Christi, durch die Kraft des Heiligen Geistes! Amen.\n\nIch segne meine Nieren, jedes Glied meines Leibes, meine Familienangehörigen, meine Frau / meinen Mann, meine Kinder, meine Geschwister und meine Verwandten zur Reinheit, zur Heiligkeit, zur Gerechtigkeit, zum Vertrauen gegenüber den Dienern Gottes, zum Gehorsam. Ich habe von Dir, Herr, ein neues Herz empfangen, und dieses neue Herz ist wie Deines: sanftmütig und demütig. Darum erbe ich das Erdreich, und Du erhöhst mich.\n\nIch beschuhe meine Füße mit der Bereitschaft für das Evangelium des Friedens. Ich nehme mir vor, auch heute gute Nachricht, Freude, Frieden und Befreiung zu verkündigen. Zu den Füßen gehört das Gehetztsein. Darum trete ich im Namen des Herrn Jesus die Gewalttätigkeit, die Rastlosigkeit, die Unruhe, das Gehetztsein und die Getriebenheit von mir ab, den Dämon des Umherstreifens, die „vergiftete Maus“, die nicht stillhalten kann, den Dämon des Kobolds, der nie zur Ruhe kommt. Diese trete ich ab und treibe sie aus! Ich verpflichte mich: Wenn ich dieses Schuhwerk anziehe, will ich aus Barmherzigkeit, aus der Liebe Gottes und aus Frieden das Evangelium Gottes sagen und Zeugnis geben, wenn ich auch heute Gelegenheit dazu habe, und ich werde vor dieser Situation nicht davonlaufen und mich ihr nicht entziehen. Es steht geschrieben: Wie lieblich sind die Füße derer, die den Frieden verkündigen, die das Gute verkündigen! (Röm 10,15) Darum sind meine Füße lieblich im Namen Jesu Christi. Amen. Aber es steht auch geschrieben: Er hat nicht Lust an der Stärke des Rosses noch Gefallen an eines Mannes Schenkeln. (Ps 147,10)\n\nIm Namen des Herrn Jesus Christus nehme ich Vollmacht über jeden bösen Geist des Unfriedens, der Verfolgung, der Getriebenheit, der Unruhe, der Rastlosigkeit, der Nervosität, der Feindseligkeit, des Unruhestiftens, des Streitens, des Zankens, des Gerangels, des Gezänks, der Spaltung, der Plumpheit, der Rohheit, der Grobheit, der Gewöhnlichkeit und der Ungehobeltheit, der gegen uns, gegen mich und gegen unsere Gemeinde kommt. Ich binde dich und gebiete dir, von uns zu weichen, aus meinem Zuhause, aus meiner Familie, aus meinen Beziehungen, im Namen des Herrn Jesus Christus, durch die Kraft des Heiligen Geistes.\n\nIch nehme Kraft, und ich nehme Vollmacht, und ich segne meine Füße, meine Beziehungen, unsere Versammlungen, die Gottesdienste und mein Zuhause zum Frieden, zum Wandel auf dem Weg des Herrn, zur Freude und zur Fröhlichkeit. Es steht geschrieben: Sehet, ich habe euch Macht gegeben, zu treten auf Schlangen und Skorpione, und über alle Gewalt des Feindes (Lk 10,19), und diese sind geistlich. Und ich erkläre, dass sie mir nicht schaden können und gegen mich wirkungslos sind. Jesus Christus ist der Herr des Friedens, und es steht geschrieben: Aber der Gott des Friedens zertrete den Satan unter eure Füße in kurzem. (Röm 16,20)\n\nIch ergreife den Schild des Glaubens, mit dem ich im Namen Jesu Christi alle feurigen Pfeile Satans auslösche. In mir wohnt ein Glaube, der die Welt überwindet. Ich erkläre, dass ich auch heute die Welt überwinde und was in der Welt ist: die Lust des Fleisches, die Lust der Augen, den Hochmut und die Prahlerei des Lebens, Versuchungen, Fluch, Ängste, Hass, Beklemmungen, Schrecken, Zynismus, Kritiksucht, Unglauben; dumme Gedanken, dieses Bekenntnis nicht zu sprechen. Ich bin kein größerer Mensch, wenn ich dieses Bekenntnis verweigere. Ich bin ein Kind Gottes. Es steht geschrieben: Es sei denn, daß ihr umkehret und werdet wie die Kinder, so werdet ihr nicht ins Himmelreich kommen. (Mt 18,3) Wenn ich mich über das Wort Gottes erhebe, wird der Stein so auf mich fallen, wie beim Propheten Daniel geschrieben steht: Solches sahst du, bis daß ein Stein herabgerissen ward ohne Hände; der schlug das Bild an seine Füße, die Eisen und Ton waren, und zermalmte sie. (Dan 2,34) Darum habe ich beschlossen, mich mit weichem Herzen unter das Wort Gottes zu beugen. Herr, wenn Du es sagst, dann tue ich es mit Freude. Was Du auch sagst, Herr, ich tue es, weil Du es sagst. Ich liebe das Wort Gottes und tue es. Ein Schaf, das nicht weidet, geht zugrunde. Darum habe ich beschlossen, das Wort Gottes zu essen; jeden Tag nähre ich meinen Geist. Im Namen des Herrn Jesus überwinde ich durch den Glauben die ungläubigen Gedanken. Im Namen Jesu Christi widerstehe ich durch den Glauben dem Bösen, und er flieht von mir, denn es steht geschrieben: Widerstehet dem Teufel, so flieht er von euch (Jak 4,7). Durch den Glauben trachte ich nach dem Reich Gottes und nach Seiner Gerechtigkeit, und Du erfüllst mich, Du deckst all meinen Bedarf. Durch den Glauben habe ich meine Lust an Dir, Herr Jesus Christus. Du gibst mir, was mein Herz wünscht. Durch den Glauben gehe ich von Kraft zu Kraft, von Sieg zu Sieg, von Herrlichkeit zu Herrlichkeit. Durch den Glauben rede ich in neuen Zungen, durch den Glauben weissage ich, im mächtigen Namen des Herrn Jesus Christus. Durch den Glauben lege ich im Namen des Herrn Jesus Christus den Kranken die Hände auf, und sie werden gesund. Durch den Glauben treibe ich im Namen des Herrn Jesus Christus Dämonen aus. Wenn ich etwas Tödliches trinke oder Schlangen aufhebe, schaden auch sie mir nicht. Durch den Glauben, aus Gnade, bewahrt mich mein Gott durch Seine Macht zum Heil. Amen. (Bekenntnis: Hebräer 11, die Stellen über die Helden des Glaubens.)\n\nIm Namen des Herrn Jesus unterstelle ich mich dem Wort Gottes und übergebe Gott besonders meine Zunge, meinen Mund. Ich segne dich, mein Mund, im Namen Jesu, dass das Reden Gottes, das Wort Gottes, auch heute aus dir hervorgeht wie das zweischneidige Schwert, wie der Hammer, der Felsen zerschmeißt, Geist und Leben, verzehrendes Feuer, Wahrheit, Frieden, durch die Kraft, die Vollmacht und die Salbung des Heiligen Geistes. Es soll den Hörenden und auch mir zur Wiedergeburt, zu Zeichen und Wundern werden, im mächtigen und herrlichen Namen Jesu Christi. Amen. Halleluja!\n\nÜber all dies ziehe ich das Gewand und den Mantel des Lobes an, und die Verzagtheit ist von mir gewichen, husch! Im Namen Jesu. Halleluja!\n\nDiese Bekenntnisse muss man jeden Tag sprechen. Auch über die Tage und die Feste muss man im Namen Jesu Vollmacht nehmen. Seit Jahrhunderten beherrschen böse Geister die Tage, die Feste, Städte, Dörfer, Länder, Völker und Menschen. Mit dem Wort Gottes muss man Vollmacht über geistliche Festungen nehmen. Ich stehe ohnehin im Krieg! Nur wenn ich jeden Tag die geistlichen Waffen anlege, können mir diese bösen Geister nicht schaden. Über meine Familie, mein Zuhause, meine Arbeit und alles, was ich habe, muss man den Schutz des Herrn Jesus stellen und Engel bitten, dass sie kommen und über uns wachen.\n\nIm Namen des Herrn Jesus nehme ich durch die Kraft des Heiligen Geistes Vollmacht und binde jede satanische Macht über meinem heutigen Tag! Mein Leben, mein Zuhause, meine Familie stelle ich unter den Schutz des Blutes Jesu.\n\nIm Namen des Herrn Jesus binde ich die Zauberei, die Behexung, den Geist Isebels, den religiösen Nebel, den Antichristen, den Materialismus. Ihr bösen Geister des Unglaubens, des Fluches, der Armut, des falschen Geistes, des falschen Schmerzes, des lügnerischen Symptoms, der Krankheit, des Zweifels, der Kraftlosigkeit, des Horoskops, des Okkultismus, des Yoga, des Todes, der Hölle und der Verworfenheit, im Namen Jesu binde ich euch und gebiete euch: Fahrt aus mir aus, weicht von mir, von meiner Familie, von meinem Zuhause, von meinem Leben, von meinem Schicksal, aus meinem Volk, aus meiner Nation, im Namen Jesu, durch die Kraft des Heiligen Geistes. Meinen heutigen Tag übergebe ich der Herrlichkeit Gottes.\n\nBekenntnis:\n\nMein Leib ist der Tempel des Heiligen Geistes, erlöst, gereinigt und geheiligt durch das Blut Jesu. Meine Glieder sind Teile des Leibes, Waffen der Gerechtigkeit, die Gott übergeben sind zu Seinem Dienst und zu Seiner Herrlichkeit. Ich halte mein Auge auf ein Ziel gerichtet, und mein ganzer Leib ist voll Licht. Der Teufel hat keinen Raum in mir, keine Macht über mich und keine berechtigten Ansprüche gegen mich. Das Blut Jesu hat alles geordnet; Er hat den Satan durch das Blut des Lammes besiegt. Mein Zeugnis ist dieses: Jesus selbst hat meine Sünden hinaufgetragen an Seinem Leibe auf das Holz, auf dass ich, der Sünde abgestorben, der Gerechtigkeit lebe; durch Seine Wunden bin ich heil geworden. Amen. Ehre sei dem Herrn Jesus Christus, der zur Rechten des Vaters sitzt!", "kepek": [{"f": "10-feher-ruha.webp", "mondat": "ich danke Dir für Deine Liebe", "utana": true}, {"f": "1-sisak.webp", "mondat": "Ich setze den Helm des Heils und der Hoffnung auf", "nev": "Helm des Heils und der Hoffnung"}, {"f": "2-mellvert.webp", "mondat": "lege den Panzer der Gerechtigkeit", "nev": "Panzer der Gerechtigkeit und der Rechtfertigung"}, {"f": "3-ov.webp", "mondat": "Ich umgürte meine Lenden mit Aufrichtigkeit", "nev": "Lenden mit Aufrichtigkeit"}, {"f": "4-saru.webp", "mondat": "Ich beschuhe meine Füße", "nev": "Bereitschaft für das Evangelium des Friedens"}, {"f": "5-pajzs.webp", "mondat": "Ich ergreife den Schild des Glaubens", "nev": "Schild des Glaubens"}, {"f": "6-kard.webp", "mondat": "unterstelle ich mich dem Wort Gottes", "nev": "zweischneidige Schwert"}, {"f": "7-palast.webp", "mondat": "ziehe ich das Gewand und den Mantel des Lobes an", "nev": "Gewand und den Mantel des Lobes"}, {"f": "9-tiszt.webp", "mondat": "Über all dies ziehe ich", "utana": true}]};


