  "Térkép: a műholdkép tovább nagyítható szürke „nincs adat” mező nélkül.": "Karte: Das Satellitenbild lässt sich weiter vergrößern, ohne graues Feld „keine Daten“.",
  "Visszajelzés: egy képernyőn elfér; a „Még mindig hibás” saját ablakot nyit szövegmezővel; a morze-nézet mérési adatokat csatol.": "Rückmeldung: passt auf einen Bildschirm; „Immer noch fehlerhaft“ öffnet ein eigenes Fenster mit Textfeld; die Morse-Ansicht hängt Messdaten an.",
  "Wordlight: a kezdőlapon a csempék alatt megjelenik a napi olvasási cél sávja.": "Wordlight: Auf der Startseite erscheint unter den Kacheln der Balken des täglichen Leseziels.",
  "Biblia-kereső: a keresett szó kiemelt színnel látszik a találatokban.": "Bibelsuche: Das gesuchte Wort erscheint in den Treffern farbig hervorgehoben.",
  "Biblia-térkép: internettel a világtérkép letöltése nélkül is látszik az alaptérkép (pl. Midián alatt a tenger, a part és a városok).": "Bibelkarte: Mit Internet ist die Grundkarte auch ohne Download der Weltkarte sichtbar (z. B. unter Midian das Meer, die Küste und die Städte).",
  "Hirdetések: ha a telefon tárolójában hibás vagy üres kép maradt, az app újra letölti.": "Werbung: Ist im Speicher des Telefons ein fehlerhaftes oder leeres Bild geblieben, lädt die App es erneut herunter.",
  "Frissítés: ha az app nem éri el a frissítési listát, 30 másodperc múlva újra próbálja, és a hibát naplózza.": "Update: Erreicht die App die Update-Liste nicht, versucht sie es nach 30 Sekunden erneut und protokolliert den Fehler.",
  "Biblia: a felolvasó panelen a háttérzene gombjain a feliratok kiférnek, a panel nem csúszik oldalra.": "Bibel: Im Vorlese-Panel passen die Beschriftungen auf den Tasten der Hintergrundmusik, das Panel rutscht nicht zur Seite.",
  "Biblia: hosszú, több fejezeten át tartó olvasásnál a szöveg alja nem homályosodik el.": "Bibel: Bei langem Lesen über mehrere Kapitel wird das untere Ende des Textes nicht unscharf.",
  "Biblia: új olvasási tervek: Ószövetség és Újszövetség párhuzamosan (napi egy-egy fejezet), Próféciák 41 nap alatt, Jézus példázatai, A Biblia imádságai, Pál levelei 30 nap alatt.": "Bibel: neue Lesepläne: Altes und Neues Testament parallel (täglich je ein Kapitel), Prophezeiungen in 41 Tagen, Die Gleichnisse Jesu, Die Gebete der Bibel, Die Paulusbriefe in 30 Tagen.",
  "Biblia: új elhivatottság-oldal a statisztikákkal; a PrepperPapa kezdőlapján a Biblia csempék alatt a napi olvasási idő, a fejezetnézetben kerek lebegő gyűrű; az aktuális könyvet vastag zöld keret jelöli.": "Bibel: neue Seite Hingabe mit den Statistiken; auf der Startseite von PrepperPapa unter den Bibel-Kacheln die tägliche Lesezeit, in der Kapitelansicht ein runder schwebender Ring; das aktuelle Buch markiert ein dicker grüner Rahmen.",
  "Wordlight: az első megnyitáskor a nyitókép tovább látszik, és lágy áttűnéssel adja át a helyét a Bibliának.": "Wordlight: Beim ersten Öffnen ist der Startbildschirm länger zu sehen und macht mit einer sanften Überblendung der Bibel Platz.",
  "Frissítés: ha a telefon a Wi-Fi-t „internet nélkülinek” látja, és a letöltés nem indul el, az app 20 másodperc után maga tölti le a frissítést.": "Update: Wenn das Telefon das WLAN als „ohne Internet“ einstuft und der Download nicht startet, lädt die App das Update nach 20 Sekunden selbst herunter.",
