  "Gerah: minden nap, amikor eléred a napi bibliaolvasási célt, Gerah-t bányászol (10 perces céltól 1, 20 perctől 2, 30 perctől 3 gerah-t), Biblia prémium nélkül is; a tárcában leírás mutatja, hogyan gyűjthetsz Gerah-t.": "Gerah: An jedem Tag, an dem du das tägliche Bibelleseziel erreichst, schürfst du Gerah (ab 10 Minuten Ziel 1, ab 20 Minuten 2, ab 30 Minuten 3 gerah), auch ohne Bibel Premium; in der Brieftasche zeigt eine Beschreibung, wie du Gerah sammeln kannst.",
  "Beállítások: feliratkozhatsz a hírlevélre; a Wordlightban a fiók és a hírlevél is itt érhető el. A fiók törlése a hírlevélről is leiratkoztat.": "Einstellungen: Du kannst den Newsletter abonnieren; in Wordlight sind Konto und Newsletter ebenfalls hier erreichbar. Das Löschen des Kontos meldet auch vom Newsletter ab.",
  "Belépés: a belépőkódot hozó levélben egy gomb egyből megnyitja az appot.": "Anmeldung: In der E-Mail mit dem Anmeldecode öffnet eine Taste direkt die App.",
  "Helyi szobák (Wi-Fi, Bluetooth): egy üzenetet vagy tagot hosszan nyomva jelenteni vagy letiltani lehet; a letiltottak a Beállításokban oldhatók fel.": "Lokale Räume (WLAN, Bluetooth): Durch langes Drücken auf eine Nachricht oder ein Mitglied lässt es sich melden oder blockieren; Blockierte lassen sich in den Einstellungen freigeben.",
