  "Térkép: ha a saját térkép üresen maradna, az app magától helyreállítja.": "Karte: Würde die eigene Karte leer bleiben, stellt die App sie selbst wieder her.",
  "Esésérzékelés: kikapcsolt képernyőnél is pontosan méri a zuhanás idejét.": "Sturzerkennung: misst die Fallzeit auch bei ausgeschaltetem Bildschirm genau.",
