  "Névjegy: új link az app adatkezelési tájékoztatójához, a PrepperPapában és a Wordlightban is.": "Über die App: neuer Link zur Datenschutzerklärung der App, in PrepperPapa und in Wordlight.",
  "Wordlight: csak azokat az engedélyeket kéri, amelyeket ténylegesen használ.": "Wordlight: fragt nur die Berechtigungen an, die es tatsächlich nutzt.",
