  "Biblia: a fogaskerék körüli napi olvasásidő-gyűrű újra a hátralévő időt mutatja: reggel tele, olvasás és hallgatás közben fogy, a napi célnál arany.": "Bibel: Der Ring der täglichen Lesezeit um das Zahnrad zeigt wieder die verbleibende Zeit: morgens voll, beim Lesen und Hören nimmt er ab, beim Tagesziel golden.",
