  "Wordlight: a Névjegy a Wordlight adatait mutatja.": "Wordlight: Über die App zeigt die Daten von Wordlight.",
  "Wordlight: havonta egyszer jelzi, hány Gerah-t kaphattál volna a PrepperPapában a teljesített olvasási napjaidért.": "Wordlight: zeigt einmal im Monat an, wie viel Gerah du in PrepperPapa für deine erfüllten Lesetage hättest bekommen können.",
  "Biblia: az automatikus görgetés lágyan indul, lágyan vált sebességet és lágyan áll meg; koppintásra a szöveg finoman lefékez, húzásra azonnal megáll.": "Bibel: Das automatische Scrollen startet sanft, wechselt die Geschwindigkeit sanft und hält sanft an; beim Tippen bremst der Text sanft ab, beim Ziehen hält er sofort an.",
  "Biblia: mind a nyolc csempe új, egységes vonalas ikont kapott, nagyobb méretben, a PrepperPapában és a Wordlightban is.": "Bibel: Alle acht Kacheln haben ein neues, einheitliches Liniensymbol bekommen, in größerer Größe, in PrepperPapa und in Wordlight.",
