  "Wordlight: az app neve mindenhol Wordlight, új indítóikon lámpás nélkül, alatta BIBLIA felirattal.": "Wordlight: Der Name der App ist überall Wordlight, neues Startsymbol ohne Laterne, darunter die Beschriftung BIBLIA.",
  "Wordlight: a nyitólapon nincs ébresztő és fogaskerék; az ébresztő az olvasási tervnél, a beállítások az olvasásból érhetők el.": "Wordlight: Auf der Startseite gibt es keinen Wecker und kein Zahnrad; der Wecker ist beim Leseplan, die Einstellungen sind aus dem Lesen erreichbar.",
