  "A nyelvválasztóban a magyar minden nyelven Magyar néven szerepel.": "In der Sprachauswahl steht Ungarisch in allen Sprachen unter dem Namen Magyar.",
  "Felolvasás: a köd sarkai lekerekítve, nincs szögletes sarok.": "Vorlesen: Die Ecken des Nebels sind abgerundet, keine eckigen Ecken.",
